/* gerado por _fonte/enem/gerar.py: perguntas dos moradores da Ilha ENEM no Mundo. Não edite à mão. */
window.ENEM_ILHA_PERGUNTAS = {"bio":{"tema":"Biologia","ic":"🧬","lista":[{"enun":"Complete: Grupo de plantas com flores e frutos: _____. Com sementes nuas: gimnospermas. Primeiras com vasos condutores: pteridófitas.","alts":["timina","xilema","floema","angiospermas"],"certa":3,"coment":"Grupo de plantas com flores e frutos: <b>angiospermas</b>. Com sementes nuas: <b>gimnospermas</b>. Primeiras com vasos condutores: <b>pteridófitas</b>."},{"enun":"Qual alternativa explica <b>Briófitas, pteridófitas, gimnospermas, angiospermas: o que cada grupo \"inventa\"</b>?","alts":["Auxina: crescimento, fototropismo (cresce em direção à luz) e dominância apical. Etileno: amadurecimento dos frutos (por isso banana madura acelera as outras).","Briófitas: sem vasos (musgos). Pteridófitas: vasos condutores (samambaias). Gimnospermas: sementes nuas (pinheiros, araucária). Angiospermas: flores e frutos.","Xilema: seiva bruta (água e sais) da raiz para as folhas. Floema: seiva elaborada (açúcares) das folhas para o resto da planta.","Eucariontes heterotróficos por absorção, parede de quitina, reserva glicogênio. Decompositores, fazem fermentação (leveduras) e antibióticos (Penicillium)."],"certa":1,"coment":"💡 \"Musgo sem Vaso, Samambaia com Vaso, Pinheiro com Semente, Angiosperma com Fruto\" (V-S-F na ordem)."},{"enun":"Qual alternativa explica <b>O que é eutrofização</b>?","alts":["Primária: começa em área nunca habitada (rocha nua), com pioneiras como liquens. Secundária: em área já habitada e perturbada (incêndio, roça abandonada). Comunidade final = clímax.","Excesso de nutrientes (esgoto, fertilizantes com N e P) → explosão de algas → algas morrem → decompositores aeróbios consomem o O2 → morte de peixes. Aumenta a DBO.","Diminui (cerca de 10% passa adiante). O resto se perde como calor na respiração. Por isso cadeias são curtas.","Quantidade de O2 que os microrganismos consomem para decompor a matéria orgânica da água. DBO alta = água muito poluída por matéria orgânica."],"certa":1,"coment":"💡 \"Excesso de comida mata de fome de ar\": nutriente demais → falta O2."},{"enun":"Qual alternativa explica <b>Amensalismo (antibiose)</b>?","alts":["Os nutrientes estão na biomassa e na serrapilheira, reciclados rapidamente. Desmatado, o solo fica exposto à lixiviação pelas chuvas e perde fertilidade.","Quantidade de O2 que os microrganismos consomem para decompor a matéria orgânica da água. DBO alta = água muito poluída por matéria orgânica.","Uma espécie libera substância que prejudica outra (-/0). Ex.: fungo Penicillium e bactérias; maré vermelha.","Campos do sul do RS, vegetação rasteira (gramíneas), clima subtropical. Ameaçado pela pecuária extensiva, silvicultura (eucalipto) e arenização."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Fotossíntese: equação geral e onde ocorre</b>?","alts":["Transporte ativo que joga 3 Na+ para fora e traz 2 K+ para dentro, gastando ATP. Mantém o potencial de membrana (essencial nos neurônios).","6CO2 + 6H2O + luz → C6H12O6 + 6O2, no cloroplasto. O O2 liberado vem da água (fotólise).","Crossing-over (permutação) na prófase I e segregação independente dos cromossomos homólogos na anáfase I.","Clara (tilacoides): luz quebra água, libera O2, produz ATP e NADPH. Química/escura (estroma): ciclo de Calvin fixa CO2 em glicose usando ATP e NADPH."],"certa":1,"coment":"💡 A fotossíntese é a respiração \"de trás para frente\": CO2 + H2O entram, glicose + O2 saem."},{"enun":"Qual alternativa explica <b>Por que rotação de culturas com leguminosas (feijão, soja) é usada na agricultura</b>?","alts":["As raízes têm nódulos com bactérias fixadoras de nitrogênio (Rhizobium), que enriquecem o solo e reduzem a necessidade de adubo nitrogenado.","Diminui (cerca de 10% passa adiante). O resto se perde como calor na respiração. Por isso cadeias são curtas.","Uma espécie libera substância que prejudica outra (-/0). Ex.: fungo Penicillium e bactérias; maré vermelha.","Fixação (N2 → NH3, bactérias Rhizobium nas leguminosas e cianobactérias), nitrificação (NH3 → NO2- → NO3-, Nitrosomonas e Nitrobacter), assimilação pelas plantas, desnitrificação (NO3- → N2, Pseudomonas)."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Vacina x soro</b>?","alts":["Retrovírus (RNA → DNA pela transcriptase reversa) que destrói linfócitos T CD4 (auxiliares), enfraquecendo a imunidade (aids).","Protozoário Trypanosoma cruzi. Transmitido pelas fezes do barbeiro (triatomíneo) na pele ou mucosa, e por alimentos contaminados (açaí, caldo de cana).","Bactéria Leptospira, na urina de ratos. Contato com água de enchente e esgoto.","Vacina: antígeno → imunização ativa, memória, prevenção, demora a agir. Soro: anticorpos prontos → imunização passiva, ação imediata, sem memória (picada de cobra, tétano)."],"certa":3,"coment":"💡 VaCina = Cria memória (prevenção). SOro = SOcorro imediato (tratamento)."},{"enun":"Complete: O sangue sai do ventrículo _____ pela artéria aorta e volta ao átrio direito pelas veias cavas.","alts":["hematose","difusão","esquerdo","FSH"],"certa":2,"coment":"O sangue sai do ventrículo <b>esquerdo</b> pela artéria <b>aorta</b> e volta ao átrio <b>direito</b> pelas veias <b>cavas</b>."},{"enun":"Qual alternativa explica <b>Chuva ácida: causa e efeitos</b>?","alts":["Óxidos de enxofre (SO2, da queima de carvão e diesel) e de nitrogênio (NOx) reagem com água formando H2SO4 e HNO3. Corrói monumentos de mármore (CaCO3), acidifica lagos e solos.","Quantidade de O2 que os microrganismos consomem para decompor a matéria orgânica da água. DBO alta = água muito poluída por matéria orgânica.","Aumentam biodiversidade, biomassa e complexidade das teias. A produtividade líquida tende a cair perto do clímax (quase tudo que é produzido é consumido).","Uso de um inimigo natural (predador, parasita, patógeno) para controlar uma praga, reduzindo agrotóxicos. Ex.: vespas contra lagartas, Bacillus thuringiensis."],"certa":0,"coment":""},{"enun":"Certo ou errado? A artéria pulmonar transporta sangue rico em oxigênio.","alts":["Certo","Errado"],"certa":1,"coment":"Transporta sangue VENOSO (pobre em O2) do ventrículo direito para os pulmões. Artéria = sai do coração, não importa o tipo de sangue."},{"enun":"Qual alternativa explica <b>Hematose</b>?","alts":["Estrogênio e progesterona sintéticos inibem FSH e LH na hipófise, impedindo a ovulação.","Filtração (glomérulo/cápsula de Bowman), reabsorção (glicose, água, sais no túbulo) e secreção. ADH aumenta a reabsorção de água.","T3 e T4 regulam o metabolismo; precisam de iodo. Falta de iodo → bócio. Por isso o sal é iodado no Brasil.","Troca gasosa nos alvéolos: O2 passa para o sangue e CO2 sai, por difusão."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>O que é deriva genética</b>?","alts":["Barreira geográfica separa populações; com o tempo acumulam diferenças até isolamento reprodutivo (não geram descendentes férteis) → novas espécies.","O antibiótico não cria a resistência: seleciona bactérias que já tinham mutação de resistência. Elas sobrevivem e se multiplicam. Uso incorreto acelera isso.","Lamarck: uso e desuso + herança de caracteres adquiridos (errado). Darwin: variação + seleção natural; os mais aptos sobrevivem e deixam mais descendentes.","Mudança aleatória nas frequências gênicas, forte em populações pequenas. Inclui efeito fundador e efeito gargalo."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Por que o monóxido de carbono (CO) é tão perigoso</b>?","alts":["Resposta rápida e involuntária coordenada pela medula espinhal: receptor → neurônio sensitivo → medula → neurônio motor → efetor. Ex.: reflexo patelar.","FSH (amadurece o folículo, estimula estrogênio), LH (pico causa a ovulação, forma o corpo lúteo), estrogênio (espessa endométrio), progesterona (mantém o endométrio).","Liga-se à hemoglobina com afinidade muito maior que o O2 (carboxiemoglobina) e impede o transporte de oxigênio.","Produzida no fígado, armazenada na vesícula. Não é enzima: emulsifica gorduras (quebra em gotas menores), facilitando a ação da lipase."],"certa":2,"coment":""},{"enun":"Qual o tipo sanguíneo doador universal (ABO)?","alts":["9:3:3:1","glucagon","O","2"],"certa":2,"coment":"Não tem aglutinogênios A nem B nas hemácias."},{"enun":"Qual alternativa explica <b>Artéria x veia</b>?","alts":["Produzida no fígado, armazenada na vesícula. Não é enzima: emulsifica gorduras (quebra em gotas menores), facilitando a ação da lipase.","Artéria sai do coração (parede espessa, alta pressão). Veia chega ao coração (parede fina, válvulas). Artéria pulmonar leva sangue venoso; veia pulmonar leva sangue arterial.","Estrogênio e progesterona sintéticos inibem FSH e LH na hipófise, impedindo a ovulação.","Simpático: \"luta ou fuga\" (acelera coração, dilata pupila e brônquios, inibe digestão; noradrenalina). Parassimpático: repouso (desacelera coração, estimula digestão; acetilcolina)."],"certa":1,"coment":"💡 Artéria = A sai (Away do coração). Veia = Volta ao coração."},{"enun":"Certo ou errado? A pirâmide de biomassa nunca pode ser invertida.","alts":["Certo","Errado"],"certa":1,"coment":"Pode inverter no mar: o fitoplâncton tem pouca biomassa em um dado momento, mas se reproduz muito rápido. Quem NUNCA inverte é a de energia."},{"enun":"Qual alternativa explica <b>O que é o câncer do ponto de vista celular</b>?","alts":["Alcoólica (leveduras): glicose → etanol + CO2 (pão, cerveja). Lática (bactérias, músculo em esforço): glicose → ácido lático (iogurte). Ambas rendem só 2 ATP.","Vegetal tem parede celular de celulose, cloroplastos e grande vacúolo central. Animal tem centríolos e lisossomos mais evidentes, e reserva glicogênio (vegetal reserva amido).","Divisão celular descontrolada por mutações em genes que regulam o ciclo (proto-oncogenes e supressores de tumor). Metástase = células migram para outros tecidos.","Clara (tilacoides): luz quebra água, libera O2, produz ATP e NADPH. Química/escura (estroma): ciclo de Calvin fixa CO2 em glicose usando ATP e NADPH."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Sistema ABO: quem doa e quem recebe</b>?","alts":["\"E\" (eventos independentes simultâneos): multiplica. \"Ou\" (mutuamente exclusivos): soma. Ex.: chance de menino E afetado = 1/2 x 1/4 = 1/8.","Vários códons diferentes codificam o mesmo aminoácido. Por isso algumas mutações pontuais são silenciosas (não alteram a proteína).","O (sem aglutinogênios) é doador universal. AB (sem anticorpos anti-A e anti-B) é receptor universal. A recebe de A e O; B recebe de B e O.","Cada característica é determinada por um par de fatores (alelos) que se separam na formação dos gametas. Cruzamento Aa x Aa → 1 AA : 2 Aa : 1 aa (fenótipo 3:1)."],"certa":2,"coment":"💡 O = \"Oferece para todos\". AB = \"Aceita de Bastante gente\"."},{"enun":"Qual alternativa explica <b>Genótipo x fenótipo</b>?","alts":["Ocorre com mãe Rh- e feto Rh+, geralmente na 2ª gestação: a mãe sensibilizada produz anti-Rh que destrói hemácias do feto. Prevenção: imunoglobulina anti-Rh após o 1º parto.","Genótipo: constituição genética (AA, Aa). Fenótipo: característica observável, resultado do genótipo + ambiente.","Pais normais com filho afetado → a característica é recessiva (os pais são heterozigotos).","Compara bandas de DNA (marcadores, eletroforese). Toda banda do filho que não veio da mãe tem de estar no pai."],"certa":1,"coment":""},{"enun":"Complete: Comunidade final e estável de uma sucessão ecológica: _____. Primeiros colonizadores de rocha nua: liquens.","alts":["unidirecional","cíclica","CFCs","clímax"],"certa":3,"coment":"Comunidade final e estável de uma sucessão ecológica: <b>clímax</b>. Primeiros colonizadores de rocha nua: <b>liquens</b>."},{"enun":"Complete: A pílula anticoncepcional inibe a liberação de _____ e LH, impedindo a ovulação.","alts":["FSH","aorta","direito","esquerdo"],"certa":0,"coment":"A pílula anticoncepcional inibe a liberação de <b>FSH</b> e <b>LH</b>, impedindo a <b>ovulação</b>."},{"enun":"Complete: O processo DNA → RNAm chama-se _____ e ocorre no núcleo; RNAm → proteína chama-se tradução e ocorre no ribossomo.","alts":["uracila","guanina","transcrição","timina"],"certa":2,"coment":"O processo DNA → RNAm chama-se <b>transcrição</b> e ocorre no <b>núcleo</b>; RNAm → proteína chama-se <b>tradução</b> e ocorre no <b>ribossomo</b>."},{"enun":"Qual alternativa explica <b>Função das mitocôndrias</b>?","alts":["Hipertônico: célula perde água e murcha (plasmólise na vegetal). Hipotônico: ganha água; hemácia pode estourar (hemólise), vegetal fica túrgida (parede impede ruptura).","Clara (tilacoides): luz quebra água, libera O2, produz ATP e NADPH. Química/escura (estroma): ciclo de Calvin fixa CO2 em glicose usando ATP e NADPH.","Respiração celular aeróbia (ciclo de Krebs e cadeia respiratória) → produção de ATP. Têm DNA próprio, herança materna (teoria endossimbiótica).","Transporte ativo que joga 3 Na+ para fora e traz 2 K+ para dentro, gastando ATP. Mantém o potencial de membrana (essencial nos neurônios)."],"certa":2,"coment":"💡 Mitocôndria = \"usina de energia\" (ATP). DNA só da mãe: herança materna."},{"enun":"Qual alternativa explica <b>Hormônios vegetais: auxina e etileno</b>?","alts":["Auxina: crescimento, fototropismo (cresce em direção à luz) e dominância apical. Etileno: amadurecimento dos frutos (por isso banana madura acelera as outras).","Trocas gasosas e transpiração. Abrem com luz e água disponível; fecham na falta de água para evitar perda.","Briófitas: sem vasos (musgos). Pteridófitas: vasos condutores (samambaias). Gimnospermas: sementes nuas (pinheiros, araucária). Angiospermas: flores e frutos.","Xilema: seiva bruta (água e sais) da raiz para as folhas. Floema: seiva elaborada (açúcares) das folhas para o resto da planta."],"certa":0,"coment":"💡 Etileno = \"Esconde a banana madura no saco com a verde e ela amadurece\"."},{"enun":"Qual alternativa explica <b>Mitose x meiose</b>?","alts":["Hipertônico: célula perde água e murcha (plasmólise na vegetal). Hipotônico: ganha água; hemácia pode estourar (hemólise), vegetal fica túrgida (parede impede ruptura).","Meio hipertônico: os microrganismos perdem água por osmose e não conseguem se multiplicar. O mesmo vale para doces com muito açúcar.","Clara (tilacoides): luz quebra água, libera O2, produz ATP e NADPH. Química/escura (estroma): ciclo de Calvin fixa CO2 em glicose usando ATP e NADPH.","Mitose: 1 célula → 2 idênticas (2n → 2n), crescimento e reparo. Meiose: 1 célula → 4 com metade dos cromossomos (2n → n), forma gametas, tem crossing-over (variabilidade)."],"certa":3,"coment":"💡 MEIOse divide pela MEtade (2n → n). MITOse faz cópias IdênTicas."},{"enun":"Qual alternativa explica <b>Biomas brasileiros: características do Cerrado</b>?","alts":["Savana, árvores tortuosas de casca grossa (resistência ao fogo), raízes profundas que alcançam lençol freático, solo ácido rico em alumínio. \"Berço das águas\". Ameaçado pela soja.","Semiárido, chuvas irregulares, plantas xerófitas (cactos, folhas reduzidas, espinhos), caducifólia na seca. Bioma exclusivamente brasileiro.","Efeito estufa é natural e mantém a Terra habitável (CO2, CH4, vapor d'água retêm calor). Aquecimento global é a intensificação dele pela emissão humana de gases.","O \"modo de vida\" da espécie: o que come, quando age, onde vive, como interage. Habitat é só o \"endereço\"."],"certa":0,"coment":"💡 Cerrado = árvore \"torta e de casca grossa, com raiz de poço profundo\"."},{"enun":"Qual alternativa explica <b>Parasitismo</b>?","alts":["Relação +/-: um vive à custa do outro sem matá-lo rápido (carrapato e cão).","Relação +/-: um animal mata e come o outro (onça e capivara).","Animal se alimentando de planta (+/-).","Esquistossomose, teníase/cisticercose, ascaridíase (lombriga), ancilostomose (amarelão), filariose (elefantíase)."],"certa":0,"coment":""},{"enun":"Complete: A troca gasosa nos alvéolos chama-se _____ e ocorre por difusão.","alts":["LH","ovulação","hematose","FSH"],"certa":2,"coment":"A troca gasosa nos alvéolos chama-se <b>hematose</b> e ocorre por <b>difusão</b>."},{"enun":"Qual alternativa explica <b>Células-tronco embrionárias x adultas</b>?","alts":["Embrionárias: pluripotentes (formam qualquer tecido). Adultas (medula óssea, cordão umbilical): multipotentes, mais limitadas. iPS: células adultas reprogramadas.","Produção de indivíduo geneticamente idêntico a partir do núcleo de uma célula somática transferido para um óvulo sem núcleo. Ex.: ovelha Dolly.","Vários códons diferentes codificam o mesmo aminoácido. Por isso algumas mutações pontuais são silenciosas (não alteram a proteína).","Compara bandas de DNA (marcadores, eletroforese). Toda banda do filho que não veio da mãe tem de estar no pai."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Teste de DNA de paternidade: como funciona</b>?","alts":["Compara bandas de DNA (marcadores, eletroforese). Toda banda do filho que não veio da mãe tem de estar no pai.","Daltonismo e hemofilia (recessivas no X). São mais comuns em homens (XY, basta um alelo). O pai passa o X para todas as filhas; o filho recebe o X da mãe.","Embrionárias: pluripotentes (formam qualquer tecido). Adultas (medula óssea, cordão umbilical): multipotentes, mais limitadas. iPS: células adultas reprogramadas.","Replicação: DNA → DNA (semiconservativa). Transcrição: DNA → RNAm (no núcleo). Tradução: RNAm → proteína (no ribossomo, RNAt traz aminoácidos)."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Como saber em um heredograma se a herança é recessiva</b>?","alts":["O (sem aglutinogênios) é doador universal. AB (sem anticorpos anti-A e anti-B) é receptor universal. A recebe de A e O; B recebe de B e O.","Pais normais com filho afetado → a característica é recessiva (os pais são heterozigotos).","Ocorre com mãe Rh- e feto Rh+, geralmente na 2ª gestação: a mãe sensibilizada produz anti-Rh que destrói hemácias do feto. Prevenção: imunoglobulina anti-Rh após o 1º parto.","\"E\" (eventos independentes simultâneos): multiplica. \"Ou\" (mutuamente exclusivos): soma. Ex.: chance de menino E afetado = 1/2 x 1/4 = 1/8."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Xilema x floema</b>?","alts":["Eucariontes heterotróficos por absorção, parede de quitina, reserva glicogênio. Decompositores, fazem fermentação (leveduras) e antibióticos (Penicillium).","São acelulares, sem metabolismo próprio: só se reproduzem dentro de células (parasitas intracelulares obrigatórios).","Xilema: seiva bruta (água e sais) da raiz para as folhas. Floema: seiva elaborada (açúcares) das folhas para o resto da planta.","Auxina: crescimento, fototropismo (cresce em direção à luz) e dominância apical. Etileno: amadurecimento dos frutos (por isso banana madura acelera as outras)."],"certa":2,"coment":"💡 XIlema = XIxi da planta: sobe água (seiva bruta). FLOema = FLuxo de açúcar (seiva elaborada) que desce."},{"enun":"Complete: Gases do efeito estufa: _____, metano (CH4) e vapor d'água. A destruição da camada de ozônio é causada pelos CFCs.","alts":["2","1/4","CO2","1/8"],"certa":2,"coment":"Gases do efeito estufa: <b>CO2</b>, <b>metano (CH4)</b> e vapor d'água. A destruição da camada de ozônio é causada pelos <b>CFCs</b>."},{"enun":"Certo ou errado? Bactérias não têm ribossomos porque são procariontes.","alts":["Certo","Errado"],"certa":1,"coment":"Bactérias TÊM ribossomos (menores, 70S). O que falta nelas é núcleo e organelas membranosas."},{"enun":"Qual alternativa explica <b>Fator Rh e eritroblastose fetal</b>?","alts":["DNA: dupla hélice, desoxirribose, bases A T C G. RNA: fita simples, ribose, bases A U C G. DNA guarda a informação; RNA participa da síntese de proteínas.","Down: trissomia do 21 (47 cromossomos). Turner: 45,X0 (mulher). Klinefelter: 47,XXY (homem). Causa: não disjunção na meiose.","Ocorre com mãe Rh- e feto Rh+, geralmente na 2ª gestação: a mãe sensibilizada produz anti-Rh que destrói hemácias do feto. Prevenção: imunoglobulina anti-Rh após o 1º parto.","Cada característica é determinada por um par de fatores (alelos) que se separam na formação dos gametas. Cruzamento Aa x Aa → 1 AA : 2 Aa : 1 aa (fenótipo 3:1)."],"certa":2,"coment":"💡 \"Mãe NEGATIVA, filho POSITIVO, problema no SEGUNDO\"."},{"enun":"Qual alternativa explica <b>Codominância x dominância incompleta</b>?","alts":["Compara bandas de DNA (marcadores, eletroforese). Toda banda do filho que não veio da mãe tem de estar no pai.","Codominância: os dois alelos se expressam juntos (sangue AB). Dominância incompleta: heterozigoto tem fenótipo intermediário (flor rosa entre vermelha e branca).","DNA: dupla hélice, desoxirribose, bases A T C G. RNA: fita simples, ribose, bases A U C G. DNA guarda a informação; RNA participa da síntese de proteínas.","Embrionárias: pluripotentes (formam qualquer tecido). Adultas (medula óssea, cordão umbilical): multipotentes, mais limitadas. iPS: células adultas reprogramadas."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Ciclo do carbono: o que retira e o que devolve CO2 à atmosfera</b>?","alts":["Mata Atlântica: floresta úmida costeira, altíssima biodiversidade e endemismo, só ~12% restante. Pantanal: maior planície alagável do mundo, ciclo de cheia e seca.","As raízes têm nódulos com bactérias fixadoras de nitrogênio (Rhizobium), que enriquecem o solo e reduzem a necessidade de adubo nitrogenado.","Intra: entre indivíduos da mesma espécie. Inter: entre espécies diferentes que disputam recurso; pode levar à exclusão competitiva (princípio de Gause).","Retira: fotossíntese (e dissolução nos oceanos). Devolve: respiração, decomposição, queima de combustíveis fósseis e queimadas."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Efeito estufa x aquecimento global</b>?","alts":["O \"modo de vida\" da espécie: o que come, quando age, onde vive, como interage. Habitat é só o \"endereço\".","Efeito estufa é natural e mantém a Terra habitável (CO2, CH4, vapor d'água retêm calor). Aquecimento global é a intensificação dele pela emissão humana de gases.","Mata Atlântica: floresta úmida costeira, altíssima biodiversidade e endemismo, só ~12% restante. Pantanal: maior planície alagável do mundo, ciclo de cheia e seca.","Primária: começa em área nunca habitada (rocha nua), com pioneiras como liquens. Secundária: em área já habitada e perturbada (incêndio, roça abandonada). Comunidade final = clímax."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Esquistossomose: agente e ciclo</b>?","alts":["Verme Schistosoma mansoni. Hospedeiro intermediário: caramujo Biomphalaria. A cercária penetra na pele em água doce contaminada (\"barriga d'água\"). Prevenção: saneamento.","Teníase: comer carne de porco ou boi malcozida com cisticercos (adulto no intestino). Cisticercose: ingerir OVOS da Taenia solium (água e verduras contaminadas), larvas vão a músculos e cérebro.","Bactéria Leptospira, na urina de ratos. Contato com água de enchente e esgoto.","Retrovírus (RNA → DNA pela transcriptase reversa) que destrói linfócitos T CD4 (auxiliares), enfraquecendo a imunidade (aids)."],"certa":0,"coment":"💡 \"Barriga d'água\" pega na água: caramujo + pele na lagoa contaminada."},{"enun":"Qual alternativa explica <b>O que é magnificação (bioacumulação) trófica</b>?","alts":["CFCs liberam cloro que quebra O3 na estratosfera. O ozônio filtra radiação UV, que causa câncer de pele e mutações.","Substâncias não biodegradáveis (mercúrio, DDT, metais pesados) se acumulam e ficam mais concentradas nos níveis tróficos mais altos. Predadores de topo são os mais contaminados.","Primária: começa em área nunca habitada (rocha nua), com pioneiras como liquens. Secundária: em área já habitada e perturbada (incêndio, roça abandonada). Comunidade final = clímax.","Os nutrientes estão na biomassa e na serrapilheira, reciclados rapidamente. Desmatado, o solo fica exposto à lixiviação pelas chuvas e perde fertilidade."],"certa":1,"coment":"💡 Quem come mais no topo, acumula mais veneno: \"o tubarão paga a conta\"."},{"enun":"Proporção fenotípica do cruzamento AaBb x AaBb (genes independentes)?","alts":["etileno","Aedes aegypti","O","9:3:3:1"],"certa":3,"coment":"Use o quadro de Punnett 4x4 ou multiplique (3:1) x (3:1)."},{"enun":"Qual alternativa explica <b>Insulina x glucagon</b>?","alts":["Ambos do pâncreas. Insulina baixa a glicemia (glicose entra nas células, vira glicogênio). Glucagon sobe a glicemia (quebra glicogênio no fígado).","Tipo 1: autoimune, pâncreas não produz insulina (precisa aplicar). Tipo 2: resistência à insulina, ligada a obesidade e sedentarismo.","Simpático: \"luta ou fuga\" (acelera coração, dilata pupila e brônquios, inibe digestão; noradrenalina). Parassimpático: repouso (desacelera coração, estimula digestão; acetilcolina).","Artéria sai do coração (parede espessa, alta pressão). Veia chega ao coração (parede fina, válvulas). Artéria pulmonar leva sangue venoso; veia pulmonar leva sangue arterial."],"certa":0,"coment":"💡 Insulina INSere glicose nas células (glicemia cai). GLUCAgon GERA GLUcose no sangue (glicemia sobe)."},{"enun":"Complete: A leptospirose é causada por _____ e transmitida pela urina de ratos, comum em enchentes.","alts":["bactéria","Plasmodium","Anopheles","ovos"],"certa":0,"coment":"A leptospirose é causada por <b>bactéria</b> e transmitida pela <b>urina de ratos</b>, comum em <b>enchentes</b>."},{"enun":"Qual alternativa explica <b>Teníase x cisticercose</b>?","alts":["Com grande parte da população vacinada, o patógeno circula pouco e protege até quem não pode se vacinar.","Antibióticos atuam em estruturas de bactérias (parede, ribossomos bacterianos). Vírus não têm metabolismo próprio; usam a célula do hospedeiro.","Protozoário Trypanosoma cruzi. Transmitido pelas fezes do barbeiro (triatomíneo) na pele ou mucosa, e por alimentos contaminados (açaí, caldo de cana).","Teníase: comer carne de porco ou boi malcozida com cisticercos (adulto no intestino). Cisticercose: ingerir OVOS da Taenia solium (água e verduras contaminadas), larvas vão a músculos e cérebro."],"certa":3,"coment":""},{"enun":"Certo ou errado? Daltonismo é mais comum em mulheres porque elas têm dois cromossomos X.","alts":["Certo","Errado"],"certa":1,"coment":"É mais comum em HOMENS: com um X só, basta um alelo recessivo para manifestar."},{"enun":"Qual alternativa explica <b>O que é nicho ecológico</b>?","alts":["Óxidos de enxofre (SO2, da queima de carvão e diesel) e de nitrogênio (NOx) reagem com água formando H2SO4 e HNO3. Corrói monumentos de mármore (CaCO3), acidifica lagos e solos.","Campos do sul do RS, vegetação rasteira (gramíneas), clima subtropical. Ameaçado pela pecuária extensiva, silvicultura (eucalipto) e arenização.","Quantidade de O2 que os microrganismos consomem para decompor a matéria orgânica da água. DBO alta = água muito poluída por matéria orgânica.","O \"modo de vida\" da espécie: o que come, quando age, onde vive, como interage. Habitat é só o \"endereço\"."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Osmose: célula em meio hipertônico e hipotônico</b>?","alts":["Hipertônico: célula perde água e murcha (plasmólise na vegetal). Hipotônico: ganha água; hemácia pode estourar (hemólise), vegetal fica túrgida (parede impede ruptura).","6CO2 + 6H2O + luz → C6H12O6 + 6O2, no cloroplasto. O O2 liberado vem da água (fotólise).","Carboidratos: energia rápida (glicose) e estrutura (celulose). Lipídios: reserva de energia, membranas, hormônios esteroides. Proteínas: estrutura, enzimas, anticorpos, transporte.","A: cegueira noturna. C: escorbuto (gengiva sangrando). D: raquitismo. K: problemas de coagulação. B12: anemia perniciosa."],"certa":0,"coment":"💡 \"A água vai para onde tem mais sal\" (sai do lado diluído para o concentrado)."},{"enun":"Qual alternativa explica <b>Código genético é \"degenerado\": o que significa</b>?","alts":["Produção de indivíduo geneticamente idêntico a partir do núcleo de uma célula somática transferido para um óvulo sem núcleo. Ex.: ovelha Dolly.","O (sem aglutinogênios) é doador universal. AB (sem anticorpos anti-A e anti-B) é receptor universal. A recebe de A e O; B recebe de B e O.","Vários códons diferentes codificam o mesmo aminoácido. Por isso algumas mutações pontuais são silenciosas (não alteram a proteína).","Down: trissomia do 21 (47 cromossomos). Turner: 45,X0 (mulher). Klinefelter: 47,XXY (homem). Causa: não disjunção na meiose."],"certa":2,"coment":""},{"enun":"Complete: Na cadeia alimentar, a energia é _____ (não volta), enquanto a matéria é cíclica (decompositores devolvem ao ambiente).","alts":["liquens","aeróbias","clímax","unidirecional"],"certa":3,"coment":"Na cadeia alimentar, a energia é <b>unidirecional</b> (não volta), enquanto a matéria é <b>cíclica</b> (decompositores devolvem ao ambiente)."},{"enun":"Qual alternativa explica <b>Biomas brasileiros: Pampa</b>?","alts":["Aumentam biodiversidade, biomassa e complexidade das teias. A produtividade líquida tende a cair perto do clímax (quase tudo que é produzido é consumido).","Campos do sul do RS, vegetação rasteira (gramíneas), clima subtropical. Ameaçado pela pecuária extensiva, silvicultura (eucalipto) e arenização.","Primária: começa em área nunca habitada (rocha nua), com pioneiras como liquens. Secundária: em área já habitada e perturbada (incêndio, roça abandonada). Comunidade final = clímax.","Semiárido, chuvas irregulares, plantas xerófitas (cactos, folhas reduzidas, espinhos), caducifólia na seca. Bioma exclusivamente brasileiro."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Hormônios do ciclo menstrual</b>?","alts":["Estrogênio e progesterona sintéticos inibem FSH e LH na hipófise, impedindo a ovulação.","Pequena (pulmonar): ventrículo direito → artéria pulmonar → pulmões → veias pulmonares → átrio esquerdo. Grande (sistêmica): ventrículo esquerdo → aorta → corpo → veias cavas → átrio direito.","FSH (amadurece o folículo, estimula estrogênio), LH (pico causa a ovulação, forma o corpo lúteo), estrogênio (espessa endométrio), progesterona (mantém o endométrio).","hCG (gonadotrofina coriônica), produzido pelo embrião/placenta; mantém o corpo lúteo no início da gestação."],"certa":2,"coment":"💡 \"FSH Faz o folículo, LH Libera o óvulo, Progesterona Protege a gravidez\"."},{"enun":"Qual alternativa explica <b>Função dos lisossomos</b>?","alts":["Passivo: a favor do gradiente, sem ATP (difusão simples, facilitada, osmose). Ativo: contra o gradiente, gasta ATP (bomba de sódio e potássio).","Digestão intracelular com enzimas hidrolíticas; autofagia (reciclagem de organelas).","A: cegueira noturna. C: escorbuto (gengiva sangrando). D: raquitismo. K: problemas de coagulação. B12: anemia perniciosa.","Transporte ativo que joga 3 Na+ para fora e traz 2 K+ para dentro, gastando ATP. Mantém o potencial de membrana (essencial nos neurônios)."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Camada de ozônio: o que a destrói e por que importa</b>?","alts":["Uma espécie libera substância que prejudica outra (-/0). Ex.: fungo Penicillium e bactérias; maré vermelha.","Substâncias não biodegradáveis (mercúrio, DDT, metais pesados) se acumulam e ficam mais concentradas nos níveis tróficos mais altos. Predadores de topo são os mais contaminados.","CFCs liberam cloro que quebra O3 na estratosfera. O ozônio filtra radiação UV, que causa câncer de pele e mutações.","Quantidade de O2 que os microrganismos consomem para decompor a matéria orgânica da água. DBO alta = água muito poluída por matéria orgânica."],"certa":2,"coment":""},{"enun":"Complete: A cisticercose humana ocorre ao ingerir _____ de Taenia solium; a teníase, ao comer carne de porco malcozida com cisticercos.","alts":["Anopheles","Plasmodium","bactéria","ovos"],"certa":3,"coment":"A cisticercose humana ocorre ao ingerir <b>ovos</b> de Taenia solium; a teníase, ao comer <b>carne de porco malcozida</b> com cisticercos."},{"enun":"Qual alternativa explica <b>Especiação alopátrica</b>?","alts":["Seleção natural + genética: mutação e recombinação geram variabilidade; seleção natural, deriva genética e migração alteram as frequências gênicas.","Barreira geográfica separa populações; com o tempo acumulam diferenças até isolamento reprodutivo (não geram descendentes férteis) → novas espécies.","O antibiótico não cria a resistência: seleciona bactérias que já tinham mutação de resistência. Elas sobrevivem e se multiplicam. Uso incorreto acelera isso.","Lamarck: uso e desuso + herança de caracteres adquiridos (errado). Darwin: variação + seleção natural; os mais aptos sobrevivem e deixam mais descendentes."],"certa":1,"coment":""},{"enun":"Qual é o saldo de ATP da fermentação por molécula de glicose?","alts":["lisossomo","O","9:3:3:1","2"],"certa":3,"coment":"Só a glicólise, sem mitocôndria."},{"enun":"Qual alternativa explica <b>Hormônios da tireoide e o papel do iodo</b>?","alts":["Estrogênio e progesterona sintéticos inibem FSH e LH na hipófise, impedindo a ovulação.","Produzida no fígado, armazenada na vesícula. Não é enzima: emulsifica gorduras (quebra em gotas menores), facilitando a ação da lipase.","T3 e T4 regulam o metabolismo; precisam de iodo. Falta de iodo → bócio. Por isso o sal é iodado no Brasil.","Carboidratos: boca (amilase salivar). Proteínas: estômago (pepsina, meio ácido). Lipídios: intestino delgado (lipase pancreática + bile emulsificando)."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Diferença entre pirâmide de energia e pirâmide de biomassa/números</b>?","alts":["As raízes têm nódulos com bactérias fixadoras de nitrogênio (Rhizobium), que enriquecem o solo e reduzem a necessidade de adubo nitrogenado.","A de energia NUNCA é invertida. Biomassa pode inverter (fitoplâncton no mar) e números pode inverter (uma árvore com milhares de insetos).","Uso de um inimigo natural (predador, parasita, patógeno) para controlar uma praga, reduzindo agrotóxicos. Ex.: vespas contra lagartas, Bacillus thuringiensis.","Semiárido, chuvas irregulares, plantas xerófitas (cactos, folhas reduzidas, espinhos), caducifólia na seca. Bioma exclusivamente brasileiro."],"certa":1,"coment":"💡 Energia \"não volta atrás\": a pirâmide de energia NUNCA fica de cabeça para baixo."},{"enun":"Qual alternativa explica <b>Biomas brasileiros: características da Caatinga</b>?","alts":["Campos do sul do RS, vegetação rasteira (gramíneas), clima subtropical. Ameaçado pela pecuária extensiva, silvicultura (eucalipto) e arenização.","A de energia NUNCA é invertida. Biomassa pode inverter (fitoplâncton no mar) e números pode inverter (uma árvore com milhares de insetos).","Intra: entre indivíduos da mesma espécie. Inter: entre espécies diferentes que disputam recurso; pode levar à exclusão competitiva (princípio de Gause).","Semiárido, chuvas irregulares, plantas xerófitas (cactos, folhas reduzidas, espinhos), caducifólia na seca. Bioma exclusivamente brasileiro."],"certa":3,"coment":""},{"enun":"Complete: A malária é causada pelo protozoário _____ e transmitida pela fêmea do mosquito Anopheles.","alts":["bactéria","ovos","Plasmodium","carne de porco malcozida"],"certa":2,"coment":"A malária é causada pelo protozoário <b>Plasmodium</b> e transmitida pela fêmea do mosquito <b>Anopheles</b>."}]},"qui":{"tema":"Química","ic":"⚗️","lista":[{"enun":"Qual alternativa explica <b>Escala de pH</b>?","alts":["Tempo para metade dos núcleos decair. Após n meias-vidas sobra m0 / 2^n. Ex.: 3 meias-vidas → 1/8.","O ΔH de uma reação depende só dos estados inicial e final. Pode-se somar equações (inverter troca o sinal; multiplicar multiplica o ΔH).","Exo: libera calor, ΔH < 0 (combustão). Endo: absorve calor, ΔH > 0 (fotossíntese, derreter gelo, compressa fria).","pH = -log[H+]. pH < 7 ácido, = 7 neutro, > 7 básico (a 25 °C). pH + pOH = 14. Cada unidade = fator 10 na [H+]."],"certa":3,"coment":"💡 pH baixo = muito H+ = ácido. Cada 1 de pH = 10x."},{"enun":"Qual alternativa explica <b>Le Chatelier: efeito da temperatura</b>?","alts":["Adição de calcário (CaCO3) ou cal para neutralizar a acidez do solo e corrigir o pH.","É um sal de caráter básico (hidrólise) que neutraliza o excesso de HCl no estômago.","Aumentar a temperatura favorece o sentido endotérmico. Diminuir favorece o exotérmico. Temperatura é o único fator que muda o valor de K.","A solução de pH 3 tem [H+] 100 vezes maior (10^-3 x 10^-5)."],"certa":2,"coment":"💡 \"Esquentou, favorece quem ABSORVE calor (endo).\""},{"enun":"Quantas partículas há em 1 mol?","alts":["0,25","6,02 x 10^23","flúor","10"],"certa":1,"coment":"Constante de Avogadro."},{"enun":"Qual alternativa explica <b>Diluição: fórmula</b>?","alts":["C1 x V1 = C2 x V2 (a quantidade de soluto não muda, só o volume aumenta).","6,02 x 10^23 partículas (constante de Avogadro). A massa de 1 mol em gramas = massa molar.","22,4 L por mol (0 °C, 1 atm). Nas CATP (25 °C, 1 atm) cerca de 24,5 L.","Partes por milhão: 1 ppm = 1 mg de soluto por kg de solução (ou cerca de 1 mg/L em água). Usado para poluentes e flúor na água."],"certa":0,"coment":"💡 Diluir é só pôr água: a quantidade de soluto não muda, então \"C x V antes = C x V depois\"."},{"enun":"Qual alternativa explica <b>Mistura homogênea x heterogênea</b>?","alts":["Decantação: sólido-líquido ou líquidos imiscíveis (funil de bromo para água e óleo). Filtração: sólido retido no filtro. Centrifugação: acelera a decantação (separar plasma do sangue).","Físico: não forma substância nova (mudança de estado, dissolução). Químico: forma nova substância (queima, ferrugem, cozimento).","Homogênea: uma fase (água e sal dissolvido, ar). Heterogênea: duas ou mais fases (água e óleo, granito).","Cátion: perdeu elétrons, carga positiva (metais tendem a formar). Ânion: ganhou elétrons, carga negativa (ametais)."],"certa":2,"coment":""},{"enun":"Certo ou errado? Gorduras saturadas são geralmente líquidas à temperatura ambiente.","alts":["Certo","Errado"],"certa":1,"coment":"Saturadas (gordura animal, manteiga) são sólidas. Insaturadas (óleos vegetais) são líquidas."},{"enun":"Qual alternativa explica <b>Exemplo: pH 3 x pH 5</b>?","alts":["A solução de pH 3 tem [H+] 100 vezes maior (10^-3 x 10^-5).","Exo: libera calor, ΔH < 0 (combustão). Endo: absorve calor, ΔH > 0 (fotossíntese, derreter gelo, compressa fria).","Ácido libera H+ (H3O+) em água. Base libera OH-. Neutralização: ácido + base → sal + água.","É um sal de caráter básico (hidrólise) que neutraliza o excesso de HCl no estômago."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Volume molar dos gases nas CNTP</b>?","alts":["Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","C1 x V1 = C2 x V2 (a quantidade de soluto não muda, só o volume aumenta).","22,4 L por mol (0 °C, 1 atm). Nas CATP (25 °C, 1 atm) cerca de 24,5 L.","Sal nas estradas derrete o gelo (baixa o ponto de congelamento). Água com sal ferve a temperatura maior. Aditivo no radiador."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Calagem do solo</b>?","alts":["Fissão: núcleo pesado (urânio-235) se divide; usinas como Angra e bomba atômica. Fusão: núcleos leves (hidrogênio) se unem; energia do Sol.","Processo NÃO espontâneo: usa corrente elétrica para provocar reação redox. Usada para obter alumínio, cloro, soda, galvanoplastia (cromar, niquelar).","Alfa: núcleo de He (2p+2n), pouco penetrante, A -4 e Z -2. Beta: elétron, Z +1, A igual. Gama: onda eletromagnética, muito penetrante, sem massa.","Adição de calcário (CaCO3) ou cal para neutralizar a acidez do solo e corrigir o pH."],"certa":3,"coment":""},{"enun":"Qual gás tóxico se forma na combustão incompleta?","alts":["5","monóxido de carbono","0,25","6,02 x 10^23"],"certa":1,"coment":"CO: liga-se à hemoglobina e impede o transporte de O2."},{"enun":"Qual alternativa explica <b>Ligação iônica, covalente e metálica</b>?","alts":["Aumenta para cima e para a direita. Ordem a decorar: F > O > N > Cl > Br > I > S > C > P > H (\"Fui Ontem No Clube, Briguei, I Saí Correndo Para Hospital\").","Iônica: metal + ametal, transferência de elétrons (NaCl). Covalente: ametal + ametal, compartilhamento (H2O). Metálica: metal + metal, \"mar de elétrons\" (conduz eletricidade).","Físico: não forma substância nova (mudança de estado, dissolução). Químico: forma nova substância (queima, ferrugem, cozimento).","IsótoPos: mesmo nº de Prótons (mesmo elemento). IsóbAros: mesma massa (A). IsótoNos: mesmo nº de Nêutrons."],"certa":1,"coment":""},{"enun":"Complete: Ligação _____: metal + ametal, transfere elétrons. Ligação covalente: ametal + ametal, compartilha elétrons. Ligação metálica: \"mar de elétrons\".","alts":["semelhante","polares","iônica","prótons"],"certa":2,"coment":"Ligação <b>iônica</b>: metal + ametal, transfere elétrons. Ligação <b>covalente</b>: ametal + ametal, compartilha elétrons. Ligação <b>metálica</b>: \"mar de elétrons\"."},{"enun":"Certo ou errado? Compostos iônicos conduzem corrente elétrica no estado sólido.","alts":["Certo","Errado"],"certa":1,"coment":"Só conduzem fundidos ou dissolvidos em água, quando os íons ficam livres para se mover."},{"enun":"Qual alternativa explica <b>Química verde: ideias centrais</b>?","alts":["Prevenir resíduos, usar matérias-primas renováveis, catalisadores, solventes menos tóxicos, economia de átomos e eficiência energética.","São muito estáveis e quase não biodegradáveis; persistem por séculos e geram microplásticos. Alternativas: reciclagem, plásticos biodegradáveis (PLA).","Ácido carboxílico + álcool → éster + água. Reação reversível. Ésteres dão aroma de frutas.","Óleo vegetal ou gordura + álcool (metanol ou etanol), com catalisador → biodiesel (ésteres) + glicerina."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Concentração comum x molaridade</b>?","alts":["C1 x V1 = C2 x V2 (a quantidade de soluto não muda, só o volume aumenta).","Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","Comum: C = massa do soluto (g) / volume (L). Molaridade: M = mols do soluto / volume (L). Relação: C = M x massa molar.","O que acaba primeiro e limita a quantidade de produto. O outro está em excesso. Compare a proporção estequiométrica com a quantidade disponível."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Pilha (célula galvânica): ânodo e cátodo</b>?","alts":["Aumentar a temperatura favorece o sentido endotérmico. Diminuir favorece o exotérmico. Temperatura é o único fator que muda o valor de K.","Um sistema em equilíbrio perturbado se desloca para minimizar a perturbação (concentração, pressão, temperatura).","Ânodo: polo negativo, OXIDAÇÃO (perde elétrons, a placa corrói). Cátodo: polo positivo, REDUÇÃO (ganha elétrons, a placa engrossa). Elétrons vão do ânodo ao cátodo.","Fissão: núcleo pesado (urânio-235) se divide; usinas como Angra e bomba atômica. Fusão: núcleos leves (hidrogênio) se unem; energia do Sol."],"certa":2,"coment":"💡 \"ÂNODO OXIDA, CÁTODO REDUZ\" (vogais com vogais, consoantes com consoantes: Ânodo-Oxidação, Cátodo-Redução)."},{"enun":"Qual alternativa explica <b>Destilação fracionada do petróleo</b>?","alts":["Óleo vegetal ou gordura + álcool (metanol ou etanol), com catalisador → biodiesel (ésteres) + glicerina.","Separa frações por ponto de ebulição: gás (GLP), gasolina, querosene, diesel, óleos lubrificantes, e o resíduo (asfalto, piche).","Álcool: -OH em carbono saturado. Fenol: -OH no anel aromático. Aldeído: -CHO na ponta. Cetona: C=O no meio. Ácido carboxílico: -COOH.","Completa: combustível + O2 suficiente → CO2 + H2O. Incompleta: pouco O2 → CO (tóxico) e/ou C (fuligem)."],"certa":1,"coment":"💡 Quanto mais leve a fração, mais alto ela sai na torre (gás no topo, asfalto embaixo)."},{"enun":"Qual alternativa explica <b>Biomoléculas: gordura saturada x insaturada</b>?","alts":["Prevenir resíduos, usar matérias-primas renováveis, catalisadores, solventes menos tóxicos, economia de átomos e eficiência energética.","Saturada: só ligações simples, sólida à temperatura ambiente (gordura animal). Insaturada: duplas ligações, líquida (óleos vegetais). Hidrogenação transforma óleo em margarina.","Ácido carboxílico + álcool → éster + água. Reação reversível. Ésteres dão aroma de frutas.","Aterro sanitário (impermeabilizado, trata o chorume e o gás) é melhor que lixão. Compostagem: matéria orgânica vira adubo. Incineração reduz volume mas emite gases."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Por que a água tem ponto de ebulição alto para uma molécula tão pequena</b>?","alts":["Aumenta para baixo no grupo (mais camadas) e para a esquerda no período (menos prótons puxando). Frâncio é o maior.","Z = prótons. A = prótons + nêutrons. Nêutrons = A - Z.","Polar: momento dipolar resultante diferente de zero (H2O, NH3, HCl). Apolar: dipolos se anulam (CO2, CH4, O2). \"Semelhante dissolve semelhante\".","Ligações de hidrogênio entre as moléculas."],"certa":3,"coment":""},{"enun":"Complete: Moléculas _____ dissolvem-se em solventes polares, e apolares em apolares: \"semelhante dissolve semelhante\".","alts":["iônica","polares","decantação (bromo)","fracionada"],"certa":1,"coment":"Moléculas <b>polares</b> dissolvem-se em solventes polares, e apolares em apolares: \"semelhante dissolve <b>semelhante</b>\"."},{"enun":"Qual alternativa explica <b>Por que NaCl tem efeito coligativo maior que a glicose na mesma concentração</b>?","alts":["Comum: C = massa do soluto (g) / volume (L). Molaridade: M = mols do soluto / volume (L). Relação: C = M x massa molar.","Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","τ = massa do soluto / massa da solução. Em % basta multiplicar por 100. Ex.: álcool 70% em massa.","NaCl se dissocia em 2 íons (Na+ e Cl-), dobrando o número de partículas. Glicose não se dissocia."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>R–CO–R (carbonila no meio)</b>?","alts":["Éter","Aldeído","Amina","Cetona"],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Por que o gelo flutua</b>?","alts":["Decantação: sólido-líquido ou líquidos imiscíveis (funil de bromo para água e óleo). Filtração: sólido retido no filtro. Centrifugação: acelera a decantação (separar plasma do sangue).","Aumenta para cima e para a direita. Ordem a decorar: F > O > N > Cl > Br > I > S > C > P > H (\"Fui Ontem No Clube, Briguei, I Saí Correndo Para Hospital\").","Aumenta para baixo no grupo (mais camadas) e para a esquerda no período (menos prótons puxando). Frâncio é o maior.","As ligações de hidrogênio organizam o gelo numa estrutura hexagonal com espaços vazios: o gelo é menos denso que a água líquida."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Reação exotérmica x endotérmica</b>?","alts":["Ácido forte + base fraca → sal ácido (NH4Cl). Ácido fraco + base forte → sal básico (NaHCO3, Na2CO3). Forte + forte → neutro (NaCl).","Diminui a energia de ativação, acelerando a reação. Não é consumido e NÃO altera o ΔH nem o equilíbrio (só faz chegar a ele mais rápido).","Exo: libera calor, ΔH < 0 (combustão). Endo: absorve calor, ΔH > 0 (fotossíntese, derreter gelo, compressa fria).","Adição de calcário (CaCO3) ou cal para neutralizar a acidez do solo e corrigir o pH."],"certa":2,"coment":"💡 EXOtérmica = calor EXIT (sai), ΔH negativo. ENDOtérmica = calor ENTRA, ΔH positivo."},{"enun":"Complete: Sal de ácido fraco com base forte (como o bicarbonato de sódio) forma solução _____; sal de ácido forte com base fraca (como o NH4Cl), solução ácida.","alts":["básica","ânodo","cátodo","oxidação"],"certa":0,"coment":"Sal de ácido fraco com base forte (como o bicarbonato de sódio) forma solução <b>básica</b>; sal de ácido forte com base fraca (como o NH4Cl), solução <b>ácida</b>."},{"enun":"Qual alternativa explica <b>Transesterificação e biodiesel</b>?","alts":["Adição: monômeros com dupla ligação se somam sem perder nada (polietileno, PVC, isopor). Condensação: monômeros se unem liberando molécula pequena, como água (PET, náilon).","Óleo vegetal ou gordura + álcool (metanol ou etanol), com catalisador → biodiesel (ésteres) + glicerina.","São muito estáveis e quase não biodegradáveis; persistem por séculos e geram microplásticos. Alternativas: reciclagem, plásticos biodegradáveis (PLA).","Só C e H, apolares, insolúveis em água, menos densos que ela. Principal fonte: petróleo e gás natural (metano)."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Reagente limitante</b>?","alts":["Sal nas estradas derrete o gelo (baixa o ponto de congelamento). Água com sal ferve a temperatura maior. Aditivo no radiador.","22,4 L por mol (0 °C, 1 atm). Nas CATP (25 °C, 1 atm) cerca de 24,5 L.","Comum: C = massa do soluto (g) / volume (L). Molaridade: M = mols do soluto / volume (L). Relação: C = M x massa molar.","O que acaba primeiro e limita a quantidade de produto. O outro está em excesso. Compare a proporção estequiométrica com a quantidade disponível."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Saponificação</b>?","alts":["São muito estáveis e quase não biodegradáveis; persistem por séculos e geram microplásticos. Alternativas: reciclagem, plásticos biodegradáveis (PLA).","Carbono quiral (assimétrico): ligado a 4 grupos diferentes. Gera enantiômeros que desviam a luz polarizada. Importante em fármacos (talidomida).","Gordura/óleo (triglicerídeo) + base forte (NaOH) → sabão (sal de ácido graxo) + glicerol.","1 met, 2 et, 3 prop, 4 but, 5 pent, 6 hex, 7 hept, 8 oct. Infixo: an (simples), en (dupla), in (tripla)."],"certa":2,"coment":"💡 SAPOnificação = faz SAbãO: gordura + base."},{"enun":"Complete: Aumentar a temperatura favorece o sentido _____; aumentar a pressão desloca para o lado com menos mols de gás.","alts":["libera","positivo","endotérmico","negativo"],"certa":2,"coment":"Aumentar a temperatura favorece o sentido <b>endotérmico</b>; aumentar a pressão desloca para o lado com <b>menos mols de gás</b>."},{"enun":"Qual alternativa explica <b>Como age o catalisador</b>?","alts":["A solução de pH 3 tem [H+] 100 vezes maior (10^-3 x 10^-5).","Aumentar a temperatura favorece o sentido endotérmico. Diminuir favorece o exotérmico. Temperatura é o único fator que muda o valor de K.","Diminui a energia de ativação, acelerando a reação. Não é consumido e NÃO altera o ΔH nem o equilíbrio (só faz chegar a ele mais rápido).","Alfa: núcleo de He (2p+2n), pouco penetrante, A -4 e Z -2. Beta: elétron, Z +1, A igual. Gama: onda eletromagnética, muito penetrante, sem massa."],"certa":2,"coment":"💡 Catalisador é um \"atalho na montanha\": diminui a subida (energia de ativação), mas não muda o ponto de partida nem o de chegada (ΔH)."},{"enun":"Qual alternativa explica <b>Quanto vale 1 mol</b>?","alts":["Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","22,4 L por mol (0 °C, 1 atm). Nas CATP (25 °C, 1 atm) cerca de 24,5 L.","6,02 x 10^23 partículas (constante de Avogadro). A massa de 1 mol em gramas = massa molar.","Partes por milhão: 1 ppm = 1 mg de soluto por kg de solução (ou cerca de 1 mg/L em água). Usado para poluentes e flúor na água."],"certa":2,"coment":"💡 Mol é uma \"dúzia gigante\": 1 dúzia = 12, 1 mol = 6 x 10²³."},{"enun":"Complete: Nas CNTP, 1 mol de qualquer gás ocupa _____ L.","alts":["2","22,4","4","C2·V2"],"certa":1,"coment":"Nas CNTP, 1 mol de qualquer gás ocupa <b>22,4</b> L."},{"enun":"Qual alternativa explica <b>R–O–R</b>?","alts":["Amina","Éter","Éster","Cetona"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Cátion x ânion</b>?","alts":["Aumenta para baixo no grupo (mais camadas) e para a esquerda no período (menos prótons puxando). Frâncio é o maior.","Simples: sólido dissolvido em líquido (água e sal). Fracionada: líquidos miscíveis com pontos de ebulição diferentes (petróleo, álcool e água).","Coagulação/floculação (sulfato de alumínio forma flocos), decantação, filtração (areia e cascalho), desinfecção (cloro) e fluoretação.","Cátion: perdeu elétrons, carga positiva (metais tendem a formar). Ânion: ganhou elétrons, carga negativa (ametais)."],"certa":3,"coment":"💡 CátIon = \"gaTo positivo\" (perdeu elétron, +). ÂNIon = \"Ânimo Negativo\" (ganhou elétron, −)."},{"enun":"Quantos carbonos tem uma cadeia com prefixo \"pent\"?","alts":["5","6,02 x 10^23","monóxido de carbono","12"],"certa":0,"coment":"met 1, et 2, prop 3, but 4, pent 5, hex 6."},{"enun":"Qual alternativa explica <b>Isomeria: o que é e tipos</b>?","alts":["Mesma fórmula molecular, estruturas diferentes. Plana: cadeia, posição, função, metameria, tautomeria. Espacial: geométrica (cis-trans) e óptica.","Gordura/óleo (triglicerídeo) + base forte (NaOH) → sabão (sal de ácido graxo) + glicerol.","São muito estáveis e quase não biodegradáveis; persistem por séculos e geram microplásticos. Alternativas: reciclagem, plásticos biodegradáveis (PLA).","Saturada: só ligações simples, sólida à temperatura ambiente (gordura animal). Insaturada: duplas ligações, líquida (óleos vegetais). Hidrogenação transforma óleo em margarina."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>R–NH2</b>?","alts":["Amida","Éter","Amina","Éster"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Potencial de redução e quem oxida</b>?","alts":["Maior E° de redução → reduz (cátodo). Menor E° → oxida (ânodo). ddp = E°maior - E°menor.","Alfa: núcleo de He (2p+2n), pouco penetrante, A -4 e Z -2. Beta: elétron, Z +1, A igual. Gama: onda eletromagnética, muito penetrante, sem massa.","Aumentar pressão desloca para o lado com MENOR número de mols de gás. Diminuir, para o lado com mais mols.","Ácido forte + base fraca → sal ácido (NH4Cl). Ácido fraco + base forte → sal básico (NaHCO3, Na2CO3). Forte + forte → neutro (NaCl)."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Datação por carbono-14</b>?","alts":["C-14 tem meia-vida de ~5.730 anos; serve para datar restos de seres vivos de até ~50 mil anos.","Ânodo: polo negativo, OXIDAÇÃO (perde elétrons, a placa corrói). Cátodo: polo positivo, REDUÇÃO (ganha elétrons, a placa engrossa). Elétrons vão do ânodo ao cátodo.","Ácido libera H+ (H3O+) em água. Base libera OH-. Neutralização: ácido + base → sal + água.","pH = -log[H+]. pH < 7 ácido, = 7 neutro, > 7 básico (a 25 °C). pH + pOH = 14. Cada unidade = fator 10 na [H+]."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Propriedades coligativas: o que são</b>?","alts":["6,02 x 10^23 partículas (constante de Avogadro). A massa de 1 mol em gramas = massa molar.","Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","C1 x V1 = C2 x V2 (a quantidade de soluto não muda, só o volume aumenta).","1) Escreva e balanceie a equação. 2) Relacione mols pelos coeficientes. 3) Converta para a unidade pedida (massa, volume, partículas). Atenção a pureza e rendimento."],"certa":1,"coment":"💡 COLIGATIVA = conta as partículas (\"colig\" = coleção): não importa QUEM, importa QUANTAS."},{"enun":"Complete: Ácido carboxílico + álcool → _____ + água. Esse processo é a esterificação.","alts":["glicerina","biodiesel","éster","transesterificação"],"certa":2,"coment":"Ácido carboxílico + álcool → <b>éster</b> + água. Esse processo é a <b>esterificação</b>."},{"enun":"Qual alternativa explica <b>Eletronegatividade: tendência na tabela</b>?","alts":["Homogênea: uma fase (água e sal dissolvido, ar). Heterogênea: duas ou mais fases (água e óleo, granito).","Decantação: sólido-líquido ou líquidos imiscíveis (funil de bromo para água e óleo). Filtração: sólido retido no filtro. Centrifugação: acelera a decantação (separar plasma do sangue).","Simples: sólido dissolvido em líquido (água e sal). Fracionada: líquidos miscíveis com pontos de ebulição diferentes (petróleo, álcool e água).","Aumenta para cima e para a direita. Ordem a decorar: F > O > N > Cl > Br > I > S > C > P > H (\"Fui Ontem No Clube, Briguei, I Saí Correndo Para Hospital\")."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Exemplos de efeito crioscópico e ebulioscópico</b>?","alts":["Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","Sal nas estradas derrete o gelo (baixa o ponto de congelamento). Água com sal ferve a temperatura maior. Aditivo no radiador.","Comum: C = massa do soluto (g) / volume (L). Molaridade: M = mols do soluto / volume (L). Relação: C = M x massa molar.","τ = massa do soluto / massa da solução. Em % basta multiplicar por 100. Ex.: álcool 70% em massa."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Por que plásticos comuns causam problema ambiental</b>?","alts":["Aterro sanitário (impermeabilizado, trata o chorume e o gás) é melhor que lixão. Compostagem: matéria orgânica vira adubo. Incineração reduz volume mas emite gases.","Adição: monômeros com dupla ligação se somam sem perder nada (polietileno, PVC, isopor). Condensação: monômeros se unem liberando molécula pequena, como água (PET, náilon).","São muito estáveis e quase não biodegradáveis; persistem por séculos e geram microplásticos. Alternativas: reciclagem, plásticos biodegradáveis (PLA).","Prevenir resíduos, usar matérias-primas renováveis, catalisadores, solventes menos tóxicos, economia de átomos e eficiência energética."],"certa":2,"coment":""},{"enun":"Qual o pH de uma solução neutra a 25 °C?","alts":["monóxido de carbono","6,02 x 10^23","7","10"],"certa":2,"coment":"pH + pOH = 14."},{"enun":"Qual alternativa explica <b>Meia-vida: definição e cálculo</b>?","alts":["Alfa: núcleo de He (2p+2n), pouco penetrante, A -4 e Z -2. Beta: elétron, Z +1, A igual. Gama: onda eletromagnética, muito penetrante, sem massa.","Metal mais reativo (menor potencial de redução, ex.: zinco ou magnésio) é ligado ao ferro para oxidar no lugar dele. Ex.: cascos de navio, galvanização.","Tempo para metade dos núcleos decair. Após n meias-vidas sobra m0 / 2^n. Ex.: 3 meias-vidas → 1/8.","Processo NÃO espontâneo: usa corrente elétrica para provocar reação redox. Usada para obter alumínio, cloro, soda, galvanoplastia (cromar, niquelar)."],"certa":2,"coment":"💡 Cada meia-vida corta pela metade: 100 → 50 → 25 → 12,5."},{"enun":"Qual alternativa explica <b>Título e porcentagem em massa</b>?","alts":["τ = massa do soluto / massa da solução. Em % basta multiplicar por 100. Ex.: álcool 70% em massa.","22,4 L por mol (0 °C, 1 atm). Nas CATP (25 °C, 1 atm) cerca de 24,5 L.","O que acaba primeiro e limita a quantidade de produto. O outro está em excesso. Compare a proporção estequiométrica com a quantidade disponível.","1) Escreva e balanceie a equação. 2) Relacione mols pelos coeficientes. 3) Converta para a unidade pedida (massa, volume, partículas). Atenção a pureza e rendimento."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Funções orgânicas: grupos característicos (1)</b>?","alts":["1 met, 2 et, 3 prop, 4 but, 5 pent, 6 hex, 7 hept, 8 oct. Infixo: an (simples), en (dupla), in (tripla).","Álcool: -OH em carbono saturado. Fenol: -OH no anel aromático. Aldeído: -CHO na ponta. Cetona: C=O no meio. Ácido carboxílico: -COOH.","Etanol: renovável (cana), CO2 emitido é reabsorvido no plantio, menos poluentes de enxofre. Gasolina: fóssil, rende mais energia por litro.","Ácido carboxílico + álcool → éster + água. Reação reversível. Ésteres dão aroma de frutas."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Alotropia: exemplos do carbono e oxigênio</b>?","alts":["Coagulação/floculação (sulfato de alumínio forma flocos), decantação, filtração (areia e cascalho), desinfecção (cloro) e fluoretação.","Carbono: grafite (conduz, macio), diamante (duro, isolante), fulereno, grafeno. Oxigênio: O2 e O3 (ozônio).","Cátion: perdeu elétrons, carga positiva (metais tendem a formar). Ânion: ganhou elétrons, carga negativa (ametais).","Sólidos com altos pontos de fusão; conduzem corrente quando fundidos ou em solução aquosa (íons livres), não no estado sólido."],"certa":1,"coment":""},{"enun":"Complete: Óleo + álcool (com catalisador) → _____ + glicerina: é a transesterificação.","alts":["éster","condensação","adição","biodiesel"],"certa":3,"coment":"Óleo + álcool (com catalisador) → <b>biodiesel</b> + <b>glicerina</b>: é a <b>transesterificação</b>."},{"enun":"Qual alternativa explica <b>Ácidos e bases de Arrhenius</b>?","alts":["Processo NÃO espontâneo: usa corrente elétrica para provocar reação redox. Usada para obter alumínio, cloro, soda, galvanoplastia (cromar, niquelar).","Aumentar pressão desloca para o lado com MENOR número de mols de gás. Diminuir, para o lado com mais mols.","Ácido libera H+ (H3O+) em água. Base libera OH-. Neutralização: ácido + base → sal + água.","C-14 tem meia-vida de ~5.730 anos; serve para datar restos de seres vivos de até ~50 mil anos."],"certa":2,"coment":""},{"enun":"Certo ou errado? O catalisador desloca o equilíbrio no sentido dos produtos.","alts":["Certo","Errado"],"certa":1,"coment":"Catalisador acelera os dois sentidos igualmente: o equilíbrio chega mais rápido, mas não se desloca."},{"enun":"Qual alternativa explica <b>Forças intermoleculares em ordem de intensidade</b>?","alts":["Físico: não forma substância nova (mudança de estado, dissolução). Químico: forma nova substância (queima, ferrugem, cozimento).","Ligação de hidrogênio (H ligado a F, O ou N) > dipolo-dipolo > dipolo induzido (London). Mais forte = maior ponto de ebulição.","Aumenta para baixo no grupo (mais camadas) e para a esquerda no período (menos prótons puxando). Frâncio é o maior.","Homogênea: uma fase (água e sal dissolvido, ar). Heterogênea: duas ou mais fases (água e óleo, granito)."],"certa":1,"coment":"💡 Ligação de hidrogênio só com \"FON\": H ligado a F, O ou N."},{"enun":"Complete: O nome \"but-2-eno\" indica cadeia com _____ carbonos e uma ligação dupla no carbono 2.","alts":["4","22,4","C2·V2","2"],"certa":0,"coment":"O nome \"but-2-eno\" indica cadeia com <b>4</b> carbonos e uma ligação <b>dupla</b> no carbono <b>2</b>."},{"enun":"Certo ou errado? O gelo flutua porque é mais denso que a água líquida.","alts":["Certo","Errado"],"certa":1,"coment":"Flutua porque é MENOS denso: as ligações de hidrogênio formam uma rede com espaços vazios."},{"enun":"Complete: Número de massa A = número de _____ + número de nêutrons. O número atômico Z é o número de prótons.","alts":["polares","semelhante","prótons","iônica"],"certa":2,"coment":"Número de massa A = número de <b>prótons</b> + número de <b>nêutrons</b>. O número atômico Z é o número de <b>prótons</b>."},{"enun":"Qual alternativa explica <b>R–CHO (carbonila na ponta)</b>?","alts":["Aldeído","Éter","Amida","Amina"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>R–CONH2</b>?","alts":["Aldeído","Éter","Éster","Amida"],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Por que guardar alimentos na geladeira os conserva</b>?","alts":["Diminui a energia de ativação, acelerando a reação. Não é consumido e NÃO altera o ΔH nem o equilíbrio (só faz chegar a ele mais rápido).","Tempo para metade dos núcleos decair. Após n meias-vidas sobra m0 / 2^n. Ex.: 3 meias-vidas → 1/8.","Temperatura menor diminui a velocidade das reações químicas e da atividade microbiana.","Oxidação: perde elétrons, NOX aumenta (agente redutor). Redução: ganha elétrons, NOX diminui (agente oxidante). \"Quem oxida é redutor\"."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Separação de misturas: decantação, filtração, centrifugação</b>?","alts":["Carbono: grafite (conduz, macio), diamante (duro, isolante), fulereno, grafeno. Oxigênio: O2 e O3 (ozônio).","IsótoPos: mesmo nº de Prótons (mesmo elemento). IsóbAros: mesma massa (A). IsótoNos: mesmo nº de Nêutrons.","Decantação: sólido-líquido ou líquidos imiscíveis (funil de bromo para água e óleo). Filtração: sólido retido no filtro. Centrifugação: acelera a decantação (separar plasma do sangue).","Simples: sólido dissolvido em líquido (água e sal). Fracionada: líquidos miscíveis com pontos de ebulição diferentes (petróleo, álcool e água)."],"certa":2,"coment":""}]},"fis":{"tema":"Física","ic":"⚡","lista":[{"enun":"Qual alternativa explica <b>Vantagens e desvantagens da hidrelétrica</b>?","alts":["Luz de frequência suficiente arranca elétrons de um metal; depende da frequência, não da intensidade. Base das células solares e explicação de Einstein para o fóton.","Renovável, baixa emissão na operação. Mas alaga grandes áreas, desloca populações, afeta peixes e emite metano da vegetação submersa.","Corrente elétrica gera campo magnético ao redor do fio. Base dos eletroímãs e motores.","E = P·Δt. Em kWh: potência em kW x horas de uso. Ex.: chuveiro de 5.000 W por 0,5 h/dia em 30 dias = 75 kWh."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>3ª Lei de Newton (ação e reação)</b>?","alts":["Sem atrito: Ec + Ep = constante. Ex.: na montanha-russa, v no ponto mais baixo = √(2gh).","Ec = m·v²/2. Epg = m·g·h. Epe = k·x²/2.","Forças de mesma intensidade, mesma direção, sentidos opostos, aplicadas em CORPOS DIFERENTES (por isso não se anulam).","Massa (kg) é a quantidade de matéria, igual em qualquer lugar. Peso é força: P = m·g (newtons), varia com a gravidade."],"certa":2,"coment":"💡 Ação e reação em corpos DIFERENTES: por isso nunca se anulam."},{"enun":"Qual alternativa explica <b>Lançamento oblíquo: o que acontece em cada eixo</b>?","alts":["MUV com a = g ≈ 10 m/s². Sem resistência do ar, todos os corpos caem juntos, independentemente da massa. h = g·t²/2.","Área sob a curva = deslocamento. Inclinação (coeficiente angular) = aceleração.","Horizontal: MU (velocidade constante). Vertical: MUV (g para baixo). Alcance máximo com ângulo de 45°.","v = Δs / Δt. Para converter: km/h ÷ 3,6 = m/s; m/s x 3,6 = km/h."],"certa":2,"coment":"💡 Horizontal \"anda reto\" (MU), vertical \"sobe e desce\" (MUV). Ângulos complementares (30° e 60°) têm o mesmo alcance."},{"enun":"Qual alternativa explica <b>Ressonância</b>?","alts":["Sistema recebe energia na sua frequência natural e vibra com amplitude máxima. Ex.: taça quebrando com a voz, sintonizar rádio.","Altura: frequência (agudo x grave). Intensidade: amplitude, volume (decibéis). Timbre: forma da onda, distingue instrumentos.","Imagem virtual, direita, do mesmo tamanho, simétrica (inverte esquerda-direita). Girar o espelho em α gira o raio refletido em 2α.","A luz azul (menor comprimento de onda) é mais espalhada pelas moléculas do ar."],"certa":0,"coment":""},{"enun":"Certo ou errado? Durante a fervura, a temperatura da água continua subindo enquanto houver aquecimento.","alts":["Certo","Errado"],"certa":1,"coment":"Durante a mudança de estado a temperatura fica constante: o calor é usado para mudar o estado (calor latente)."},{"enun":"Qual alternativa explica <b>Função do fio terra</b>?","alts":["Polos iguais se repelem e opostos se atraem. Não existe monopolo: cortar um ímã gera dois ímãs. Bússola aponta para o polo sul magnético (perto do norte geográfico).","Luz de frequência suficiente arranca elétrons de um metal; depende da frequência, não da intensidade. Base das células solares e explicação de Einstein para o fóton.","Inverno: resistência MENOR → mais corrente → mais potência (P = U²/R) → água mais quente.","Oferecer caminho de baixa resistência para a corrente de fuga, protegendo quem toca no aparelho."],"certa":3,"coment":""},{"enun":"Um corpo de 2 kg está a 5 m de altura (g = 10). Qual sua energia potencial em joules?","alts":["5000","100","20","12"],"certa":1,"coment":"Ep = m·g·h = 2·10·5."},{"enun":"Complete: Empuxo: E = _____ · V(submerso) · g.","alts":["divergente","d(líquido)","menor","convergente"],"certa":1,"coment":"Empuxo: E = <b>d(líquido)</b> · <b>V(submerso)</b> · g."},{"enun":"Qual alternativa explica <b>Energia elétrica consumida e conta de luz</b>?","alts":["Corrente elétrica gera campo magnético ao redor do fio. Base dos eletroímãs e motores.","P = U·i = R·i² = U²/R.","Luz de frequência suficiente arranca elétrons de um metal; depende da frequência, não da intensidade. Base das células solares e explicação de Einstein para o fóton.","E = P·Δt. Em kWh: potência em kW x horas de uso. Ex.: chuveiro de 5.000 W por 0,5 h/dia em 30 dias = 75 kWh."],"certa":3,"coment":"💡 Conta de luz: kW x h. Lembre de dividir os watts por 1.000."},{"enun":"Qual alternativa explica <b>Queda livre</b>?","alts":["v² = v0² + 2·a·Δs. Use quando o problema não fala de tempo.","Área sob a curva = deslocamento. Inclinação (coeficiente angular) = aceleração.","MUV com a = g ≈ 10 m/s². Sem resistência do ar, todos os corpos caem juntos, independentemente da massa. h = g·t²/2.","s = s0 + v·t. Velocidade constante, aceleração zero. Gráfico s x t é uma reta."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Velocidade média</b>?","alts":["v = Δs / Δt. Para converter: km/h ÷ 3,6 = m/s; m/s x 3,6 = km/h.","v² = v0² + 2·a·Δs. Use quando o problema não fala de tempo.","Horizontal: MU (velocidade constante). Vertical: MUV (g para baixo). Alcance máximo com ângulo de 45°.","Área sob a curva = deslocamento. Inclinação (coeficiente angular) = aceleração."],"certa":0,"coment":"💡 Para converter: de km/h para m/s \"desce dividindo por 3,6\"; de m/s para km/h \"sobe multiplicando\"."},{"enun":"Qual alternativa explica <b>2ª Lei e máquinas térmicas</b>?","alts":["p·V/T = constante (T em kelvin). Isotérmica: pV constante. Isobárica: V/T constante. Isovolumétrica: p/T constante.","Pressão maior eleva o ponto de ebulição da água (acima de 100 °C).","Condução: contato, partícula a partícula (metais). Convecção: correntes no fluido (ar-condicionado no alto, freezer em cima). Irradiação: ondas eletromagnéticas, inclusive no vácuo (Sol).","Nenhuma máquina converte todo calor em trabalho. Rendimento de Carnot: η = 1 - Tfria/Tquente (em K)."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Equação dos pontos conjugados e aumento</b>?","alts":["Um objeto reflete a cor que vemos e absorve as outras. Branco reflete todas; preto absorve todas (esquenta mais ao sol).","Imagem virtual, direita, do mesmo tamanho, simétrica (inverte esquerda-direita). Girar o espelho em α gira o raio refletido em 2α.","1/f = 1/p + 1/p'. A = -p'/p = i/o. Vergência V = 1/f (em dioptrias, f em metros: \"graus\").","Altura: frequência (agudo x grave). Intensidade: amplitude, volume (decibéis). Timbre: forma da onda, distingue instrumentos."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Lei da gravitação universal</b>?","alts":["F = G·M·m/d². Dobrar a distância → força cai para 1/4.","P = energia / tempo (W = J/s). Rendimento η = potência útil / potência total. 1 kWh = 3,6 x 10^6 J.","Ec = m·v²/2. Epg = m·g·h. Epe = k·x²/2.","I = F·Δt = ΔQ. Airbag e capacete aumentam o tempo de colisão, diminuindo a força."],"certa":0,"coment":""},{"enun":"Complete: Transformadores só funcionam com corrente _____, porque dependem da variação do fluxo magnético (lei de Faraday).","alts":["alternada","tensão","P·Δt","corrente"],"certa":0,"coment":"Transformadores só funcionam com corrente <b>alternada</b>, porque dependem da <b>variação do fluxo magnético</b> (lei de Faraday)."},{"enun":"Qual alternativa explica <b>Ímãs: propriedades básicas</b>?","alts":["Polos iguais se repelem e opostos se atraem. Não existe monopolo: cortar um ímã gera dois ímãs. Bússola aponta para o polo sul magnético (perto do norte geográfico).","Oferecer caminho de baixa resistência para a corrente de fuga, protegendo quem toca no aparelho.","U = R·i.","i = Q/Δt (ampère = C/s). Sentido convencional: do polo + para o -."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Função do fusível e do disjuntor</b>?","alts":["Interromper o circuito quando a corrente passa do limite, evitando superaquecimento e incêndio.","F = k·|Q1|·|Q2| / d². Cargas iguais se repelem, opostas se atraem.","Polos iguais se repelem e opostos se atraem. Não existe monopolo: cortar um ímã gera dois ímãs. Bússola aponta para o polo sul magnético (perto do norte geográfico).","R = ρ·L/A. Fio mais longo → mais resistência; fio mais grosso → menos resistência."],"certa":0,"coment":""},{"enun":"Na prensa hidráulica, A2 = 10·A1. Se F1 = 50 N, quanto vale F2 (N)?","alts":["0,5","100","12","500"],"certa":3,"coment":"F1/A1 = F2/A2."},{"enun":"Certo ou errado? No lançamento oblíquo, a velocidade horizontal diminui até o ponto mais alto.","alts":["Certo","Errado"],"certa":1,"coment":"A componente horizontal é constante (MU). Quem diminui até zero, no ponto mais alto, é a componente VERTICAL."},{"enun":"Qual alternativa explica <b>Conservação da energia mecânica</b>?","alts":["Ec = m·v²/2. Epg = m·g·h. Epe = k·x²/2.","Fat = μ·N. Atrito estático máximo é maior que o cinético (é mais difícil começar a empurrar). ABS evita travar a roda para manter atrito estático.","Forças de mesma intensidade, mesma direção, sentidos opostos, aplicadas em CORPOS DIFERENTES (por isso não se anulam).","Sem atrito: Ec + Ep = constante. Ex.: na montanha-russa, v no ponto mais baixo = √(2gh)."],"certa":3,"coment":"💡 Na queda, troca altura por velocidade: v = √(2gh), sem depender da massa."},{"enun":"Lente de vergência +2 di tem distância focal de quantos metros?","alts":["0,5","60","5000","30"],"certa":0,"coment":"V = 1/f, então f = 1/2 m."},{"enun":"Complete: 1ª lei de Ohm: U = _____. Potência: P = U·i.","alts":["variação do fluxo magnético","R·i","P·Δt","alternada"],"certa":1,"coment":"1ª lei de Ohm: U = <b>R·i</b>. Potência: P = <b>U·i</b>."},{"enun":"Qual alternativa explica <b>Usinas: transformações de energia</b>?","alts":["Hidrelétrica: potencial gravitacional → cinética → elétrica. Termelétrica: química → térmica → cinética → elétrica. Eólica: cinética do vento → elétrica. Todas (menos solar fotovoltaica) usam gerador com indução.","Interromper o circuito quando a corrente passa do limite, evitando superaquecimento e incêndio.","P = U·i = R·i² = U²/R.","E = P·Δt. Em kWh: potência em kW x horas de uso. Ex.: chuveiro de 5.000 W por 0,5 h/dia em 30 dias = 75 kWh."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Associação de resistores em paralelo</b>?","alts":["Oferecer caminho de baixa resistência para a corrente de fuga, protegendo quem toca no aparelho.","Variação do fluxo magnético induz corrente. Base dos geradores (usinas), transformadores, carregador por indução e cartão por aproximação.","Mesma tensão; 1/Req = 1/R1 + 1/R2 + ... Req menor que o menor resistor. Ligação das tomadas de casa.","E = P·Δt. Em kWh: potência em kW x horas de uso. Ex.: chuveiro de 5.000 W por 0,5 h/dia em 30 dias = 75 kWh."],"certa":2,"coment":"💡 Paralelo: \"cada um tem sua própria estrada\", a tensão é a mesma para todos."},{"enun":"Qual alternativa explica <b>Ondas mecânicas x eletromagnéticas</b>?","alts":["Só ocorre com ondas transversais (luz). Óculos polarizados filtram o brilho refletido.","1/f = 1/p + 1/p'. A = -p'/p = i/o. Vergência V = 1/f (em dioptrias, f em metros: \"graus\").","Mecânicas precisam de meio (som, ondas na água). Eletromagnéticas propagam-se no vácuo, a 3 x 10^8 m/s (luz, rádio, raios X).","v = λ·f. A frequência não muda quando a onda troca de meio; muda velocidade e comprimento de onda."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Espectro eletromagnético em ordem crescente de frequência</b>?","alts":["Mecânicas precisam de meio (som, ondas na água). Eletromagnéticas propagam-se no vácuo, a 3 x 10^8 m/s (luz, rádio, raios X).","v = λ·f. A frequência não muda quando a onda troca de meio; muda velocidade e comprimento de onda.","Fonte se aproximando: som percebido mais agudo (frequência maior). Afastando: mais grave. Usado em radar e ultrassom.","Rádio, micro-ondas, infravermelho, luz visível, ultravioleta, raios X, raios gama. Mais frequência = mais energia (E = h·f)."],"certa":3,"coment":"💡 \"Rádio Mostra Imagens Visíveis Usando Raios Gama\" (rádio, micro-ondas, infra, visível, UV, raios X, gama)."},{"enun":"Um chuveiro de 4.000 W fica ligado 30 min por dia. Quantos kWh consome em 30 dias?","alts":["5","11","12","60"],"certa":3,"coment":"4 kW x 0,5 h x 30."},{"enun":"Qual alternativa explica <b>Reflexão total: condição e aplicação</b>?","alts":["Luz indo do meio mais refringente para o menos refringente com ângulo maior que o limite. Aplicação: fibra óptica, brilho do diamante.","Imagem virtual, direita, do mesmo tamanho, simétrica (inverte esquerda-direita). Girar o espelho em α gira o raio refletido em 2α.","Miopia: imagem antes da retina, vê mal de longe → lente divergente. Hipermetropia: depois da retina, vê mal de perto → convergente. Presbiopia (\"vista cansada\"): perda de acomodação → convergente.","Altura: frequência (agudo x grave). Intensidade: amplitude, volume (decibéis). Timbre: forma da onda, distingue instrumentos."],"certa":0,"coment":"💡 Só acontece saindo do meio \"mais denso opticamente\" para o \"menos denso\", com ângulo grande."},{"enun":"Qual alternativa explica <b>Dilatação térmica</b>?","alts":["Nenhuma máquina converte todo calor em trabalho. Rendimento de Carnot: η = 1 - Tfria/Tquente (em K).","ΔL = L0·α·ΔT. Juntas de dilatação em pontes e trilhos. Água anômala: entre 0 e 4 °C contrai ao aquecer.","Vácuo entre paredes impede condução e convecção; paredes espelhadas refletem a irradiação.","Sensível: muda temperatura, Q = m·c·ΔT. Latente: muda de estado sem mudar temperatura, Q = m·L."],"certa":1,"coment":""},{"enun":"Complete: Um corpo flutua quando sua densidade é _____ que a do líquido.","alts":["menor","d(líquido)","V(submerso)","massa"],"certa":0,"coment":"Um corpo flutua quando sua densidade é <b>menor</b> que a do líquido."},{"enun":"Complete: Equação de Torricelli: v² = _____.","alts":["v0² + 2·a·Δs","20","3,6","g ≈ 10 m/s²"],"certa":0,"coment":"Equação de Torricelli: v² = <b>v0² + 2·a·Δs</b>."},{"enun":"Qual alternativa explica <b>Trabalho de uma força</b>?","alts":["Sem atrito: Ec + Ep = constante. Ex.: na montanha-russa, v no ponto mais baixo = √(2gh).","τ = F·d·cos θ. Força perpendicular ao deslocamento não realiza trabalho. Trabalho da resultante = variação da energia cinética.","I = F·Δt = ΔQ. Airbag e capacete aumentam o tempo de colisão, diminuindo a força.","Não é falta de gravidade: estão em queda livre contínua ao redor da Terra, junto com a estação."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Calor específico: o que significa ter valor alto</b>?","alts":["C/5 = (F - 32)/9 = (K - 273)/5. K = C + 273.","p·V/T = constante (T em kelvin). Isotérmica: pV constante. Isobárica: V/T constante. Isovolumétrica: p/T constante.","Máquina térmica invertida: o compressor faz trabalho para retirar calor de dentro (evaporador) e liberar fora (serpentina atrás).","Precisa de muito calor para variar a temperatura. A água (c = 1 cal/g°C) esquenta e esfria devagar: regula o clima litorâneo."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Movimento circular uniforme: relações</b>?","alts":["s = s0 + v0·t + a·t²/2 e v = v0 + a·t.","Mesma velocidade linear nas bordas: R1·f1 = R2·f2. A polia menor gira mais rápido. Em mesmo eixo, mesma frequência.","v = ω·R; ω = 2π/T = 2πf; aceleração centrípeta a = v²/R (aponta para o centro).","MUV com a = g ≈ 10 m/s². Sem resistência do ar, todos os corpos caem juntos, independentemente da massa. h = g·t²/2."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Transformações gasosas</b>?","alts":["Q = τ + ΔU. O calor recebido vira trabalho e/ou aumento da energia interna.","Máquina térmica invertida: o compressor faz trabalho para retirar calor de dentro (evaporador) e liberar fora (serpentina atrás).","p·V/T = constante (T em kelvin). Isotérmica: pV constante. Isobárica: V/T constante. Isovolumétrica: p/T constante.","Pressão maior eleva o ponto de ebulição da água (acima de 100 °C)."],"certa":2,"coment":"💡 \"PV sobre T é constante\" (\"Piviti\"). Temperatura sempre em KELVIN."},{"enun":"Um carro parte do repouso com a = 2 m/s². Qual sua velocidade (m/s) após 5 s?","alts":["30","5000","10","12"],"certa":2,"coment":"v = v0 + a·t = 0 + 2·5."},{"enun":"Qual alternativa explica <b>Impulso</b>?","alts":["I = F·Δt = ΔQ. Airbag e capacete aumentam o tempo de colisão, diminuindo a força.","Fat = μ·N. Atrito estático máximo é maior que o cinético (é mais difícil começar a empurrar). ABS evita travar a roda para manter atrito estático.","Forças de mesma intensidade, mesma direção, sentidos opostos, aplicadas em CORPOS DIFERENTES (por isso não se anulam).","P = energia / tempo (W = J/s). Rendimento η = potência útil / potência total. 1 kWh = 3,6 x 10^6 J."],"certa":0,"coment":"💡 Airbag não reduz a variação de velocidade, aumenta o TEMPO, e por isso reduz a FORÇA."},{"enun":"Converta 27 °C para kelvin.","alts":["100","5000","500","300"],"certa":3,"coment":"K = C + 273."},{"enun":"Qual alternativa explica <b>Refração da luz: o que acontece</b>?","alts":["Só ocorre com ondas transversais (luz). Óculos polarizados filtram o brilho refletido.","Mudança de meio altera a velocidade e pode desviar o raio. Lei de Snell: n1·sen θ1 = n2·sen θ2. n = c/v.","Mecânicas precisam de meio (som, ondas na água). Eletromagnéticas propagam-se no vácuo, a 3 x 10^8 m/s (luz, rádio, raios X).","Miopia: imagem antes da retina, vê mal de longe → lente divergente. Hipermetropia: depois da retina, vê mal de perto → convergente. Presbiopia (\"vista cansada\"): perda de acomodação → convergente."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Como funciona a garrafa térmica</b>?","alts":["Nenhuma máquina converte todo calor em trabalho. Rendimento de Carnot: η = 1 - Tfria/Tquente (em K).","Vácuo entre paredes impede condução e convecção; paredes espelhadas refletem a irradiação.","C/5 = (F - 32)/9 = (K - 273)/5. K = C + 273.","p·V/T = constante (T em kelvin). Isotérmica: pV constante. Isobárica: V/T constante. Isovolumétrica: p/T constante."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Lei de Coulomb</b>?","alts":["i = Q/Δt (ampère = C/s). Sentido convencional: do polo + para o -.","U1/U2 = N1/N2. Só funciona com corrente ALTERNADA. Usado para elevar a tensão na transmissão (menos perda) e baixar no consumo.","U = R·i.","F = k·|Q1|·|Q2| / d². Cargas iguais se repelem, opostas se atraem."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Chuveiro elétrico: posição \"inverno\" x \"verão\"</b>?","alts":["Inverno: resistência MENOR → mais corrente → mais potência (P = U²/R) → água mais quente.","As duas patas estão no mesmo fio, praticamente no mesmo potencial: não há ddp significativa sobre o corpo.","U = R·i.","Variação do fluxo magnético induz corrente. Base dos geradores (usinas), transformadores, carregador por indução e cartão por aproximação."],"certa":0,"coment":"💡 Inverno = menor resistência = mais corrente = mais quente (P = U²/R: R menor, P maior)."},{"enun":"Certo ou errado? O efeito Doppler muda a frequência emitida pela fonte.","alts":["Certo","Errado"],"certa":1,"coment":"A fonte emite sempre a mesma frequência; o que muda é a frequência PERCEBIDA pelo observador."},{"enun":"Qual alternativa explica <b>Lente convergente x divergente</b>?","alts":["Imagem virtual, direita, do mesmo tamanho, simétrica (inverte esquerda-direita). Girar o espelho em α gira o raio refletido em 2α.","Só ocorre com ondas transversais (luz). Óculos polarizados filtram o brilho refletido.","1/f = 1/p + 1/p'. A = -p'/p = i/o. Vergência V = 1/f (em dioptrias, f em metros: \"graus\").","Convergente (bordas finas no ar): lupa, corrige hipermetropia. Divergente (bordas grossas): corrige miopia."],"certa":3,"coment":"💡 Bordas FINAS convergem; bordas GROSSAS divergem (no ar)."},{"enun":"Qual alternativa explica <b>Difração e interferência</b>?","alts":["Um objeto reflete a cor que vemos e absorve as outras. Branco reflete todas; preto absorve todas (esquenta mais ao sol).","1/f = 1/p + 1/p'. A = -p'/p = i/o. Vergência V = 1/f (em dioptrias, f em metros: \"graus\").","Difração: onda contorna obstáculos (ouvimos som atrás do muro). Interferência: superposição construtiva ou destrutiva (fone com cancelamento de ruído).","A luz azul (menor comprimento de onda) é mais espalhada pelas moléculas do ar."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Corrente elétrica</b>?","alts":["i = Q/Δt (ampère = C/s). Sentido convencional: do polo + para o -.","Mesma corrente; R eq = R1 + R2 + ... Se um queima, todos apagam (pisca-pisca antigo).","Mesma tensão; 1/Req = 1/R1 + 1/R2 + ... Req menor que o menor resistor. Ligação das tomadas de casa.","R = ρ·L/A. Fio mais longo → mais resistência; fio mais grosso → menos resistência."],"certa":0,"coment":""},{"enun":"Complete: Rendimento máximo de uma máquina térmica (Carnot): η = 1 − _____, com temperaturas em kelvin.","alts":["m·c·ΔT","m·L","T fria / T quente","irradiação"],"certa":2,"coment":"Rendimento máximo de uma máquina térmica (Carnot): η = 1 − <b>T fria / T quente</b>, com temperaturas em <b>kelvin</b>."},{"enun":"Quanto calor (cal) é preciso para aquecer 100 g de água de 20 °C a 70 °C? (c = 1 cal/g°C)","alts":["5000","5","100","300"],"certa":0,"coment":"Q = m·c·ΔT = 100·1·50."},{"enun":"Corrente (A) num resistor de 20 Ω ligado a 220 V?","alts":["30","11","5","60"],"certa":1,"coment":"i = U/R = 220/20."},{"enun":"Converta 108 km/h para m/s.","alts":["5","300","10","30"],"certa":3,"coment":"108 ÷ 3,6 = 30."},{"enun":"Qual alternativa explica <b>Potência e rendimento</b>?","alts":["Massa (kg) é a quantidade de matéria, igual em qualquer lugar. Peso é força: P = m·g (newtons), varia com a gravidade.","P = energia / tempo (W = J/s). Rendimento η = potência útil / potência total. 1 kWh = 3,6 x 10^6 J.","Não é falta de gravidade: estão em queda livre contínua ao redor da Terra, junto com a estação.","Ec = m·v²/2. Epg = m·g·h. Epe = k·x²/2."],"certa":1,"coment":""},{"enun":"Complete: A miopia é corrigida com lente _____; a hipermetropia e a presbiopia, com lente convergente.","alts":["eletromagnética","divergente","mecânica","vácuo"],"certa":1,"coment":"A miopia é corrigida com lente <b>divergente</b>; a hipermetropia e a presbiopia, com lente <b>convergente</b>."},{"enun":"Qual alternativa explica <b>Por que pássaros pousam em fios de alta tensão sem levar choque</b>?","alts":["As duas patas estão no mesmo fio, praticamente no mesmo potencial: não há ddp significativa sobre o corpo.","E = P·Δt. Em kWh: potência em kW x horas de uso. Ex.: chuveiro de 5.000 W por 0,5 h/dia em 30 dias = 75 kWh.","Mesma tensão; 1/Req = 1/R1 + 1/R2 + ... Req menor que o menor resistor. Ligação das tomadas de casa.","Oferecer caminho de baixa resistência para a corrente de fuga, protegendo quem toca no aparelho."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>1ª Lei de Newton (inércia)</b>?","alts":["τ = F·d·cos θ. Força perpendicular ao deslocamento não realiza trabalho. Trabalho da resultante = variação da energia cinética.","I = F·Δt = ΔQ. Airbag e capacete aumentam o tempo de colisão, diminuindo a força.","Não é falta de gravidade: estão em queda livre contínua ao redor da Terra, junto com a estação.","Corpo sem força resultante mantém repouso ou MRU. Ex.: passageiro é \"jogado\" para frente quando o ônibus freia; função do cinto de segurança."],"certa":3,"coment":"💡 Inércia = \"preguiça\" do corpo de mudar seu estado."},{"enun":"Qual alternativa explica <b>Calor sensível x calor latente</b>?","alts":["C/5 = (F - 32)/9 = (K - 273)/5. K = C + 273.","Precisa de muito calor para variar a temperatura. A água (c = 1 cal/g°C) esquenta e esfria devagar: regula o clima litorâneo.","Vácuo entre paredes impede condução e convecção; paredes espelhadas refletem a irradiação.","Sensível: muda temperatura, Q = m·c·ΔT. Latente: muda de estado sem mudar temperatura, Q = m·L."],"certa":3,"coment":"💡 \"Que macete\": Q = m·c·ΔT. Latente: Q = m·L (\"mL\" como mililitro). Na mudança de estado, a temperatura PARA."},{"enun":"Qual alternativa explica <b>Como funciona a geladeira</b>?","alts":["Sensível: muda temperatura, Q = m·c·ΔT. Latente: muda de estado sem mudar temperatura, Q = m·L.","Nenhuma máquina converte todo calor em trabalho. Rendimento de Carnot: η = 1 - Tfria/Tquente (em K).","p·V/T = constante (T em kelvin). Isotérmica: pV constante. Isobárica: V/T constante. Isovolumétrica: p/T constante.","Máquina térmica invertida: o compressor faz trabalho para retirar calor de dentro (evaporador) e liberar fora (serpentina atrás)."],"certa":3,"coment":""},{"enun":"Complete: Equação fundamental da onda: v = _____. Ao mudar de meio, a frequência não muda.","alts":["c/v","λ·f","vácuo","mecânica"],"certa":1,"coment":"Equação fundamental da onda: v = <b>λ·f</b>. Ao mudar de meio, a <b>frequência</b> não muda."},{"enun":"Qual alternativa explica <b>Efeito Doppler</b>?","alts":["A luz azul (menor comprimento de onda) é mais espalhada pelas moléculas do ar.","Fonte se aproximando: som percebido mais agudo (frequência maior). Afastando: mais grave. Usado em radar e ultrassom.","1/f = 1/p + 1/p'. A = -p'/p = i/o. Vergência V = 1/f (em dioptrias, f em metros: \"graus\").","Mudança de meio altera a velocidade e pode desviar o raio. Lei de Snell: n1·sen θ1 = n2·sen θ2. n = c/v."],"certa":1,"coment":"💡 Ambulância chegando = mais aguda; indo embora = mais grave."},{"enun":"Complete: Em queda livre, desprezando o ar, todos os corpos caem com a mesma aceleração, _____, independentemente da massa.","alts":["20","v0² + 2·a·Δs","g ≈ 10 m/s²","3,6"],"certa":2,"coment":"Em queda livre, desprezando o ar, todos os corpos caem com a mesma aceleração, <b>g ≈ 10 m/s²</b>, independentemente da <b>massa</b>."},{"enun":"Qual alternativa explica <b>Espelhos planos</b>?","alts":["Altura: frequência (agudo x grave). Intensidade: amplitude, volume (decibéis). Timbre: forma da onda, distingue instrumentos.","Luz indo do meio mais refringente para o menos refringente com ângulo maior que o limite. Aplicação: fibra óptica, brilho do diamante.","Imagem virtual, direita, do mesmo tamanho, simétrica (inverte esquerda-direita). Girar o espelho em α gira o raio refletido em 2α.","v = λ·f. A frequência não muda quando a onda troca de meio; muda velocidade e comprimento de onda."],"certa":2,"coment":""}]},"mat":{"tema":"Matemática","ic":"📐","lista":[{"enun":"Uma maquete na escala 1:100 tem área de 2 m². Qual a área real em m²?","alts":["24","20000","2","720"],"certa":1,"coment":"Área usa escala ao quadrado: 2 x 100² = 20.000 m²."},{"enun":"Complete: Mediana de 3, 7, 1, 9, 5: ordenando (1, 3, 5, 7, 9), a mediana é _____.","alts":["45","5","90","1/8"],"certa":1,"coment":"Mediana de 3, 7, 1, 9, 5: ordenando (1, 3, 5, 7, 9), a mediana é <b>5</b>."},{"enun":"Qual alternativa explica <b>Divisão proporcional</b>?","alts":["Soma de (valor x peso) / soma dos pesos. É como o Sisu calcula a nota com pesos por área.","Para dividir N em partes proporcionais a a, b, c: cada parte = N·(seu valor)/(a+b+c).","Escala = medida no desenho / medida real (mesma unidade). 1:50.000 → 1 cm = 500 m. Para área, a escala vai ao quadrado; para volume, ao cubo.","3 e 9: soma dos algarismos divisível por 3 ou 9. 4: os dois últimos algarismos formam número divisível por 4."],"certa":1,"coment":""},{"enun":"Complete: P(A ou B) = P(A) + P(B) − _____.","alts":["arranjo","combinação","P(A e B)","cima"],"certa":2,"coment":"P(A ou B) = P(A) + P(B) − <b>P(A e B)</b>."},{"enun":"Qual alternativa explica <b>Volume da pirâmide e do cone</b>?","alts":["V - A + F = 2 (vértices - arestas + faces) em poliedros convexos.","Vista superior, frontal e lateral: imagine o sólido \"achatado\" sobre cada plano. Tema frequente no ENEM.","V = (área da base x altura)/3. Cone: π·r²·h/3. Um cone tem 1/3 do volume do cilindro de mesma base e altura.","Fica 8 vezes maior (2³). A área fica 4 vezes maior (2²)."],"certa":2,"coment":"💡 \"Ponta tira dois terços\": pirâmide e cone = 1/3 do prisma/cilindro."},{"enun":"Média ponderada das notas 600 (peso 2) e 800 (peso 3)?","alts":["20000","2","720","24"],"certa":2,"coment":"(600·2 + 800·3)/5 = 3600/5."},{"enun":"Qual alternativa explica <b>Quando a mediana representa melhor os dados que a média</b>?","alts":["Quando há valores extremos (outliers), como salários com alguns muito altos: a média é puxada, a mediana não.","Multiplica: P(A e B) = P(A)·P(B).","P(A|B) = P(A e B)/P(B). O espaço amostral se reduz ao que já se sabe que aconteceu.","A dispersão dos dados em torno da média. Menor desvio padrão = dados mais homogêneos, mais regulares."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Área do triângulo equilátero e altura</b>?","alts":["Altura: L√3/2. Área: L²√3/4. Hexágono regular = 6 triângulos equiláteros: 6·L²√3/4.","Triângulo equilátero (60°), quadrado (90°) e hexágono (120°): os ângulos fecham 360° em volta de um ponto.","S = (n - 2)·180°. Triângulo 180°, quadrilátero 360°. Ângulo interno do regular = S/n.","Ângulos iguais → lados proporcionais. Razão k entre lados → razão k² entre áreas. Usada em sombras e alturas de prédios."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Se dobrarmos o raio de uma esfera, o que acontece com o volume</b>?","alts":["Fica 8 vezes maior (2³). A área fica 4 vezes maior (2²).","V = (área da base x altura)/3. Cone: π·r²·h/3. Um cone tem 1/3 do volume do cilindro de mesma base e altura.","V = área da base x altura. Cilindro: π·r²·h.","V = 4/3·π·r³. Área = 4·π·r²."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Probabilidade: definição</b>?","alts":["Quando \"pelo menos um\" aparece: P(pelo menos um) = 1 - P(nenhum).","A dispersão dos dados em torno da média. Menor desvio padrão = dados mais homogêneos, mais regulares.","P = casos favoráveis / casos possíveis. Valor entre 0 e 1.","P(A|B) = P(A e B)/P(B). O espaço amostral se reduz ao que já se sabe que aconteceu."],"certa":2,"coment":""},{"enun":"Complete: Se a &gt; 0, a parábola tem concavidade para _____ e o vértice é ponto de mínimo.","alts":["log a + log b","−b/a","c/a","cima"],"certa":3,"coment":"Se a &gt; 0, a parábola tem concavidade para <b>cima</b> e o vértice é ponto de <b>mínimo</b>."},{"enun":"Qual alternativa explica <b>Diferença entre \"pontos percentuais\" e \"por cento\"</b>?","alts":["Para achar o tempo: (1 + i)^t = M/C → t = log(M/C) / log(1 + i). Costumam dar os valores de log.","M = C·(1 + i)^t. Crescimento exponencial (progressão geométrica). Taxa e tempo na mesma unidade.","J = C·i·t; Montante M = C·(1 + i·t). Crescimento linear (progressão aritmética).","Taxa que vai de 10% para 12% subiu 2 pontos percentuais, mas aumentou 20% em termos relativos."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Escala: fórmula e cuidado com unidades</b>?","alts":["Direta: as grandezas aumentam juntas (mais produtos, mais preço). Inversa: uma aumenta e a outra diminui (mais operários, menos dias). Na inversa, inverta uma das razões.","Escala = medida no desenho / medida real (mesma unidade). 1:50.000 → 1 cm = 500 m. Para área, a escala vai ao quadrado; para volume, ao cubo.","Razão é a divisão a/b. Proporção é a igualdade entre duas razões: a/b = c/d → a·d = b·c (produto dos meios = produto dos extremos).","Número entre 1 e 10 vezes potência de 10. Ex.: 0,00052 = 5,2 x 10^-4. Na multiplicação somam-se os expoentes."],"certa":1,"coment":"💡 \"Comprimento: k. Área: k². Volume: k³.\""},{"enun":"Qual alternativa explica <b>Função exponencial: crescimento e decrescimento</b>?","alts":["f(x) = a·x + b. a = taxa de variação (inclinação); b = valor inicial (onde corta o eixo y). Ex.: corrida de táxi = bandeirada + preço por km.","log(a·b) = log a + log b; log(a/b) = log a - log b; log a^n = n·log a; mudança de base: log_b a = log a / log b.","f(x) = a·b^x. b > 1 cresce (bactérias, juros); 0 < b < 1 decresce (decaimento, depreciação).","f(x) = ax² + bx + c. xv = -b/(2a); yv = -Δ/(4a). a > 0: concavidade para cima (ponto mínimo); a < 0: para baixo (máximo)."],"certa":2,"coment":""},{"enun":"Complete: 1 m³ = _____ L; 1 dm³ = 1 L; 1 cm³ = 1 mL.","alts":["(n − 2)·180°","8","1.000","2"],"certa":2,"coment":"1 m³ = <b>1.000</b> L; 1 dm³ = <b>1</b> L; 1 cm³ = <b>1</b> mL."},{"enun":"Certo ou errado? Se a escala de um mapa dobra, a área representada também dobra.","alts":["Certo","Errado"],"certa":1,"coment":"A área é multiplicada por 4 (2²). Comprimento escala por k, área por k², volume por k³."},{"enun":"Qual o 10º termo da PA 3, 7, 11, ...?","alts":["39","1/2","5050","162"],"certa":0,"coment":"a10 = 3 + 9·4."},{"enun":"Qual alternativa explica <b>Função quadrática: vértice</b>?","alts":["Leia título, eixos e unidades. Cuidado com eixo que não começa no zero. Inclinação maior = variação mais rápida.","f(x) = ax² + bx + c. xv = -b/(2a); yv = -Δ/(4a). a > 0: concavidade para cima (ponto mínimo); a < 0: para baixo (máximo).","Soma = -b/a; produto = c/a.","f(x) = a·b^x. b > 1 cresce (bactérias, juros); 0 < b < 1 decresce (decaimento, depreciação)."],"certa":1,"coment":"💡 Vértice: \"X é menos b sobre dois a\". Boca para cima = sorriso = tem mínimo."},{"enun":"Qual alternativa explica <b>Aumento e desconto como fator multiplicativo</b>?","alts":["Para achar o tempo: (1 + i)^t = M/C → t = log(M/C) / log(1 + i). Costumam dar os valores de log.","Não. 1,1 x 0,9 = 0,99: fica 1% mais barato.","Taxa que vai de 10% para 12% subiu 2 pontos percentuais, mas aumentou 20% em termos relativos.","Aumento de i% → multiplique por (1 + i). Desconto de i% → por (1 - i). Aumento de 20% = x1,2; desconto de 15% = x0,85."],"certa":3,"coment":"💡 \"Aumentou? 1 + taxa. Diminuiu? 1 − taxa. Vários seguidos? Multiplica os fatores.\""},{"enun":"Qual alternativa explica <b>Razões trigonométricas no triângulo retângulo</b>?","alts":["sen = cateto oposto/hipotenusa; cos = adjacente/hipotenusa; tg = oposto/adjacente (\"SOH CAH TOA\").","Senos: a/sen A = b/sen B = c/sen C. Cossenos: a² = b² + c² - 2bc·cos A.","Triângulo equilátero (60°), quadrado (90°) e hexágono (120°): os ângulos fecham 360° em volta de um ponto.","a² = b² + c². Ternas: 3-4-5, 5-12-13, 8-15-17 e múltiplos (6-8-10)."],"certa":0,"coment":"💡 \"SOH CAH TOA\": Seno = Oposto/Hipotenusa, Cosseno = Adjacente/Hipotenusa, Tangente = Oposto/Adjacente."},{"enun":"Qual alternativa explica <b>Conversões de unidades que mais caem</b>?","alts":["1 m³ = 1.000 L; 1 dm³ = 1 L; 1 cm³ = 1 mL; 1 km² = 100 hectares; 1 ha = 10.000 m².","Razão é a divisão a/b. Proporção é a igualdade entre duas razões: a/b = c/d → a·d = b·c (produto dos meios = produto dos extremos).","Escala = medida no desenho / medida real (mesma unidade). 1:50.000 → 1 cm = 500 m. Para área, a escala vai ao quadrado; para volume, ao cubo.","Razão das áreas = (1/100)² = 1/10.000."],"certa":0,"coment":"💡 \"1 litro cabe num cubo de 10 cm de lado\" (1 dm³ = 1 L)."},{"enun":"Qual alternativa explica <b>Probabilidade de eventos independentes simultâneos</b>?","alts":["P(A ou B) = P(A) + P(B) - P(A e B).","P = casos favoráveis / casos possíveis. Valor entre 0 e 1.","Multiplica: P(A e B) = P(A)·P(B).","Quando \"pelo menos um\" aparece: P(pelo menos um) = 1 - P(nenhum)."],"certa":2,"coment":""},{"enun":"Um produto de R$ 200 tem desconto de 15%. Qual o novo preço em reais?","alts":["1210","5","25","170"],"certa":3,"coment":"200 x 0,85."},{"enun":"Qual o 5º termo da PG 2, 6, 18, ...?","alts":["24","5050","39","162"],"certa":3,"coment":"2 · 3⁴."},{"enun":"Qual alternativa explica <b>Semelhança de triângulos</b>?","alts":["Ângulos iguais → lados proporcionais. Razão k entre lados → razão k² entre áreas. Usada em sombras e alturas de prédios.","Retas paralelas cortadas por transversais determinam segmentos proporcionais.","sen = cateto oposto/hipotenusa; cos = adjacente/hipotenusa; tg = oposto/adjacente (\"SOH CAH TOA\").","Triângulo equilátero (60°), quadrado (90°) e hexágono (120°): os ângulos fecham 360° em volta de um ponto."],"certa":0,"coment":"💡 Lados x k → área x k²."},{"enun":"Complete: Relação de Euler: V − A + F = _____.","alts":["4/3·π·r³","π·r²·h/3","2","a1 + (n − 1)·r"],"certa":2,"coment":"Relação de Euler: V − A + F = <b>2</b>."},{"enun":"Certo ou errado? Se dobrarmos os lados de um quadrado, sua área também dobra.","alts":["Certo","Errado"],"certa":1,"coment":"A área quadruplica (2² = 4)."},{"enun":"Para f(x) = −x² + 4x, qual o valor máximo?","alts":["3","4","1","5"],"certa":1,"coment":"xv = 2; f(2) = −4 + 8 = 4."},{"enun":"Quanto mede cada ângulo interno de um hexágono regular (em graus)?","alts":["32","120","7","75"],"certa":1,"coment":"720/6."},{"enun":"Qual alternativa explica <b>Valores notáveis: 30°, 45°, 60°</b>?","alts":["S = (n - 2)·180°. Triângulo 180°, quadrilátero 360°. Ângulo interno do regular = S/n.","Retas paralelas cortadas por transversais determinam segmentos proporcionais.","Área: π·r². Comprimento: 2·π·r. No ENEM geralmente π ≈ 3 ou 3,14.","sen: 1/2, √2/2, √3/2. cos: √3/2, √2/2, 1/2. tg: √3/3, 1, √3."],"certa":3,"coment":"💡 Seno de 30, 45, 60: \"1, 2, 3\": √1/2, √2/2, √3/2. O cosseno é a mesma lista ao contrário."},{"enun":"Qual alternativa explica <b>Volume e área da esfera</b>?","alts":["Fica 8 vezes maior (2³). A área fica 4 vezes maior (2²).","V = área da base x altura. Cilindro: π·r²·h.","V = 4/3·π·r³. Área = 4·π·r².","V = (área da base x altura)/3. Cone: π·r²·h/3. Um cone tem 1/3 do volume do cilindro de mesma base e altura."],"certa":2,"coment":"💡 \"Quatro terços pi erre cubo\"."},{"enun":"Complete: Probabilidade de sair \"cara\" em 3 lançamentos seguidos de uma moeda: _____. Probabilidade de sair pelo menos uma \"coroa\": 7/8.","alts":["45","90","1/8","5"],"certa":2,"coment":"Probabilidade de sair \"cara\" em 3 lançamentos seguidos de uma moeda: <b>1/8</b>. Probabilidade de sair pelo menos uma \"coroa\": <b>7/8</b>."},{"enun":"Complete: log(a·b) = _____; log(a^n) = n·log a.","alts":["cima","mínimo","log a + log b","−b/a"],"certa":2,"coment":"log(a·b) = <b>log a + log b</b>; log(a^n) = <b>n·log a</b>."},{"enun":"Qual alternativa explica <b>Progressão aritmética (PA)</b>?","alts":["Termo geral: an = a1 + (n - 1)·r. Soma: Sn = (a1 + an)·n/2.","Termo geral: an = a1·q^(n-1). Soma finita: Sn = a1·(q^n - 1)/(q - 1). Soma infinita (|q| < 1): a1/(1 - q).","a = (y2 - y1)/(x2 - x1); depois substitua um ponto para achar b.","Quando \"pelo menos um\" aparece: P(pelo menos um) = 1 - P(nenhum)."],"certa":0,"coment":"💡 PA soma sempre o mesmo número (razão r). Soma dos termos: \"(primeiro + último) x quantidade / 2\", como o truque de Gauss."},{"enun":"Qual alternativa explica <b>Propriedades dos logaritmos</b>?","alts":["Monte a função quadrática e calcule o vértice. O yv dá o valor máximo/mínimo; o xv diz quando ocorre.","Δ = b² - 4ac; x = (-b ± √Δ)/(2a). Δ > 0: duas raízes; Δ = 0: uma; Δ < 0: nenhuma real.","f(x) = ax² + bx + c. xv = -b/(2a); yv = -Δ/(4a). a > 0: concavidade para cima (ponto mínimo); a < 0: para baixo (máximo).","log(a·b) = log a + log b; log(a/b) = log a - log b; log a^n = n·log a; mudança de base: log_b a = log a / log b."],"certa":3,"coment":"💡 \"Log transforma vezes em mais, dividir em menos, e o expoente pula para a frente.\""},{"enun":"Qual alternativa explica <b>Como funciona a TRI no ENEM</b>?","alts":["Questões fáceis, médias e difíceis valem diferente, e a coerência conta: errar fáceis e acertar difíceis sugere chute e reduz a nota. Nunca deixe em branco.","V = 4/3·π·r³. Área = 4·π·r².","Faça primeiro as questões rápidas (porcentagem, leitura de gráfico, proporção), marque as longas e volte depois. Pela TRI, acertar as fáceis é o que mais pesa.","Para dividir N em partes proporcionais a a, b, c: cada parte = N·(seu valor)/(a+b+c)."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Probabilidade condicional</b>?","alts":["P = casos favoráveis / casos possíveis. Valor entre 0 e 1.","Quando há valores extremos (outliers), como salários com alguns muito altos: a média é puxada, a mediana não.","P(A|B) = P(A e B)/P(B). O espaço amostral se reduz ao que já se sabe que aconteceu.","P(A ou B) = P(A) + P(B) - P(A e B)."],"certa":2,"coment":""},{"enun":"Complete: Soma dos ângulos internos de um polígono de n lados: _____. Num hexágono: 720°.","alts":["(n − 2)·180°","1/2","1","2·π·r"],"certa":0,"coment":"Soma dos ângulos internos de um polígono de n lados: <b>(n − 2)·180°</b>. Num hexágono: <b>720°</b>."},{"enun":"Complete: Aumento de 25% equivale a multiplicar por _____; desconto de 30% equivale a multiplicar por 0,7.","alts":["C·(1 + i·t)","1,25","C·(1 + i)^t","21"],"certa":1,"coment":"Aumento de 25% equivale a multiplicar por <b>1,25</b>; desconto de 30% equivale a multiplicar por <b>0,7</b>."},{"enun":"Qual alternativa explica <b>MMC e MDC: quando usar cada um</b>?","alts":["Para dividir N em partes proporcionais a a, b, c: cada parte = N·(seu valor)/(a+b+c).","Soma de (valor x peso) / soma dos pesos. É como o Sisu calcula a nota com pesos por área.","MMC: eventos que se repetem e voltam a coincidir (ônibus, remédios, luzes piscando). MDC: dividir em pedaços iguais do maior tamanho possível.","1 m³ = 1.000 L; 1 dm³ = 1 L; 1 cm³ = 1 mL; 1 km² = 100 hectares; 1 ha = 10.000 m²."],"certa":2,"coment":"💡 MMC = \"quando se encontram de novo\" (tempo). MDC = \"maior pedaço igual\" (corte)."},{"enun":"Qual o x do vértice de f(x) = x² − 6x + 5?","alts":["5","1","4","3"],"certa":3,"coment":"xv = −b/(2a) = 6/2."},{"enun":"Moda do conjunto 2, 3, 3, 5, 7, 3, 8?","alts":["1/2","7","12","3"],"certa":3,"coment":"Aparece 3 vezes."},{"enun":"Qual alternativa explica <b>Permutação, arranjo e combinação</b>?","alts":["P(A|B) = P(A e B)/P(B). O espaço amostral se reduz ao que já se sabe que aconteceu.","P = casos favoráveis / casos possíveis. Valor entre 0 e 1.","Permutação: n! (todos, ordem importa). Arranjo: n!/(n-p)! (alguns, ordem importa: pódio, senhas). Combinação: n!/(p!(n-p)!) (ordem não importa: comissões, grupos).","A dispersão dos dados em torno da média. Menor desvio padrão = dados mais homogêneos, mais regulares."],"certa":2,"coment":"💡 ARRanjo = ARRuma em ordem (pódio). COMBinação = COMBina em grupo (sem ordem)."},{"enun":"Média de 4, 6, 8 e 10?","alts":["12","7","10","3"],"certa":1,"coment":"28/4."},{"enun":"Qual alternativa explica <b>Média, mediana e moda</b>?","alts":["Troque dois elementos de lugar: se vira outra coisa (senha, pódio), a ordem importa (arranjo). Se é a mesma (grupo, salada), não importa (combinação).","A dispersão dos dados em torno da média. Menor desvio padrão = dados mais homogêneos, mais regulares.","Média: soma/quantidade. Mediana: valor central dos dados ordenados (com n par, média dos dois centrais). Moda: valor mais frequente.","P(A ou B) = P(A) + P(B) - P(A e B)."],"certa":2,"coment":"💡 MEDIana = MEIO da fila ordenada. MOda = o que está na MODA (mais aparece)."},{"enun":"Quantos litros cabem nessa caixa de 24 m³?","alts":["12","24","24000","39"],"certa":2,"coment":"1 m³ = 1.000 L."},{"enun":"Qual alternativa explica <b>Área do triângulo, retângulo, trapézio e losango</b>?","alts":["Senos: a/sen A = b/sen B = c/sen C. Cossenos: a² = b² + c² - 2bc·cos A.","Triângulo: b·h/2. Retângulo: b·h. Trapézio: (B + b)·h/2. Losango: D·d/2.","Altura: L√3/2. Área: L²√3/4. Hexágono regular = 6 triângulos equiláteros: 6·L²√3/4.","sen = cateto oposto/hipotenusa; cos = adjacente/hipotenusa; tg = oposto/adjacente (\"SOH CAH TOA\")."],"certa":1,"coment":"💡 Trapézio: \"base maior mais base menor, vezes altura, sobre dois\"."},{"enun":"Certo ou errado? A probabilidade de \"pelo menos um 6\" em dois lançamentos de dado é 2/6.","alts":["Certo","Errado"],"certa":1,"coment":"É 1 − (5/6)² = 11/36. Use o complementar (\"nenhum 6\")."},{"enun":"Um cubo tem 8 vértices e 6 faces. Quantas arestas?","alts":["24000","12","24","2"],"certa":1,"coment":"V − A + F = 2 → 8 − A + 6 = 2."},{"enun":"Quantas combinações de 3 camisas e 4 calças são possíveis?","alts":["12","1/2","3","7"],"certa":0,"coment":"Princípio multiplicativo: 3 x 4."},{"enun":"Complete: Juros simples: M = _____. Juros compostos: M = C·(1 + i)^t.","alts":["1,25","21","0,7","C·(1 + i·t)"],"certa":3,"coment":"Juros simples: M = <b>C·(1 + i·t)</b>. Juros compostos: M = <b>C·(1 + i)^t</b>."},{"enun":"Qual alternativa explica <b>Vistas e projeções ortogonais</b>?","alts":["Vista superior, frontal e lateral: imagine o sólido \"achatado\" sobre cada plano. Tema frequente no ENEM.","Fica 8 vezes maior (2³). A área fica 4 vezes maior (2²).","Reconhecer qual molde forma o sólido (cubo, cilindro, cone, prisma). Cilindro planificado = 2 círculos + retângulo de lado 2πr.","V = 4/3·π·r³. Área = 4·π·r²."],"certa":0,"coment":""},{"enun":"Quantos anagramas tem ARARA?","alts":["10","3","12","1/2"],"certa":0,"coment":"5!/(3!·2!) = 120/12."},{"enun":"Qual alternativa explica <b>Se um mapa tem escala 1:100, como se relacionam as áreas</b>?","alts":["Para dividir N em partes proporcionais a a, b, c: cada parte = N·(seu valor)/(a+b+c).","1 m³ = 1.000 L; 1 dm³ = 1 L; 1 cm³ = 1 mL; 1 km² = 100 hectares; 1 ha = 10.000 m².","MMC: eventos que se repetem e voltam a coincidir (ônibus, remédios, luzes piscando). MDC: dividir em pedaços iguais do maior tamanho possível.","Razão das áreas = (1/100)² = 1/10.000."],"certa":3,"coment":""},{"enun":"Complete: Em um mapa de escala 1:200.000, 1 cm representa _____ km.","alts":["2","1.000","8","1"],"certa":0,"coment":"Em um mapa de escala 1:200.000, 1 cm representa <b>2</b> km."},{"enun":"R$ 1.000 a juros compostos de 10% ao mês. Montante em reais após 2 meses?","alts":["25","1210","20000","170"],"certa":1,"coment":"1000 x 1,1²."},{"enun":"Qual alternativa explica <b>Soma e produto das raízes</b>?","alts":["Leia título, eixos e unidades. Cuidado com eixo que não começa no zero. Inclinação maior = variação mais rápida.","Soma = -b/a; produto = c/a.","a = (y2 - y1)/(x2 - x1); depois substitua um ponto para achar b.","log_b a = x ⇔ b^x = a. log 1 = 0; log_b b = 1."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Área e comprimento do círculo</b>?","alts":["Altura: L√3/2. Área: L²√3/4. Hexágono regular = 6 triângulos equiláteros: 6·L²√3/4.","S = (n - 2)·180°. Triângulo 180°, quadrilátero 360°. Ângulo interno do regular = S/n.","Triângulo: b·h/2. Retângulo: b·h. Trapézio: (B + b)·h/2. Losango: D·d/2.","Área: π·r². Comprimento: 2·π·r. No ENEM geralmente π ≈ 3 ou 3,14."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Lei dos senos e lei dos cossenos</b>?","alts":["Triângulo: b·h/2. Retângulo: b·h. Trapézio: (B + b)·h/2. Losango: D·d/2.","Senos: a/sen A = b/sen B = c/sen C. Cossenos: a² = b² + c² - 2bc·cos A.","Área: π·r². Comprimento: 2·π·r. No ENEM geralmente π ≈ 3 ou 3,14.","sen: 1/2, √2/2, √3/2. cos: √3/2, √2/2, 1/2. tg: √3/3, 1, √3."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Probabilidade complementar: quando usar</b>?","alts":["P(A|B) = P(A e B)/P(B). O espaço amostral se reduz ao que já se sabe que aconteceu.","Quando \"pelo menos um\" aparece: P(pelo menos um) = 1 - P(nenhum).","A dispersão dos dados em torno da média. Menor desvio padrão = dados mais homogêneos, mais regulares.","Multiplica: P(A e B) = P(A)·P(B)."],"certa":1,"coment":"💡 \"Pelo menos um\" → calcule o NENHUM e faça 1 menos."}]},"red":{"tema":"Redação","ic":"✍️","lista":[{"enun":"Qual alternativa explica <b>Onde x aonde</b>?","alts":["Por que: pergunta ou \"pelo qual\". Porque: explicação (pois). Por quê: fim de frase. Porquê: substantivo (\"o porquê\").","Onde: lugar fixo (verbo sem preposição a): \"onde você mora\". Aonde: movimento (a + onde): \"aonde você vai\". Na redação, use \"onde\" só para lugar físico; para ideias, prefira \"em que\".","Mal é o oposto de bem (advérbio/substantivo). Mau é o oposto de bom (adjetivo). \"Mal-estar\", \"mau exemplo\".","Gírias, \"a gente\", \"tipo\", \"né\", primeira pessoa do singular (\"eu acho\"), perguntas retóricas em excesso e clichês (\"hoje em dia\", \"desde os primórdios\")."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Panóptico e sociedade disciplinar</b>?","alts":["Sérgio Buarque de Holanda","Byung-Chul Han","Silvio Almeida","Michel Foucault"],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Modernidade líquida</b>?","alts":["Hannah Arendt","Zygmunt Bauman","Sérgio Buarque de Holanda","Michel Foucault"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>O que significa \"respeitar os direitos humanos\" na proposta</b>?","alts":["Agente (quem), ação (o quê), modo/meio (como), finalidade (para quê) e detalhamento (mais informação sobre qualquer um deles).","Ministérios (Educação, Saúde, Cidadania), Poder Legislativo, mídia/veículos de comunicação, escolas, ONGs, família, empresas. Evite agentes vagos como \"a sociedade\" ou \"alguém\".","Ser vaga (\"o governo deve resolver\") ou não se articular aos problemas apontados no desenvolvimento. Proponha uma solução para cada argumento.","Não propor violência, tortura, pena de morte, \"justiça com as próprias mãos\", exclusão de grupos. Desrespeito zera a C5."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Conectivos de causa e de consequência</b>?","alts":["Retomadas pouco variadas e ambíguas reduzem a nota na C4. Varie com expressões nominais: \"esse cenário\", \"tal panorama\", \"essa problemática\".","Além disso; Ademais; Paralelamente; Somado a isso; Outrossim; Em segundo plano.","Adversativos: mas, porém, contudo, todavia, no entanto, entretanto. Concessivos: embora, ainda que, mesmo que, apesar de (com verbo no subjuntivo nos três primeiros).","Causa: porque, visto que, já que, uma vez que, porquanto. Consequência: de modo que, de forma que, tanto que, por conseguinte."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Por que repetir \"isso\" e \"esse\" demais prejudica</b>?","alts":["Pronomes (esse, tal, isso), sinônimos, hiperônimos (\"o problema\", \"essa conjuntura\"), elipse. Evitam repetir as palavras do tema várias vezes.","A fim de, para que, com o intuito de, com o objetivo de, de modo a.","Retomadas pouco variadas e ambíguas reduzem a nota na C4. Varie com expressões nominais: \"esse cenário\", \"tal panorama\", \"essa problemática\".","Em primeiro lugar; Primeiramente; De início; Sob esse viés; Nesse sentido."],"certa":2,"coment":""},{"enun":"Complete: Estrutura de um parágrafo de desenvolvimento: _____ → repertório → análise → fechamento.","alts":["tópico frasal","argumentos","tese","tema"],"certa":0,"coment":"Estrutura de um parágrafo de desenvolvimento: <b>tópico frasal</b> → <b>repertório</b> → <b>análise</b> → <b>fechamento</b>."},{"enun":"Qual alternativa explica <b>Sociedade do cansaço</b>?","alts":["Pierre Bourdieu","Michel Foucault","Byung-Chul Han","Paulo Freire"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Pierre Bourdieu</b>?","alts":["Use instituições reconhecidas (IBGE, OMS, ONU, Ipea) sem inventar números precisos. Melhor: \"segundo o IBGE, milhões de brasileiros...\" do que um número errado.","2019: democratização do acesso ao cinema. 2020: estigma associado às doenças mentais. 2021: invisibilidade e registro civil. 2022: povos e comunidades tradicionais. 2023: trabalho de cuidado realizado pela mulher. 2024: herança africana no Brasil.","Violência simbólica e capital cultural: a escola e a cultura reproduzem desigualdades. Bom para educação, preconceito, acesso à cultura.","Sociedade do cansaço e da transparência: excesso de desempenho, esgotamento, exposição nas redes. Bom para saúde mental, trabalho, internet."],"certa":2,"coment":""},{"enun":"Complete: A introdução deve ter contextualização, apresentação do _____ e a tese, de preferência anunciando os dois argumentos.","alts":["análise","tópico frasal","repertório","tema"],"certa":3,"coment":"A introdução deve ter contextualização, apresentação do <b>tema</b> e a <b>tese</b>, de preferência anunciando os dois <b>argumentos</b>."},{"enun":"Certo ou errado? \"Porém\" e \"embora\" podem ser trocados livremente na mesma frase.","alts":["Certo","Errado"],"certa":1,"coment":"\"Porém\" é adversativo (verbo no indicativo, nova oração). \"Embora\" é concessivo e exige subjuntivo: \"Embora haja leis, ...\" x \"Há leis; porém, ...\"."},{"enun":"Qual alternativa explica <b>Conectivos para iniciar o 1º parágrafo de desenvolvimento</b>?","alts":["Causa: porque, visto que, já que, uma vez que, porquanto. Consequência: de modo que, de forma que, tanto que, por conseguinte.","A fim de, para que, com o intuito de, com o objetivo de, de modo a.","Portanto; Dessa forma; Logo; Diante do exposto; Assim; Em suma.","Em primeiro lugar; Primeiramente; De início; Sob esse viés; Nesse sentido."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Violência simbólica e capital cultural</b>?","alts":["Paulo Freire","Silvio Almeida","Pierre Bourdieu","Michel Foucault"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>O que a introdução precisa ter</b>?","alts":["Tópico frasal (ideia central ligada à tese) → repertório → explicação/análise (por quê, como, consequência) → fechamento ligando ao tema.","Retomada breve da tese e a proposta de intervenção completa (os 5 elementos). Pode fechar com retomada do repertório da introdução.","O ponto de vista que você vai defender sobre o tema. Ex.: \"os desafios decorrem da negligência estatal e da desinformação social\".","Contextualização (repertório de abertura), apresentação do tema com as palavras-chave do recorte e a tese, de preferência anunciando os dois argumentos."],"certa":3,"coment":"💡 \"Contexto → Tema → Tese\": abra com repertório, apresente o recorte e diga o que vai defender."},{"enun":"Qual alternativa explica <b>Por conseguinte</b>?","alts":["Conectivo de adição (= além disso).","Conectivo de meio/modo (= por meio de).","Conectivo de conclusão/consequência (= portanto).","Conectivo de adição (= igualmente, também)."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Fato social e anomia</b>?","alts":["Émile Durkheim","Paulo Freire","Sérgio Buarque de Holanda","Michel Foucault"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Paulo Freire</b>?","alts":["Art. 5º (igualdade e direitos individuais), art. 6º (direitos sociais: educação, saúde, moradia, lazer, segurança), art. 196 (saúde direito de todos e dever do Estado), art. 205 (educação).","Educação libertadora e crítica (\"se a educação sozinha não transforma a sociedade, sem ela tampouco a sociedade muda\"). Coringa para educação.","Violência simbólica e capital cultural: a escola e a cultura reproduzem desigualdades. Bom para educação, preconceito, acesso à cultura.","Use instituições reconhecidas (IBGE, OMS, ONU, Ipea) sem inventar números precisos. Melhor: \"segundo o IBGE, milhões de brasileiros...\" do que um número errado."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Agentes frequentes e úteis</b>?","alts":["Ministérios (Educação, Saúde, Cidadania), Poder Legislativo, mídia/veículos de comunicação, escolas, ONGs, família, empresas. Evite agentes vagos como \"a sociedade\" ou \"alguém\".","Não propor violência, tortura, pena de morte, \"justiça com as próprias mãos\", exclusão de grupos. Desrespeito zera a C5.","Ser vaga (\"o governo deve resolver\") ou não se articular aos problemas apontados no desenvolvimento. Proponha uma solução para cada argumento.","\"Cabe ao Ministério da Educação (agente) incluir educação digital no currículo (ação), por meio de oficinas nas escolas públicas (meio), a fim de reduzir a desinformação (finalidade). Essas oficinas, ministradas por especialistas, ... (detalhamento).\""],"certa":0,"coment":"💡 Um agente para cada argumento: assim a proposta conversa com o desenvolvimento."},{"enun":"Corrija: \"A desigualdade social, afeta o país.\"","alts":["A desigualdade social afeta o país.","30","Havia muitas pessoas no local.","trabalho de cuidado"],"certa":0,"coment":"Nunca use vírgula entre sujeito e verbo."},{"enun":"Qual alternativa explica <b>Competência 2</b>?","alts":["Compreender a proposta, tipo dissertativo-argumentativo e repertório produtivo.","Coesão: conectivos e retomadas.","Proposta de intervenção completa e que respeita os direitos humanos.","Norma padrão: ortografia, concordância, regência, pontuação, crase."],"certa":0,"coment":"💡 C2 = Compreender o tema + repertório."},{"enun":"Qual alternativa explica <b>Como usar os 9 dias até a prova para a redação</b>?","alts":["Escreva pelo menos 3 redações completas cronometradas (cerca de 1h10) e revise com as 5 competências. Monte 3 a 4 repertórios coringa e uma proposta de intervenção modelo.","Primeira frase do parágrafo, que anuncia o argumento. Ex.: \"Em primeiro lugar, a omissão governamental agrava o problema.\"","Cerca de 1h10 a 1h20 (rascunho rápido + passar a limpo). Muitos preferem fazer a redação logo depois de 1 bloco de questões, com a cabeça fresca.","Impessoal, fica no singular: \"Há muitos problemas\" / \"Havia dificuldades\" (não \"haviam\")."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Mediante</b>?","alts":["Conectivo de meio/modo (= por meio de).","Conectivo de conclusão/consequência (= portanto).","Conectivo de oposição (= mas, porém).","Conectivo de adição (= além disso)."],"certa":0,"coment":""},{"enun":"Complete: Refiro-me _____ questão social. Refiro-me a esse problema. Fui a pé.","alts":["Há","à","finalidade","Havia"],"certa":1,"coment":"Refiro-me <b>à</b> questão social. Refiro-me <b>a</b> esse problema. Fui <b>a</b> pé."},{"enun":"Qual alternativa explica <b>Competência 4</b>?","alts":["200 pontos cada (níveis 0, 40, 80, 120, 160, 200). Total 1000. Dois corretores; se a diferença for maior que 100 no total ou 80 em uma competência, um terceiro corrige.","Conhecimento dos mecanismos linguísticos de coesão: conectivos entre parágrafos e dentro deles, retomadas sem repetição.","Proposta de intervenção detalhada para o problema, respeitando os direitos humanos.","Selecionar, relacionar, organizar e interpretar informações em defesa de um ponto de vista (projeto de texto e argumentação consistente)."],"certa":1,"coment":"💡 C4 = Conectivos (coesão)."},{"enun":"Qual alternativa explica <b>Crase: regra básica</b>?","alts":["Impessoal, fica no singular: \"Há muitos problemas\" / \"Havia dificuldades\" (não \"haviam\").","A + a (preposição + artigo). Ocorre antes de palavra feminina quando o verbo ou nome exige \"a\". Nunca antes de verbo, masculino, pronomes pessoais e \"uma\". Ex.: \"Refiro-me à questão\".","Proibida. Errado: \"A desigualdade social, afeta o país.\" Certo: \"A desigualdade social afeta o país.\"","Por que: pergunta ou \"pelo qual\". Porque: explicação (pois). Por quê: fim de frase. Porquê: substantivo (\"o porquê\")."],"certa":1,"coment":"💡 \"Troque por masculino\": se virar \"ao\", tem crase (\"vou à escola\" → \"vou ao colégio\")."},{"enun":"Qual alternativa explica <b>O que torna um repertório \"produtivo\"</b>?","alts":["Educação libertadora e crítica (\"se a educação sozinha não transforma a sociedade, sem ela tampouco a sociedade muda\"). Coringa para educação.","Panóptico e sociedade disciplinar: vigilância e controle. Bom para tecnologia, privacidade, dados, sistema prisional.","Violência simbólica e capital cultural: a escola e a cultura reproduzem desigualdades. Bom para educação, preconceito, acesso à cultura.","Ser legitimado (fonte reconhecível), pertinente ao tema e, sobretudo, articulado ao argumento: precisa ser explicado e usado, não só citado."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Michel Foucault</b>?","alts":["Use instituições reconhecidas (IBGE, OMS, ONU, Ipea) sem inventar números precisos. Melhor: \"segundo o IBGE, milhões de brasileiros...\" do que um número errado.","Violência simbólica e capital cultural: a escola e a cultura reproduzem desigualdades. Bom para educação, preconceito, acesso à cultura.","Fato social (coercitivo, exterior, geral) e anomia (enfraquecimento das normas sociais). Bom para violência, desigualdade, instituições.","Panóptico e sociedade disciplinar: vigilância e controle. Bom para tecnologia, privacidade, dados, sistema prisional."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Diferença entre fuga ao tema e tangenciamento</b>?","alts":["Proposta de intervenção detalhada para o problema, respeitando os direitos humanos.","200 pontos cada (níveis 0, 40, 80, 120, 160, 200). Total 1000. Dois corretores; se a diferença for maior que 100 no total ou 80 em uma competência, um terceiro corrige.","Domínio da norma padrão da língua escrita: ortografia, acentuação, concordância, regência, pontuação e estrutura sintática (sem frases fragmentadas ou truncadas).","Fuga total zera. Tangenciar (abordar só o assunto amplo, não o recorte) limita a C2 a 40 pontos e afeta C3 e C5."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Conectivos para iniciar o 2º parágrafo de desenvolvimento</b>?","alts":["Pronomes (esse, tal, isso), sinônimos, hiperônimos (\"o problema\", \"essa conjuntura\"), elipse. Evitam repetir as palavras do tema várias vezes.","A fim de, para que, com o intuito de, com o objetivo de, de modo a.","Além disso; Ademais; Paralelamente; Somado a isso; Outrossim; Em segundo plano.","Portanto; Dessa forma; Logo; Diante do exposto; Assim; Em suma."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Mal x mau</b>?","alts":["Onde: lugar fixo (verbo sem preposição a): \"onde você mora\". Aonde: movimento (a + onde): \"aonde você vai\". Na redação, use \"onde\" só para lugar físico; para ideias, prefira \"em que\".","Mal é o oposto de bem (advérbio/substantivo). Mau é o oposto de bom (adjetivo). \"Mal-estar\", \"mau exemplo\".","Frases com mais de 3 ou 4 linhas sem pausa ou frases sem verbo principal prejudicam C1. Prefira períodos de 2 a 3 linhas.","Gírias, \"a gente\", \"tipo\", \"né\", primeira pessoa do singular (\"eu acho\"), perguntas retóricas em excesso e clichês (\"hoje em dia\", \"desde os primórdios\")."],"certa":1,"coment":"💡 Mal x Bem; Mau x Bom (troque e veja qual faz sentido)."},{"enun":"Qual alternativa explica <b>Competência 3</b>?","alts":["Selecionar, relacionar, organizar e interpretar informações em defesa de um ponto de vista (projeto de texto e argumentação consistente).","Fuga total zera. Tangenciar (abordar só o assunto amplo, não o recorte) limita a C2 a 40 pontos e afeta C3 e C5.","Compreender a proposta e desenvolver o tema dentro do tipo dissertativo-argumentativo, usando repertório sociocultural legitimado, pertinente e PRODUTIVO.","200 pontos cada (níveis 0, 40, 80, 120, 160, 200). Total 1000. Dois corretores; se a diferença for maior que 100 no total ou 80 em uma competência, um terceiro corrige."],"certa":0,"coment":"💡 C3 = Coerência dos argumentos (projeto de texto)."},{"enun":"Complete: \"Embora\", \"ainda que\" e \"mesmo que\" são conectivos _____ e exigem verbo no subjuntivo.","alts":["Diante do exposto","Dessa forma","Portanto","concessivos"],"certa":3,"coment":"\"Embora\", \"ainda que\" e \"mesmo que\" são conectivos <b>concessivos</b> e exigem verbo no <b>subjuntivo</b>."},{"enun":"Qual alternativa explica <b>Djamila Ribeiro / racismo estrutural (Silvio Almeida)</b>?","alts":["Fato social (coercitivo, exterior, geral) e anomia (enfraquecimento das normas sociais). Bom para violência, desigualdade, instituições.","Educação libertadora e crítica (\"se a educação sozinha não transforma a sociedade, sem ela tampouco a sociedade muda\"). Coringa para educação.","Ser legitimado (fonte reconhecível), pertinente ao tema e, sobretudo, articulado ao argumento: precisa ser explicado e usado, não só citado.","Racismo está nas estruturas (instituições, economia), não só em atos individuais. Bom para temas de raça, desigualdade e violência."],"certa":3,"coment":""},{"enun":"Certo ou errado? \"O governo deve resolver o problema da violência\" é uma proposta de intervenção completa.","alts":["Certo","Errado"],"certa":1,"coment":"Falta ação concreta, meio, finalidade e detalhamento; o agente também é vago (\"governo\")."},{"enun":"Qual alternativa explica <b>Repertório de dados: como usar com segurança</b>?","alts":["Use instituições reconhecidas (IBGE, OMS, ONU, Ipea) sem inventar números precisos. Melhor: \"segundo o IBGE, milhões de brasileiros...\" do que um número errado.","Banalidade do mal: pessoas comuns praticam atrocidades por obediência e falta de reflexão. Bom para violência, discurso de ódio, intolerância.","Modernidade líquida: relações frágeis, efêmeras e consumistas. Serve para temas de redes sociais, consumo, solidão, relações.","Panóptico e sociedade disciplinar: vigilância e controle. Bom para tecnologia, privacidade, dados, sistema prisional."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Outrossim</b>?","alts":["Conectivo de oposição (= mas, porém).","Conectivo de adição (= além disso).","Conectivo de adição (= igualmente, também).","Conectivo de causa (= porque, visto que)."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Conectivos de conclusão</b>?","alts":["Portanto; Dessa forma; Logo; Diante do exposto; Assim; Em suma.","Além disso; Ademais; Paralelamente; Somado a isso; Outrossim; Em segundo plano.","A fim de, para que, com o intuito de, com o objetivo de, de modo a.","Causa: porque, visto que, já que, uma vez que, porquanto. Consequência: de modo que, de forma que, tanto que, por conseguinte."],"certa":0,"coment":""},{"enun":"Certo ou errado? Usar repertório só citando o nome do autor, sem explicar, já garante 200 na C2.","alts":["Certo","Errado"],"certa":1,"coment":"O repertório precisa ser PRODUTIVO: articulado e explicado dentro do argumento."},{"enun":"Complete: \"A fim de\", \"com o intuito de\" e \"para que\" introduzem a _____; \"por meio de\" e \"mediante\" introduzem o meio.","alts":["agente","ação","meio/modo","finalidade"],"certa":3,"coment":"\"A fim de\", \"com o intuito de\" e \"para que\" introduzem a <b>finalidade</b>; \"por meio de\" e \"mediante\" introduzem o <b>meio</b>."},{"enun":"Tema da redação do ENEM 2023 (palavra-chave do trabalho)?","alts":["Havia muitas pessoas no local.","30","trabalho de cuidado","A desigualdade social afeta o país."],"certa":2,"coment":"\"Desafios para o enfrentamento da invisibilidade do trabalho de cuidado realizado pela mulher no Brasil\"."},{"enun":"Qual alternativa explica <b>Cidadão de papel</b>?","alts":["Zygmunt Bauman","Gilberto Dimenstein","Silvio Almeida","Pierre Bourdieu"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Conectivos de oposição (adversativos e concessivos)</b>?","alts":["Adversativos: mas, porém, contudo, todavia, no entanto, entretanto. Concessivos: embora, ainda que, mesmo que, apesar de (com verbo no subjuntivo nos três primeiros).","A fim de, para que, com o intuito de, com o objetivo de, de modo a.","Em primeiro lugar; Primeiramente; De início; Sob esse viés; Nesse sentido.","Causa: porque, visto que, já que, uma vez que, porquanto. Consequência: de modo que, de forma que, tanto que, por conseguinte."],"certa":0,"coment":"💡 \"Embora\" e \"ainda que\" pedem SUBJUNTIVO: \"Embora EXISTAM leis...\" (não \"existem\")."},{"enun":"Certo ou errado? Tangenciar o tema zera a redação.","alts":["Certo","Errado"],"certa":1,"coment":"Tangenciar limita a C2 (até 40 pontos) e prejudica outras competências. O que zera é a FUGA TOTAL ao tema."},{"enun":"Qual alternativa explica <b>Gilberto Dimenstein</b>?","alts":["\"O cidadão de papel\": direitos garantidos na lei, mas não na prática. Coringa para quase todo tema de direitos sociais.","Fato social (coercitivo, exterior, geral) e anomia (enfraquecimento das normas sociais). Bom para violência, desigualdade, instituições.","Art. 5º (igualdade e direitos individuais), art. 6º (direitos sociais: educação, saúde, moradia, lazer, segurança), art. 196 (saúde direito de todos e dever do Estado), art. 205 (educação).","Banalidade do mal: pessoas comuns praticam atrocidades por obediência e falta de reflexão. Bom para violência, discurso de ódio, intolerância."],"certa":0,"coment":"💡 \"Cidadão de PAPEL\": o direito está no papel, não na vida real."},{"enun":"Qual alternativa explica <b>Período muito longo ou truncado</b>?","alts":["Mal é o oposto de bem (advérbio/substantivo). Mau é o oposto de bom (adjetivo). \"Mal-estar\", \"mau exemplo\".","Frases com mais de 3 ou 4 linhas sem pausa ou frases sem verbo principal prejudicam C1. Prefira períodos de 2 a 3 linhas.","A + a (preposição + artigo). Ocorre antes de palavra feminina quando o verbo ou nome exige \"a\". Nunca antes de verbo, masculino, pronomes pessoais e \"uma\". Ex.: \"Refiro-me à questão\".","Onde: lugar fixo (verbo sem preposição a): \"onde você mora\". Aonde: movimento (a + onde): \"aonde você vai\". Na redação, use \"onde\" só para lugar físico; para ideias, prefira \"em que\"."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Competência 5</b>?","alts":["Proposta de intervenção completa e que respeita os direitos humanos.","Coesão: conectivos e retomadas.","Selecionar e organizar argumentos em defesa de um ponto de vista.","Norma padrão: ortografia, concordância, regência, pontuação, crase."],"certa":0,"coment":"💡 C5 = Conserto do problema (proposta)."},{"enun":"Qual alternativa explica <b>Banalidade do mal</b>?","alts":["Hannah Arendt","Pierre Bourdieu","Paulo Freire","Michel Foucault"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Porquanto</b>?","alts":["Conectivo de adição (= além disso).","Conectivo de causa (= porque, visto que).","Conectivo de meio/modo (= por meio de).","Conectivo de oposição (= mas, porém)."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>\"Haver\" no sentido de existir</b>?","alts":["Impessoal, fica no singular: \"Há muitos problemas\" / \"Havia dificuldades\" (não \"haviam\").","Gírias, \"a gente\", \"tipo\", \"né\", primeira pessoa do singular (\"eu acho\"), perguntas retóricas em excesso e clichês (\"hoje em dia\", \"desde os primórdios\").","Frases com mais de 3 ou 4 linhas sem pausa ou frases sem verbo principal prejudicam C1. Prefira períodos de 2 a 3 linhas.","Mal é o oposto de bem (advérbio/substantivo). Mau é o oposto de bom (adjetivo). \"Mal-estar\", \"mau exemplo\"."],"certa":0,"coment":"💡 \"HAVER = EXISTIR, fica no SINGULAR\": \"houve problemas\", \"havia leis\"."},{"enun":"Qual alternativa explica <b>Ademais</b>?","alts":["Conectivo de adição (= igualmente, também).","Conectivo de conclusão/consequência (= portanto).","Conectivo de adição (= além disso).","Conectivo de oposição (= mas, porém)."],"certa":2,"coment":""},{"enun":"Certo ou errado? \"Ele chegou mau-humorado\" está correto.","alts":["Certo","Errado"],"certa":1,"coment":"O certo é \"mal-humorado\": \"mal\" é o contrário de \"bem\" (bem-humorado)."},{"enun":"Qual alternativa explica <b>Quanto tempo reservar para a redação no 1º dia</b>?","alts":["Cerca de 1h10 a 1h20 (rascunho rápido + passar a limpo). Muitos preferem fazer a redação logo depois de 1 bloco de questões, com a cabeça fresca.","Proibida. Errado: \"A desigualdade social, afeta o país.\" Certo: \"A desigualdade social afeta o país.\"","Selecionar, relacionar, organizar e interpretar informações em defesa de um ponto de vista (projeto de texto e argumentação consistente).","Escreva pelo menos 3 redações completas cronometradas (cerca de 1h10) e revise com as 5 competências. Monte 3 a 4 repertórios coringa e uma proposta de intervenção modelo."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Estrutura de um parágrafo de desenvolvimento</b>?","alts":["Tópico frasal (ideia central ligada à tese) → repertório → explicação/análise (por quê, como, consequência) → fechamento ligando ao tema.","O ponto de vista que você vai defender sobre o tema. Ex.: \"os desafios decorrem da negligência estatal e da desinformação social\".","Retomada breve da tese e a proposta de intervenção completa (os 5 elementos). Pode fechar com retomada do repertório da introdução.","Primeira frase do parágrafo, que anuncia o argumento. Ex.: \"Em primeiro lugar, a omissão governamental agrava o problema.\""],"certa":0,"coment":"💡 \"TRAF\": Tópico frasal, Repertório, Análise, Fechamento."},{"enun":"Qual alternativa explica <b>Émile Durkheim</b>?","alts":["Violência simbólica e capital cultural: a escola e a cultura reproduzem desigualdades. Bom para educação, preconceito, acesso à cultura.","Fato social (coercitivo, exterior, geral) e anomia (enfraquecimento das normas sociais). Bom para violência, desigualdade, instituições.","Use instituições reconhecidas (IBGE, OMS, ONU, Ipea) sem inventar números precisos. Melhor: \"segundo o IBGE, milhões de brasileiros...\" do que um número errado.","\"O cidadão de papel\": direitos garantidos na lei, mas não na prática. Coringa para quase todo tema de direitos sociais."],"certa":1,"coment":"💡 Durkheim = \"fato social\" e \"anomia\" (sociedade sem regras firmes)."},{"enun":"Qual alternativa explica <b>Racismo estrutural</b>?","alts":["Zygmunt Bauman","Silvio Almeida","Gilberto Dimenstein","Hannah Arendt"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Competência 5</b>?","alts":["Conhecimento dos mecanismos linguísticos de coesão: conectivos entre parágrafos e dentro deles, retomadas sem repetição.","Fuga total zera. Tangenciar (abordar só o assunto amplo, não o recorte) limita a C2 a 40 pontos e afeta C3 e C5.","Proposta de intervenção detalhada para o problema, respeitando os direitos humanos.","Domínio da norma padrão da língua escrita: ortografia, acentuação, concordância, regência, pontuação e estrutura sintática (sem frases fragmentadas ou truncadas)."],"certa":2,"coment":"💡 C5 = Conserto do problema (proposta)."},{"enun":"Complete: O artigo _____ da Constituição diz que a saúde é direito de todos e dever do Estado.","alts":["30","8","6º","196"],"certa":3,"coment":"O artigo <b>196</b> da Constituição diz que a saúde é direito de todos e dever do <b>Estado</b>."},{"enun":"Certo ou errado? Na frase \"Assisti ao filme\", não há crase porque \"filme\" é masculino.","alts":["Certo","Errado"],"certa":0,"coment":"Antes de palavra masculina não há crase; aqui há só preposição + artigo masculino (\"ao\")."},{"enun":"Qual alternativa explica <b>Competência 4</b>?","alts":["Compreender a proposta, tipo dissertativo-argumentativo e repertório produtivo.","Norma padrão: ortografia, concordância, regência, pontuação, crase.","Proposta de intervenção completa e que respeita os direitos humanos.","Coesão: conectivos e retomadas."],"certa":3,"coment":"💡 C4 = Conectivos (coesão)."},{"enun":"Qual alternativa explica <b>Educação libertadora e crítica</b>?","alts":["Paulo Freire","Gilberto Dimenstein","Michel Foucault","Silvio Almeida"],"certa":0,"coment":""}]},"ling":{"tema":"Linguagens","ic":"📚","lista":[{"enun":"Qual alternativa explica <b>Aliteração x assonância</b>?","alts":["Troca de um termo por outro com relação de proximidade: autor pela obra (\"li Machado\"), parte pelo todo, marca pelo produto (\"Bombril\").","Comparação usa conectivo (\"Ela é forte como uma rocha\"). Metáfora é comparação implícita (\"Ela é uma rocha\").","Aliteração: repetição de consoantes (\"o rato roeu a roupa do rei de Roma\"). Assonância: repetição de vogais.","Antítese: ideias opostas lado a lado (\"riso e choro\"). Paradoxo: ideias opostas que parecem impossíveis juntas (\"amor é fogo que arde sem se ver\")."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Função poética</b>?","alts":["Foco no emissor: sentimentos, 1ª pessoa, interjeições.","Foco no assunto: informação objetiva (notícia).","Foco no canal: testar ou manter o contato.","Foco na forma da mensagem: ritmo, sonoridade, jogo de palavras."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Ironia</b>?","alts":["Dar características humanas a seres inanimados (\"o vento sussurrava\").","Repetição de sons consonantais.","Dizer o contrário do que se pensa, com crítica ou humor.","Exagero (\"chorei rios de lágrimas\")."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Metáfora x comparação</b>?","alts":["Troca de um termo por outro com relação de proximidade: autor pela obra (\"li Machado\"), parte pelo todo, marca pelo produto (\"Bombril\").","Aliteração: repetição de consoantes (\"o rato roeu a roupa do rei de Roma\"). Assonância: repetição de vogais.","Eufemismo: suaviza (\"ele partiu\" = morreu). Hipérbole: exagera (\"já te falei um milhão de vezes\").","Comparação usa conectivo (\"Ela é forte como uma rocha\"). Metáfora é comparação implícita (\"Ela é uma rocha\")."],"certa":3,"coment":"💡 Comparação tem \"como\"; metáfora \"esconde o como\"."},{"enun":"Qual alternativa explica <b>luego</b>?","alts":["depois, logo","pular","ontem","copo"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>\"Muy\" x \"mucho\"</b>?","alts":["Exprimir = espremer. Ganancia = lucro. Contestar = responder.","Sin embargo = no entanto (adversativo). Aunque = embora, ainda que (concessivo).","Muy antes de adjetivo e advérbio (muy bonito). Mucho antes de substantivo ou depois de verbo (mucho dinero, trabaja mucho).","Largo = comprido. Acordarse = lembrar-se. Brincar = pular."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Literatura contemporânea frequente no ENEM</b>?","alts":["Em São Paulo, ruptura com a arte acadêmica. Oswald de Andrade, Mário de Andrade, Anita Malfatti, Di Cavalcanti, Villa-Lobos. Valorização da cultura brasileira e linguagem coloquial.","Crítica social, análise psicológica, ironia, narrador que conversa com o leitor. Memórias póstumas de Brás Cubas (1881, marco), Dom Casmurro (dúvida sobre Capitu), Quincas Borba.","Determinismo (meio, raça, momento), personagens animalizados, temas patológicos, cortiços. Aluísio Azevedo: O cortiço.","Conceição Evaristo (escrevivência, mulher negra), Carolina Maria de Jesus (Quarto de despejo), literatura indígena, poesia marginal, slam e rap."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>aunque</b>?","alts":["careca","embora","agora","sobrenome"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>ahora</b>?","alts":["suposto","agora","pó, poeira","sobrenome"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Metonímia</b>?","alts":["Exagero (\"chorei rios de lágrimas\").","Troca por proximidade: autor pela obra, marca pelo produto, parte pelo todo.","Repetição de sons consonantais.","Dar características humanas a seres inanimados (\"o vento sussurrava\")."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Prosopopeia (personificação)</b>?","alts":["Atribuir características humanas a seres inanimados ou animais. \"O vento sussurrava.\"","Antítese: ideias opostas lado a lado (\"riso e choro\"). Paradoxo: ideias opostas que parecem impossíveis juntas (\"amor é fogo que arde sem se ver\").","Eufemismo: suaviza (\"ele partiu\" = morreu). Hipérbole: exagera (\"já te falei um milhão de vezes\").","Troca de um termo por outro com relação de proximidade: autor pela obra (\"li Machado\"), parte pelo todo, marca pelo produto (\"Bombril\")."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Função metalinguística</b>?","alts":["Foco no emissor: sentimentos, 1ª pessoa, interjeições.","Foco no assunto: informação objetiva (notícia).","Foco no código: a linguagem fala da própria linguagem.","Foco no canal: testar ou manter o contato."],"certa":2,"coment":"💡 METAlinguagem = a linguagem olhando no espelho."},{"enun":"Qual alternativa explica <b>cena</b>?","alts":["jantar","bêbada","ainda","sobrenome"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>mañana</b>?","alts":["delicioso","amanhã (ou manhã)","hoje","no entanto"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Realismo e Machado de Assis</b>?","alts":["Poesia reflexiva, ironia, \"gauche\", engajamento social (A rosa do povo, contra a guerra), cotidiano (\"No meio do caminho tinha uma pedra\").","Rapsódia de Mário de Andrade (1928), \"o herói sem nenhum caráter\". Mistura lendas, línguas e regiões em busca de uma identidade nacional.","1ª: nacionalista/indianista (Gonçalves Dias, \"Canção do exílio\"). 2ª: ultrarromântica, mal do século (Álvares de Azevedo). 3ª: condoreira, social, abolicionista (Castro Alves, \"O navio negreiro\").","Crítica social, análise psicológica, ironia, narrador que conversa com o leitor. Memórias póstumas de Brás Cubas (1881, marco), Dom Casmurro (dúvida sobre Capitu), Quincas Borba."],"certa":3,"coment":"💡 1881 = ano de Brás Cubas = começo do Realismo."},{"enun":"Qual alternativa explica <b>Antítese x paradoxo</b>?","alts":["Dizer o contrário do que se pensa, com intenção crítica ou humorística.","Antítese: ideias opostas lado a lado (\"riso e choro\"). Paradoxo: ideias opostas que parecem impossíveis juntas (\"amor é fogo que arde sem se ver\").","Aliteração: repetição de consoantes (\"o rato roeu a roupa do rei de Roma\"). Assonância: repetição de vogais.","Comparação usa conectivo (\"Ela é forte como uma rocha\"). Metáfora é comparação implícita (\"Ela é uma rocha\")."],"certa":1,"coment":"💡 ANTÍtese = opostos lado a lado. PARAdoxo = opostos na mesma coisa, \"parece impossível\"."},{"enun":"Qual alternativa explica <b>Cubismo</b>?","alts":["Anti-arte, acaso, deboche (Duchamp, \"A fonte\").","Formas geométricas e vários ângulos ao mesmo tempo (Picasso).","Sonho e inconsciente (Dalí).","Emoção e distorção (Munch, \"O grito\")."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>José de Alencar: principais obras</b>?","alts":["Clarice: fluxo de consciência, epifania, introspecção (A hora da estrela). Guimarães Rosa: sertão universal, neologismos (Grande sertão: veredas).","Indianistas (O Guarani, Iracema, Ubirajara), urbanas (Senhora, Lucíola), regionalistas (O gaúcho, O sertanejo). Idealização do índio como herói nacional.","1ª: nacionalista/indianista (Gonçalves Dias, \"Canção do exílio\"). 2ª: ultrarromântica, mal do século (Álvares de Azevedo). 3ª: condoreira, social, abolicionista (Castro Alves, \"O navio negreiro\").","Denúncia social do Nordeste: seca, miséria, coronelismo. Graciliano Ramos (Vidas secas, São Bernardo), Rachel de Queiroz (O quinze), Jorge Amado, José Lins do Rego."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Educação física no ENEM: temas comuns</b>?","alts":["Instalações, performance, arte conceitual, intervenção urbana, grafite: o conceito e a interação com o público importam mais que a técnica.","Práticas corporais como cultura, saúde x estética, padrões de beleza, esporte e inclusão, danças populares, capoeira, benefícios da atividade física.","Cubismo (Picasso, formas geométricas, múltiplos ângulos), Expressionismo (emoção, distorção, Munch), Surrealismo (sonho, inconsciente, Dalí), Futurismo (velocidade, máquinas), Dadaísmo (anti-arte, Duchamp).","Identifique o propósito comunicativo e o suporte (onde circula). O ENEM pergunta \"qual a finalidade\" do texto."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Função referencial</b>?","alts":["Foco no assunto: informação objetiva (notícia).","Foco no receptor: imperativo, vocativo, convencer.","Foco no código: a linguagem fala da própria linguagem.","Foco no canal: testar ou manter o contato."],"certa":0,"coment":"💡 Cada função = um elemento da comunicação: emissor-EMOTIVA, receptor-APELATIVA, mensagem-POÉTICA, referente-REFERENCIAL, canal-FÁTICA, código-METALINGUÍSTICA."},{"enun":"Qual alternativa explica <b>Falsos cognatos: \"apellido\", \"salada\", \"vaso\"</b>?","alts":["Apellido = sobrenome. Salada = salgada (ensalada = salada). Vaso = copo.","Embarazada = grávida. Exquisito = delicioso. Oficina = escritório.","Exprimir = espremer. Ganancia = lucro. Contestar = responder.","Rato = momento, instante. Polvo = pó, poeira. Borracha = bêbada (borrador = borracha)."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Falsos cognatos: \"rato\", \"polvo\", \"borracha\"</b>?","alts":["Rato = momento, instante. Polvo = pó, poeira. Borracha = bêbada (borrador = borracha).","Leia a pergunta primeiro, procure palavras transparentes e o contexto. A prova cobra interpretação, não gramática decorada. Atenção aos falsos cognatos.","Sin embargo = no entanto (adversativo). Aunque = embora, ainda que (concessivo).","Pelado = careca. Cola = rabo, fila. Zurdo = canhoto."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Função apelativa (conativa)</b>?","alts":["Tipos: narração, descrição, dissertação, injunção, exposição (estrutura). Gêneros: formas concretas de uso social (crônica, receita, notícia, charge, artigo de opinião).","Charge critica fato específico e datado, muitas vezes com personalidades. Cartum é atemporal e universal.","Considerar \"erradas\" ou inferiores as variedades não padrão. O ENEM defende adequação ao contexto, não \"certo\" x \"errado\".","Foco no receptor: convencer ou ordenar. Verbos no imperativo, vocativo, 2ª pessoa. Propagandas, discursos."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Arcadismo: características e autores</b>?","alts":["Bucolismo, \"fugere urbem\", \"carpe diem\", pastoralismo, simplicidade. Tomás Antônio Gonzaga (Marília de Dirceu), Cláudio Manuel da Costa. Ligado à Inconfidência Mineira.","Determinismo (meio, raça, momento), personagens animalizados, temas patológicos, cortiços. Aluísio Azevedo: O cortiço.","Clarice: fluxo de consciência, epifania, introspecção (A hora da estrela). Guimarães Rosa: sertão universal, neologismos (Grande sertão: veredas).","Crítica social, análise psicológica, ironia, narrador que conversa com o leitor. Memórias póstumas de Brás Cubas (1881, marco), Dom Casmurro (dúvida sobre Capitu), Quincas Borba."],"certa":0,"coment":"💡 Arcadismo = \"fugir para o campo\" (fugere urbem) e \"aproveitar o dia\" (carpe diem)."},{"enun":"Qual alternativa explica <b>todavía</b>?","alts":["grávida","suposto","ainda","careca"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Geração de 1930 (romance regionalista)</b>?","alts":["1ª: nacionalista/indianista (Gonçalves Dias, \"Canção do exílio\"). 2ª: ultrarromântica, mal do século (Álvares de Azevedo). 3ª: condoreira, social, abolicionista (Castro Alves, \"O navio negreiro\").","Denúncia social do Nordeste: seca, miséria, coronelismo. Graciliano Ramos (Vidas secas, São Bernardo), Rachel de Queiroz (O quinze), Jorge Amado, José Lins do Rego.","Poesia reflexiva, ironia, \"gauche\", engajamento social (A rosa do povo, contra a guerra), cotidiano (\"No meio do caminho tinha uma pedra\").","Rapsódia de Mário de Andrade (1928), \"o herói sem nenhum caráter\". Mistura lendas, línguas e regiões em busca de uma identidade nacional."],"certa":1,"coment":"💡 Romance de 30 = SECA e NORDESTE (Vidas secas, O quinze)."},{"enun":"Qual alternativa explica <b>Memórias póstumas de Brás Cubas</b>?","alts":["Tomás Antônio Gonzaga (Arcadismo)","Guimarães Rosa (Geração de 45)","Machado de Assis (Realismo)","Lima Barreto (Pré-Modernismo)"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Função emotiva</b>?","alts":["Foco no emissor: sentimentos, 1ª pessoa, interjeições.","Foco no receptor: imperativo, vocativo, convencer.","Foco no código: a linguagem fala da própria linguagem.","Foco na forma da mensagem: ritmo, sonoridade, jogo de palavras."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>embarazada</b>?","alts":["grávida","talvez","ainda","ontem"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Função poética</b>?","alts":["Identifique o propósito comunicativo e o suporte (onde circula). O ENEM pergunta \"qual a finalidade\" do texto.","Considerar \"erradas\" ou inferiores as variedades não padrão. O ENEM defende adequação ao contexto, não \"certo\" x \"errado\".","Foco na mensagem e na sua forma: sonoridade, ritmo, jogos de palavras. Poemas, slogans criativos.","Foco na informação, no assunto. Linguagem objetiva. Notícias, textos científicos, verbetes."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>vaso</b>?","alts":["bêbada","copo","ainda","pular"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>O cortiço</b>?","alts":["Mário de Andrade (Modernismo, 1ª fase)","João Cabral de Melo Neto","Clarice Lispector (Geração de 45)","Aluísio Azevedo (Naturalismo)"],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Romantismo: as três gerações na poesia</b>?","alts":["1ª: nacionalista/indianista (Gonçalves Dias, \"Canção do exílio\"). 2ª: ultrarromântica, mal do século (Álvares de Azevedo). 3ª: condoreira, social, abolicionista (Castro Alves, \"O navio negreiro\").","Rapsódia de Mário de Andrade (1928), \"o herói sem nenhum caráter\". Mistura lendas, línguas e regiões em busca de uma identidade nacional.","Clarice: fluxo de consciência, epifania, introspecção (A hora da estrela). Guimarães Rosa: sertão universal, neologismos (Grande sertão: veredas).","Poesia racional, \"antilírica\", concreta. Morte e vida severina: retirante nordestino."],"certa":0,"coment":"💡 \"Índio, Morte, Escravo\": 1ª indianista, 2ª ultrarromântica (mal do século), 3ª condoreira (abolicionista)."},{"enun":"Qual alternativa explica <b>Semana de Arte Moderna de 1922</b>?","alts":["Denúncia social do Nordeste: seca, miséria, coronelismo. Graciliano Ramos (Vidas secas, São Bernardo), Rachel de Queiroz (O quinze), Jorge Amado, José Lins do Rego.","Indianistas (O Guarani, Iracema, Ubirajara), urbanas (Senhora, Lucíola), regionalistas (O gaúcho, O sertanejo). Idealização do índio como herói nacional.","Bucolismo, \"fugere urbem\", \"carpe diem\", pastoralismo, simplicidade. Tomás Antônio Gonzaga (Marília de Dirceu), Cláudio Manuel da Costa. Ligado à Inconfidência Mineira.","Em São Paulo, ruptura com a arte acadêmica. Oswald de Andrade, Mário de Andrade, Anita Malfatti, Di Cavalcanti, Villa-Lobos. Valorização da cultura brasileira e linguagem coloquial."],"certa":3,"coment":"💡 1922 = centenário da Independência: \"independência cultural\"."},{"enun":"Qual alternativa explica <b>quizás</b>?","alts":["talvez","no entanto","jantar","pó, poeira"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Estratégia para a prova de espanhol</b>?","alts":["Apellido = sobrenome. Salada = salgada (ensalada = salada). Vaso = copo.","Leia a pergunta primeiro, procure palavras transparentes e o contexto. A prova cobra interpretação, não gramática decorada. Atenção aos falsos cognatos.","Embarazada = grávida. Exquisito = delicioso. Oficina = escritório.","Rato = momento, instante. Polvo = pó, poeira. Borracha = bêbada (borrador = borracha)."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>\"Sin embargo\" e \"aunque\"</b>?","alts":["Sin embargo = no entanto (adversativo). Aunque = embora, ainda que (concessivo).","Mientras = enquanto. Luego = depois, logo. Todavía = ainda.","Muy antes de adjetivo e advérbio (muy bonito). Mucho antes de substantivo ou depois de verbo (mucho dinero, trabaja mucho).","Exprimir = espremer. Ganancia = lucro. Contestar = responder."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Ironia</b>?","alts":["Eufemismo: suaviza (\"ele partiu\" = morreu). Hipérbole: exagera (\"já te falei um milhão de vezes\").","Troca de um termo por outro com relação de proximidade: autor pela obra (\"li Machado\"), parte pelo todo, marca pelo produto (\"Bombril\").","Dizer o contrário do que se pensa, com intenção crítica ou humorística.","Atribuir características humanas a seres inanimados ou animais. \"O vento sussurrava.\""],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Pré-Modernismo: autores e temas</b>?","alts":["Em São Paulo, ruptura com a arte acadêmica. Oswald de Andrade, Mário de Andrade, Anita Malfatti, Di Cavalcanti, Villa-Lobos. Valorização da cultura brasileira e linguagem coloquial.","Retrato do Brasil real e problemas sociais. Euclides da Cunha (Os sertões, Canudos), Lima Barreto (Triste fim de Policarpo Quaresma), Monteiro Lobato (Jeca Tatu), Augusto dos Anjos.","Determinismo (meio, raça, momento), personagens animalizados, temas patológicos, cortiços. Aluísio Azevedo: O cortiço.","Conflito fé x prazer, cultismo (jogo de palavras) e conceptismo (jogo de ideias), antíteses. Gregório de Matos (\"Boca do Inferno\", sátira) e Padre Antônio Vieira (sermões)."],"certa":1,"coment":""},{"enun":"Complete: \"Li Machado de Assis inteiro\" é exemplo de _____ (autor pela obra).","alts":["metonímia","comparação","Oswald de Andrade","metáfora"],"certa":0,"coment":"\"Li Machado de Assis inteiro\" é exemplo de <b>metonímia</b> (autor pela obra)."},{"enun":"Qual alternativa explica <b>Os sertões</b>?","alts":["Lima Barreto (Pré-Modernismo)","Euclides da Cunha (Pré-Modernismo, Canudos)","Aluísio Azevedo (Naturalismo)","Castro Alves (Romantismo, 3ª geração, condoreira)"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>presunto</b>?","alts":["no entanto","talvez","suposto","embora"],"certa":2,"coment":""},{"enun":"Complete: A Semana de Arte Moderna ocorreu em _____, em São Paulo.","alts":["1881","Oswald de Andrade","Tarsila do Amaral","1922"],"certa":3,"coment":"A Semana de Arte Moderna ocorreu em <b>1922</b>, em <b>São Paulo</b>."},{"enun":"Certo ou errado? O ENEM considera \"errado\" o uso de variedades regionais da língua.","alts":["Certo","Errado"],"certa":1,"coment":"O ENEM valoriza a variação linguística e combate o preconceito linguístico: o critério é a adequação ao contexto."},{"enun":"Qual alternativa explica <b>A hora da estrela</b>?","alts":["Carolina Maria de Jesus","Lima Barreto (Pré-Modernismo)","Aluísio Azevedo (Naturalismo)","Clarice Lispector (Geração de 45)"],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Função referencial (denotativa)</b>?","alts":["Foco no canal: testar ou manter contato. \"Alô?\", \"Tá me ouvindo?\", \"Né?\".","Tipos: narração, descrição, dissertação, injunção, exposição (estrutura). Gêneros: formas concretas de uso social (crônica, receita, notícia, charge, artigo de opinião).","Paródia: retoma o texto com subversão, humor ou crítica. Paráfrase: reescreve mantendo o sentido original.","Foco na informação, no assunto. Linguagem objetiva. Notícias, textos científicos, verbetes."],"certa":3,"coment":"💡 Cada função = um elemento da comunicação: emissor-EMOTIVA, receptor-APELATIVA, mensagem-POÉTICA, referente-REFERENCIAL, canal-FÁTICA, código-METALINGUÍSTICA."},{"enun":"Qual alternativa explica <b>O que é preconceito linguístico</b>?","alts":["Foco na mensagem e na sua forma: sonoridade, ritmo, jogos de palavras. Poemas, slogans criativos.","Foco no canal: testar ou manter contato. \"Alô?\", \"Tá me ouvindo?\", \"Né?\".","Tipos: narração, descrição, dissertação, injunção, exposição (estrutura). Gêneros: formas concretas de uso social (crônica, receita, notícia, charge, artigo de opinião).","Considerar \"erradas\" ou inferiores as variedades não padrão. O ENEM defende adequação ao contexto, não \"certo\" x \"errado\"."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>apellido</b>?","alts":["hoje","sobrenome","agora","desenvolvimento"],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Grande sertão: veredas</b>?","alts":["Rachel de Queiroz (Geração de 30)","Castro Alves (Romantismo, 3ª geração, condoreira)","João Cabral de Melo Neto","Guimarães Rosa (Geração de 45)"],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Triste fim de Policarpo Quaresma</b>?","alts":["Mário de Andrade (Modernismo, 1ª fase)","Castro Alves (Romantismo, 3ª geração, condoreira)","Lima Barreto (Pré-Modernismo)","Guimarães Rosa (Geração de 45)"],"certa":2,"coment":""},{"enun":"Complete: \"Ela é uma flor\" é _____; \"ela é bela como uma flor\" é comparação.","alts":["metonímia","São Paulo","metáfora","Memórias póstumas de Brás Cubas"],"certa":2,"coment":"\"Ela é uma flor\" é <b>metáfora</b>; \"ela é bela como uma flor\" é <b>comparação</b>."},{"enun":"Qual alternativa explica <b>Carlos Drummond de Andrade</b>?","alts":["Retrato do Brasil real e problemas sociais. Euclides da Cunha (Os sertões, Canudos), Lima Barreto (Triste fim de Policarpo Quaresma), Monteiro Lobato (Jeca Tatu), Augusto dos Anjos.","Poesia reflexiva, ironia, \"gauche\", engajamento social (A rosa do povo, contra a guerra), cotidiano (\"No meio do caminho tinha uma pedra\").","Manifesto Antropófago (1928): \"devorar\" a cultura estrangeira e transformá-la em algo brasileiro. \"Tupi or not tupi\". Abaporu, de Tarsila do Amaral.","Clarice: fluxo de consciência, epifania, introspecção (A hora da estrela). Guimarães Rosa: sertão universal, neologismos (Grande sertão: veredas)."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Eufemismo</b>?","alts":["Repetição de sons consonantais.","Dizer o contrário do que se pensa, com crítica ou humor.","Exagero (\"chorei rios de lágrimas\").","Suavização (\"ele nos deixou\" = morreu)."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Função fática</b>?","alts":["Foco no código: a linguagem fala da própria linguagem.","Foco no canal: testar ou manter o contato.","Foco na forma da mensagem: ritmo, sonoridade, jogo de palavras.","Foco no emissor: sentimentos, 1ª pessoa, interjeições."],"certa":1,"coment":"💡 FÁTICA = testa o FIO (canal): \"alô, tá me ouvindo?\"."},{"enun":"Qual alternativa explica <b>Falsos cognatos: \"pelado\", \"cola\", \"zurdo\"</b>?","alts":["Largo = comprido. Acordarse = lembrar-se. Brincar = pular.","Pelado = careca. Cola = rabo, fila. Zurdo = canhoto.","Taller = oficina (mecânica, ateliê). Cena = jantar. Presunto = suposto (jamón = presunto).","Embarazada = grávida. Exquisito = delicioso. Oficina = escritório."],"certa":1,"coment":""},{"enun":"Complete: O marco inicial do Realismo no Brasil é _____ (1881), de Machado de Assis.","alts":["São Paulo","Tarsila do Amaral","Memórias póstumas de Brás Cubas","Oswald de Andrade"],"certa":2,"coment":"O marco inicial do Realismo no Brasil é <b>Memórias póstumas de Brás Cubas</b> (<b>1881</b>), de Machado de Assis."},{"enun":"Qual alternativa explica <b>sin embargo</b>?","alts":["lembrar-se","delicioso","no entanto","hoje"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>polvo</b>?","alts":["pó, poeira","escritório","suposto","jantar"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>zurdo</b>?","alts":["bêbada","jantar","canhoto","escritório"],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>oficina</b>?","alts":["grávida","suposto","talvez","escritório"],"certa":3,"coment":""}]},"hum":{"tema":"Humanas","ic":"🌎","lista":[{"enun":"Complete: Contra a crise de 1929, os EUA aplicaram o _____, inspirado nas ideias de Keynes.","alts":["Lutero","Inglaterra","New Deal","indulgências"],"certa":2,"coment":"Contra a crise de 1929, os EUA aplicaram o <b>New Deal</b>, inspirado nas ideias de <b>Keynes</b>."},{"enun":"Em que ano ocorreu a Independência do Brasil?","alts":["1988","1822","1889","15h"],"certa":1,"coment":"Dom Pedro I."},{"enun":"Qual alternativa explica <b>Karl Marx</b>?","alts":["Ação social, tipos de dominação (legal, tradicional, carismática), burocracia, \"A ética protestante e o espírito do capitalismo\".","Etnocentrismo: julgar outras culturas pela sua, como superior. Relativismo: compreender cada cultura em seus próprios termos.","Taylorismo: tempos e movimentos, especialização. Fordismo: linha de montagem, produção em massa. Toyotismo: produção flexível, just in time, trabalhador multifuncional.","Luta de classes (burguesia x proletariado), mais-valia (exploração do trabalho não pago), alienação, materialismo histórico."],"certa":3,"coment":"💡 Marx = Mais-valia (M com M): o trabalhador produz mais do que recebe."},{"enun":"Qual alternativa explica <b>Conurbação</b>?","alts":["Cidades que crescem e se juntam fisicamente.","União de metrópoles (eixo Rio-São Paulo).","Migração do campo para a cidade.","Acúmulo de sedimentos no leito dos rios por causa da erosão."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Aristóteles</b>?","alts":["\"Só sei que nada sei\". Maiêutica (parto das ideias por perguntas) e ironia. Busca da verdade pelo diálogo; não deixou escritos.","Realismo, lógica, ética das virtudes (justo meio), \"o homem é um animal político\". Felicidade (eudaimonia) como fim.","Imperativo categórico: aja de modo que sua ação possa virar lei universal; trate as pessoas como fim, nunca só como meio. Esclarecimento: \"ouse saber\".","\"A existência precede a essência\": o ser humano é condenado a ser livre e responsável por suas escolhas."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Revolta da Vacina</b>?","alts":["Revolta messiânica na Bahia (Antônio Conselheiro), República Velha.","1789, elite contra a derrama; Tiradentes executado.","Rio, 1904, contra a vacinação obrigatória e as reformas urbanas.","1910, marinheiros contra castigos físicos (João Cândido)."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>\"Só sei que nada sei\"</b>?","alts":["Sócrates","Platão","Aristóteles","Maquiavel"],"certa":0,"coment":""},{"enun":"Complete: O Mercosul foi criado em _____ pelo Tratado de Assunção.","alts":["15","1850","1968","1991"],"certa":3,"coment":"O Mercosul foi criado em <b>1991</b> pelo Tratado de <b>Assunção</b>."},{"enun":"Qual alternativa explica <b>Revolução Industrial</b>?","alts":["Democracia direta, mas só para cidadãos: excluía mulheres, estrangeiros (metecos) e escravizados.","Inglaterra, século XVIII. Máquina a vapor, fábricas, êxodo rural, proletariado, jornadas longas, trabalho infantil. Reações: ludismo (quebra de máquinas), cartismo, sindicatos.","Quebra da bolsa de Nova York, superprodução. Resposta: New Deal (intervenção estatal, Keynes). No Brasil, derrubou o café e contribuiu para a Revolução de 1930.","Economia agrária, autossuficiente, sociedade estamental (clero, nobreza, servos), relações de suserania e vassalagem, poder da Igreja."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Massas de ar que atuam no Brasil</b>?","alts":["Rápida e desordenada (pós-1950, êxodo rural): favelização, segregação socioespacial, especulação imobiliária, mobilidade precária, enchentes.","Centros urbanos mais quentes que o entorno: asfalto, concreto, pouca vegetação e poluição retêm calor.","Queda da natalidade e da mortalidade → envelhecimento da população. Pirâmide com base mais estreita e topo mais largo; impacto na previdência.","Equatorial continental (mEc, quente e úmida, chuvas de verão), Polar atlântica (mPa, frentes frias e friagem), Tropical atlântica (mTa)."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Contratualistas: Hobbes, Locke, Rousseau</b>?","alts":["Crítica à moral cristã (\"moral de rebanho\"), \"Deus está morto\", vontade de potência, além-do-homem.","Racionalismo (Descartes): conhecimento vem da razão, \"penso, logo existo\". Empirismo (Locke, Hume): vem da experiência, mente como \"tábula rasa\".","Realismo, lógica, ética das virtudes (justo meio), \"o homem é um animal político\". Felicidade (eudaimonia) como fim.","Hobbes: estado de natureza é guerra de todos contra todos, Estado absoluto (Leviatã). Locke: direitos naturais (vida, liberdade, propriedade), direito de resistência. Rousseau: o homem nasce bom, a sociedade o corrompe; vontade geral."],"certa":3,"coment":"💡 Hobbes = Homem é lobo do homem (medo). Locke = Liberdade e propriedade. Rousseau = \"bom selvagem\"."},{"enun":"Complete: A Reforma Protestante começou em _____ com as 95 teses de Lutero, contra a venda de indulgências.","alts":["1850","1517","15","1968"],"certa":1,"coment":"A Reforma Protestante começou em <b>1517</b> com as 95 teses de <b>Lutero</b>, contra a venda de <b>indulgências</b>."},{"enun":"Qual alternativa explica <b>Ciclo do ouro e suas consequências</b>?","alts":["Canudos (messiânica, Bahia), Contestado (SC/PR), Revolta da Vacina (1904, RJ), Revolta da Chibata (1910, marinheiros), Tenentismo (anos 1920).","Mineira (1789): elite contra a derrama, Tiradentes executado. Baiana (1798): popular, com escravizados e alfaiates, defendia o fim da escravidão.","Séculos XVI e XVII, Nordeste (Pernambuco e Bahia). Plantation: latifúndio, monocultura, mão de obra escravizada africana, produção para exportação.","Século XVIII, Minas Gerais. Urbanização, deslocamento do eixo para o Sudeste, capital vai para o Rio (1763), impostos como o quinto e a derrama."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Cartismo</b>?","alts":["Movimento de operários que quebravam máquinas na Revolução Industrial.","Ajuda dos EUA para reconstruir a Europa ocidental no pós-guerra.","Plano de Roosevelt contra a crise de 1929, com intervenção estatal.","Movimento operário inglês por direitos políticos (voto)."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Imperativo categórico</b>?","alts":["Kant","Sócrates","Platão","Hobbes"],"certa":0,"coment":""},{"enun":"Complete: Linha de montagem e produção em massa caracterizam o _____; produção flexível e \"just in time\", o toyotismo.","alts":["tradicional","fordismo","legal","carismática"],"certa":1,"coment":"Linha de montagem e produção em massa caracterizam o <b>fordismo</b>; produção flexível e \"just in time\", o <b>toyotismo</b>."},{"enun":"Qual alternativa explica <b>Êxodo rural</b>?","alts":["União de metrópoles (eixo Rio-São Paulo).","Acúmulo de sedimentos no leito dos rios por causa da erosão.","Migração do campo para a cidade.","Cidades que crescem e se juntam fisicamente."],"certa":2,"coment":""},{"enun":"Complete: A Revolução Farroupilha (1835-1845) ocorreu no _____ e foi motivada pelos impostos sobre o charque.","alts":["café com leite","Rio Grande do Sul","Congresso","censura"],"certa":1,"coment":"A Revolução Farroupilha (1835-1845) ocorreu no <b>Rio Grande do Sul</b> e foi motivada pelos impostos sobre o <b>charque</b>."},{"enun":"Qual alternativa explica <b>Agronegócio x agricultura familiar</b>?","alts":["Vapor d'água da evapotranspiração da Amazônia levado por correntes de ar, que traz chuva ao Centro-Sul. Desmatamento ameaça esse fluxo.","Arenização: formação de areais em solo arenoso, por processo natural agravado pelo pisoteio do gado e monocultura (sudoeste do RS). Desertificação: degradação em áreas áridas e semiáridas (Nordeste).","Conurbação: cidades que crescem e se juntam. Megalópole: união de metrópoles (eixo Rio-São Paulo).","Agronegócio: grandes propriedades, mecanização, monocultura para exportação (soja, carne). Agricultura familiar: pequenas propriedades, produz grande parte do alimento consumido no país."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Ludismo</b>?","alts":["Movimento de operários que quebravam máquinas na Revolução Industrial.","Movimento operário inglês por direitos políticos (voto).","Plano de Roosevelt contra a crise de 1929, com intervenção estatal.","Ajuda dos EUA para reconstruir a Europa ocidental no pós-guerra."],"certa":0,"coment":""},{"enun":"Complete: Weber identificou três tipos de dominação: _____, tradicional e carismática.","alts":["toyotismo","fordismo","legal","Rio Grande do Sul"],"certa":2,"coment":"Weber identificou três tipos de dominação: <b>legal</b>, <b>tradicional</b> e <b>carismática</b>."},{"enun":"Qual alternativa explica <b>República Velha: política do café com leite e coronelismo</b>?","alts":["Eusébio de Queirós (1850, fim do tráfico), Ventre Livre (1871), Sexagenários (1885), Lei Áurea (1888). Lei de Terras (1850) dificultou o acesso à terra para ex-escravizados e imigrantes.","Revezamento SP e MG, política dos governadores, voto de cabresto (aberto), coronéis controlando eleitores.","Conduzida pela elite, manteve monarquia, escravidão e latifúndio. Dom Pedro I. Constituição de 1824 com Poder Moderador e voto censitário.","Séculos XVI e XVII, Nordeste (Pernambuco e Bahia). Plantation: latifúndio, monocultura, mão de obra escravizada africana, produção para exportação."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Plano Marshall</b>?","alts":["Movimento operário inglês por direitos políticos (voto).","Movimento de operários que quebravam máquinas na Revolução Industrial.","Ajuda dos EUA para reconstruir a Europa ocidental no pós-guerra.","Plano de Roosevelt contra a crise de 1929, com intervenção estatal."],"certa":2,"coment":""},{"enun":"Complete: O AI-5 foi decretado em _____ e foi o ato mais duro da ditadura: fechou o Congresso e ampliou a censura.","alts":["1968","1517","1850","1888"],"certa":0,"coment":"O AI-5 foi decretado em <b>1968</b> e foi o ato mais duro da ditadura: fechou o <b>Congresso</b> e ampliou a <b>censura</b>."},{"enun":"Qual alternativa explica <b>Canudos</b>?","alts":["Revolta messiânica na Bahia (Antônio Conselheiro), República Velha.","Rio, 1904, contra a vacinação obrigatória e as reformas urbanas.","1798, popular, defendia o fim da escravidão.","1789, elite contra a derrama; Tiradentes executado."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Urbanização brasileira: problemas</b>?","alts":["Agronegócio: grandes propriedades, mecanização, monocultura para exportação (soja, carne). Agricultura familiar: pequenas propriedades, produz grande parte do alimento consumido no país.","Queda da natalidade e da mortalidade → envelhecimento da população. Pirâmide com base mais estreita e topo mais largo; impacto na previdência.","Rápida e desordenada (pós-1950, êxodo rural): favelização, segregação socioespacial, especulação imobiliária, mobilidade precária, enchentes.","Mercator: conforme (preserva formas), distorce áreas perto dos polos (Europa grande), eurocêntrica. Peters: equivalente (preserva áreas), distorce formas."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>\"Rios voadores\"</b>?","alts":["Camada de ar frio fica presa embaixo de ar quente (comum em manhãs de inverno), impedindo a dispersão de poluentes nas cidades.","Vapor d'água da evapotranspiração da Amazônia levado por correntes de ar, que traz chuva ao Centro-Sul. Desmatamento ameaça esse fluxo.","Modernização agrícola a partir dos anos 1960: sementes melhoradas, fertilizantes, agrotóxicos e máquinas. Aumentou a produção, mas concentrou terras e causou impactos ambientais.","Conurbação: cidades que crescem e se juntam. Megalópole: união de metrópoles (eixo Rio-São Paulo)."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Projeções cartográficas: Mercator x Peters</b>?","alts":["Agronegócio: grandes propriedades, mecanização, monocultura para exportação (soja, carne). Agricultura familiar: pequenas propriedades, produz grande parte do alimento consumido no país.","Rápida e desordenada (pós-1950, êxodo rural): favelização, segregação socioespacial, especulação imobiliária, mobilidade precária, enchentes.","Centros urbanos mais quentes que o entorno: asfalto, concreto, pouca vegetação e poluição retêm calor.","Mercator: conforme (preserva formas), distorce áreas perto dos polos (Europa grande), eurocêntrica. Peters: equivalente (preserva áreas), distorce formas."],"certa":3,"coment":"💡 MERcator = conforMe (forma) e Europa grande. PETERS = Preserva árEa (equivalente)."},{"enun":"Qual alternativa explica <b>Blocos econômicos: Mercosul</b>?","alts":["Internos (endógenos): tectonismo, vulcanismo, terremotos (formam). Externos (exógenos): chuva, vento, rios, seres vivos (modelam, causam erosão).","Criado em 1991 (Tratado de Assunção): Brasil, Argentina, Uruguai, Paraguai (Bolívia em adesão). União aduaneira imperfeita.","Modernização agrícola a partir dos anos 1960: sementes melhoradas, fertilizantes, agrotóxicos e máquinas. Aumentou a produção, mas concentrou terras e causou impactos ambientais.","Vapor d'água da evapotranspiração da Amazônia levado por correntes de ar, que traz chuva ao Centro-Sul. Desmatamento ameaça esse fluxo."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Inconfidência Mineira x Conjuração Baiana</b>?","alts":["Revezamento SP e MG, política dos governadores, voto de cabresto (aberto), coronéis controlando eleitores.","Cabanagem (Pará), Balaiada (Maranhão), Sabinada (Bahia), Malês (escravizados muçulmanos, Bahia) e Farroupilha (RS, 1835-1845, estancieiros contra impostos sobre o charque).","\"Constituição Cidadã\": redemocratização, voto para analfabetos e maiores de 16 anos, SUS, racismo como crime inafiançável, direitos indígenas e quilombolas.","Mineira (1789): elite contra a derrama, Tiradentes executado. Baiana (1798): popular, com escravizados e alfaiates, defendia o fim da escravidão."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Renascimento</b>?","alts":["Inglaterra, século XVIII. Máquina a vapor, fábricas, êxodo rural, proletariado, jornadas longas, trabalho infantil. Reações: ludismo (quebra de máquinas), cartismo, sindicatos.","Séculos XIV a XVI, Itália. Humanismo, antropocentrismo, racionalismo, retomada da cultura greco-romana. Leonardo da Vinci, Michelangelo.","Partido único, culto ao líder, nacionalismo extremo, propaganda, anticomunismo, perseguição a minorias (Holocausto). Mussolini (Itália) e Hitler (Alemanha).","Razão contra o absolutismo. Locke (direitos naturais), Montesquieu (três poderes), Rousseau (contrato social, vontade geral), Voltaire (tolerância). Inspirou as revoluções liberais."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Max Weber</b>?","alts":["MST, movimentos negro, feminista, indígena, LGBTQIA+. \"Minoria\" é sobre falta de poder e representação, não sobre número.","Etnocentrismo: julgar outras culturas pela sua, como superior. Relativismo: compreender cada cultura em seus próprios termos.","Ação social, tipos de dominação (legal, tradicional, carismática), burocracia, \"A ética protestante e o espírito do capitalismo\".","Direitos civis (séc. XVIII), políticos (XIX) e sociais (XX). No Brasil, segundo José Murilo de Carvalho, a ordem foi invertida (sociais com Vargas antes dos políticos plenos)."],"certa":2,"coment":"💡 Weber = \"dominação\": legal, tradicional e carismática."},{"enun":"Qual alternativa explica <b>Revoltas do Período Regencial</b>?","alts":["Eusébio de Queirós (1850, fim do tráfico), Ventre Livre (1871), Sexagenários (1885), Lei Áurea (1888). Lei de Terras (1850) dificultou o acesso à terra para ex-escravizados e imigrantes.","Golpe de 1964, Atos Institucionais (AI-5 em 1968, o mais duro: censura, fechamento do Congresso), \"milagre econômico\", Lei da Anistia (1979), Diretas Já (1984).","Cabanagem (Pará), Balaiada (Maranhão), Sabinada (Bahia), Malês (escravizados muçulmanos, Bahia) e Farroupilha (RS, 1835-1845, estancieiros contra impostos sobre o charque).","Conduzida pela elite, manteve monarquia, escravidão e latifúndio. Dom Pedro I. Constituição de 1824 com Poder Moderador e voto censitário."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Primeira Guerra Mundial (1914-1918)</b>?","alts":["Causas: imperialismo, nacionalismo, alianças, corrida armamentista. Estopim: assassinato de Francisco Ferdinando. Tratado de Versalhes humilhou a Alemanha.","EUA (capitalismo) x URSS (socialismo), sem confronto direto: corrida armamentista e espacial, Plano Marshall, Muro de Berlim (1961-1989), guerras da Coreia e do Vietnã, crise dos mísseis em Cuba.","Lutero (1517, 95 teses contra a venda de indulgências). Calvinismo valorizou o trabalho e o lucro (Weber relaciona à ética capitalista). Contrarreforma: Concílio de Trento, Inquisição, jesuítas.","Potências europeias dividem África e Ásia (Conferência de Berlim, 1884-1885) em busca de matérias-primas e mercados. Justificativa: darwinismo social, \"fardo do homem branco\"."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Era Vargas: principais marcas</b>?","alts":["Cabanagem (Pará), Balaiada (Maranhão), Sabinada (Bahia), Malês (escravizados muçulmanos, Bahia) e Farroupilha (RS, 1835-1845, estancieiros contra impostos sobre o charque).","Fugindo de Napoleão. Abertura dos portos às nações amigas, criação do Banco do Brasil, imprensa régia; em 1815 o Brasil vira Reino Unido a Portugal.","\"Constituição Cidadã\": redemocratização, voto para analfabetos e maiores de 16 anos, SUS, racismo como crime inafiançável, direitos indígenas e quilombolas.","Revolução de 1930, Estado Novo (1937-1945, ditadura), CLT (1943), salário mínimo, voto feminino (1932), CSN e Petrobras (1953), populismo e propaganda (DIP)."],"certa":3,"coment":"💡 Vargas = \"pai dos pobres e mãe dos ricos\": deu direitos trabalhistas (CLT) e governou com autoritarismo."},{"enun":"Qual alternativa explica <b>Fato social e solidariedade orgânica</b>?","alts":["Max Weber","Karl Marx","Émile Durkheim","Julgar outras culturas a partir da própria, como se fosse superior."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Cidadania segundo T. H. Marshall</b>?","alts":["Mecânica: sociedades simples, semelhança entre indivíduos. Orgânica: sociedades complexas, divisão do trabalho e interdependência.","Direitos civis (séc. XVIII), políticos (XIX) e sociais (XX). No Brasil, segundo José Murilo de Carvalho, a ordem foi invertida (sociais com Vargas antes dos políticos plenos).","Taylorismo: tempos e movimentos, especialização. Fordismo: linha de montagem, produção em massa. Toyotismo: produção flexível, just in time, trabalhador multifuncional.","Luta de classes (burguesia x proletariado), mais-valia (exploração do trabalho não pago), alienação, materialismo histórico."],"certa":1,"coment":""},{"enun":"Certo ou errado? Para a sociologia, \"minoria\" significa sempre um grupo numericamente pequeno.","alts":["Certo","Errado"],"certa":1,"coment":"Minoria se refere a menos poder e representação. Mulheres e negros são maioria numérica no Brasil e são estudados como minorias."},{"enun":"Qual alternativa explica <b>Movimentos sociais e minorias no ENEM</b>?","alts":["MST, movimentos negro, feminista, indígena, LGBTQIA+. \"Minoria\" é sobre falta de poder e representação, não sobre número.","Ação social, tipos de dominação (legal, tradicional, carismática), burocracia, \"A ética protestante e o espírito do capitalismo\".","Luta de classes (burguesia x proletariado), mais-valia (exploração do trabalho não pago), alienação, materialismo histórico.","Etnocentrismo: julgar outras culturas pela sua, como superior. Relativismo: compreender cada cultura em seus próprios termos."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>\"Deus está morto\" / vontade de potência</b>?","alts":["Sartre","Nietzsche","Aristóteles","Hobbes"],"certa":1,"coment":""},{"enun":"Certo ou errado? Na democracia ateniense, todos os moradores da cidade podiam votar.","alts":["Certo","Errado"],"certa":1,"coment":"Só cidadãos homens livres nascidos em Atenas. Mulheres, estrangeiros (metecos) e escravizados estavam excluídos."},{"enun":"Qual alternativa explica <b>Crise de 1929</b>?","alts":["Inglaterra, século XVIII. Máquina a vapor, fábricas, êxodo rural, proletariado, jornadas longas, trabalho infantil. Reações: ludismo (quebra de máquinas), cartismo, sindicatos.","Potências europeias dividem África e Ásia (Conferência de Berlim, 1884-1885) em busca de matérias-primas e mercados. Justificativa: darwinismo social, \"fardo do homem branco\".","Quebra da bolsa de Nova York, superprodução. Resposta: New Deal (intervenção estatal, Keynes). No Brasil, derrubou o café e contribuiu para a Revolução de 1930.","Partido único, culto ao líder, nacionalismo extremo, propaganda, anticomunismo, perseguição a minorias (Holocausto). Mussolini (Itália) e Hitler (Alemanha)."],"certa":2,"coment":""},{"enun":"Qual alternativa explica <b>Alegoria da caverna</b>?","alts":["Platão","Hobbes","Descartes","Sócrates"],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Revoltas da Primeira República</b>?","alts":["Canudos (messiânica, Bahia), Contestado (SC/PR), Revolta da Vacina (1904, RJ), Revolta da Chibata (1910, marinheiros), Tenentismo (anos 1920).","Fugindo de Napoleão. Abertura dos portos às nações amigas, criação do Banco do Brasil, imprensa régia; em 1815 o Brasil vira Reino Unido a Portugal.","Séculos XVI e XVII, Nordeste (Pernambuco e Bahia). Plantation: latifúndio, monocultura, mão de obra escravizada africana, produção para exportação.","Conduzida pela elite, manteve monarquia, escravidão e latifúndio. Dom Pedro I. Constituição de 1824 com Poder Moderador e voto censitário."],"certa":0,"coment":""},{"enun":"Qual alternativa explica <b>Platão</b>?","alts":["O príncipe: separa política da moral; o governante precisa de virtù e fortuna. \"Melhor ser temido que amado\" se não puder ser ambos.","\"A existência precede a essência\": o ser humano é condenado a ser livre e responsável por suas escolhas.","Mundo das ideias (verdadeiro, eterno) x mundo sensível (cópias). Alegoria da caverna. A filosofia liberta da ignorância.","Adorno e Horkheimer: a cultura vira mercadoria padronizada, que aliena e massifica o público."],"certa":2,"coment":"💡 A caverna: sombras = senso comum; sair da caverna = filosofia."},{"enun":"Qual alternativa explica <b>Sartre (existencialismo)</b>?","alts":["\"Só sei que nada sei\". Maiêutica (parto das ideias por perguntas) e ironia. Busca da verdade pelo diálogo; não deixou escritos.","O príncipe: separa política da moral; o governante precisa de virtù e fortuna. \"Melhor ser temido que amado\" se não puder ser ambos.","\"A existência precede a essência\": o ser humano é condenado a ser livre e responsável por suas escolhas.","Crítica à moral cristã (\"moral de rebanho\"), \"Deus está morto\", vontade de potência, além-do-homem."],"certa":2,"coment":""},{"enun":"Certo ou errado? Um mapa de escala 1:1.000 tem escala menor que um de 1:1.000.000.","alts":["Certo","Errado"],"certa":1,"coment":"1:1.000 é escala MAIOR (mais detalhe). Quanto menor o denominador, maior a escala."},{"enun":"Qual alternativa explica <b>Agentes do relevo: internos x externos</b>?","alts":["Muito renovável em comparação com o mundo: hidrelétricas dominam a eletricidade; cana (etanol), eólica (Nordeste) e solar crescendo.","Internos (endógenos): tectonismo, vulcanismo, terremotos (formam). Externos (exógenos): chuva, vento, rios, seres vivos (modelam, causam erosão).","Camada de ar frio fica presa embaixo de ar quente (comum em manhãs de inverno), impedindo a dispersão de poluentes nas cidades.","Equatorial (Amazônia, quente e úmido), tropical (Brasil central, verão chuvoso e inverno seco), semiárido (sertão nordestino), tropical de altitude, subtropical (Sul, 4 estações, geadas)."],"certa":1,"coment":""},{"enun":"Complete: A Lei Eusébio de Queirós (_____) proibiu o tráfico; a Lei Áurea (1888) aboliu a escravidão.","alts":["1517","1968","15","1850"],"certa":3,"coment":"A Lei Eusébio de Queirós (<b>1850</b>) proibiu o tráfico; a Lei Áurea (<b>1888</b>) aboliu a escravidão."},{"enun":"Qual alternativa explica <b>Taylorismo, fordismo e toyotismo</b>?","alts":["Taylorismo: tempos e movimentos, especialização. Fordismo: linha de montagem, produção em massa. Toyotismo: produção flexível, just in time, trabalhador multifuncional.","Direitos civis (séc. XVIII), políticos (XIX) e sociais (XX). No Brasil, segundo José Murilo de Carvalho, a ordem foi invertida (sociais com Vargas antes dos políticos plenos).","Mecânica: sociedades simples, semelhança entre indivíduos. Orgânica: sociedades complexas, divisão do trabalho e interdependência.","MST, movimentos negro, feminista, indígena, LGBTQIA+. \"Minoria\" é sobre falta de poder e representação, não sobre número."],"certa":0,"coment":"💡 Ford = esteira (linha de montagem). Toyota = \"just in time\", estoque mínimo."},{"enun":"Qual alternativa explica <b>Sócrates</b>?","alts":["O príncipe: separa política da moral; o governante precisa de virtù e fortuna. \"Melhor ser temido que amado\" se não puder ser ambos.","\"A existência precede a essência\": o ser humano é condenado a ser livre e responsável por suas escolhas.","Hobbes: estado de natureza é guerra de todos contra todos, Estado absoluto (Leviatã). Locke: direitos naturais (vida, liberdade, propriedade), direito de resistência. Rousseau: o homem nasce bom, a sociedade o corrompe; vontade geral.","\"Só sei que nada sei\". Maiêutica (parto das ideias por perguntas) e ironia. Busca da verdade pelo diálogo; não deixou escritos."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Vinda da família real (1808)</b>?","alts":["Cabanagem (Pará), Balaiada (Maranhão), Sabinada (Bahia), Malês (escravizados muçulmanos, Bahia) e Farroupilha (RS, 1835-1845, estancieiros contra impostos sobre o charque).","Canudos (messiânica, Bahia), Contestado (SC/PR), Revolta da Vacina (1904, RJ), Revolta da Chibata (1910, marinheiros), Tenentismo (anos 1920).","Fugindo de Napoleão. Abertura dos portos às nações amigas, criação do Banco do Brasil, imprensa régia; em 1815 o Brasil vira Reino Unido a Portugal.","Revolução de 1930, Estado Novo (1937-1945, ditadura), CLT (1943), salário mínimo, voto feminino (1932), CSN e Petrobras (1953), populismo e propaganda (DIP)."],"certa":2,"coment":""},{"enun":"Em que ano caiu o Muro de Berlim?","alts":["1988","1989","15h","1889"],"certa":1,"coment":"Fim simbólico da Guerra Fria."},{"enun":"Em que ano foi promulgada a Constituição Cidadã?","alts":["1822","1988","15","1889"],"certa":1,"coment":"Redemocratização."},{"enun":"Qual alternativa explica <b>Conjuração Baiana</b>?","alts":["Revolta messiânica na Bahia (Antônio Conselheiro), República Velha.","1798, popular, defendia o fim da escravidão.","Rio, 1904, contra a vacinação obrigatória e as reformas urbanas.","1789, elite contra a derrama; Tiradentes executado."],"certa":1,"coment":""},{"enun":"Complete: Na República Velha, o revezamento entre SP e MG chamava-se política do _____; o controle de votos pelos coronéis, voto de cabresto.","alts":["Congresso","censura","Rio Grande do Sul","café com leite"],"certa":3,"coment":"Na República Velha, o revezamento entre SP e MG chamava-se política do <b>café com leite</b>; o controle de votos pelos coronéis, <b>voto de cabresto</b>."},{"enun":"Qual alternativa explica <b>Etnocentrismo</b>?","alts":["Entender cada cultura em seus próprios termos.","Émile Durkheim","Max Weber","Julgar outras culturas a partir da própria, como se fosse superior."],"certa":3,"coment":""},{"enun":"Qual alternativa explica <b>Racionalismo x empirismo</b>?","alts":["Mundo das ideias (verdadeiro, eterno) x mundo sensível (cópias). Alegoria da caverna. A filosofia liberta da ignorância.","\"Só sei que nada sei\". Maiêutica (parto das ideias por perguntas) e ironia. Busca da verdade pelo diálogo; não deixou escritos.","Racionalismo (Descartes): conhecimento vem da razão, \"penso, logo existo\". Empirismo (Locke, Hume): vem da experiência, mente como \"tábula rasa\".","\"A existência precede a essência\": o ser humano é condenado a ser livre e responsável por suas escolhas."],"certa":2,"coment":"💡 RACIOnalismo = RAzão (Descartes). EMPIRismo = EXPERIência (Locke, Hume)."},{"enun":"Qual alternativa explica <b>Escola de Frankfurt: indústria cultural</b>?","alts":["Imperativo categórico: aja de modo que sua ação possa virar lei universal; trate as pessoas como fim, nunca só como meio. Esclarecimento: \"ouse saber\".","Adorno e Horkheimer: a cultura vira mercadoria padronizada, que aliena e massifica o público.","\"Só sei que nada sei\". Maiêutica (parto das ideias por perguntas) e ironia. Busca da verdade pelo diálogo; não deixou escritos.","Realismo, lógica, ética das virtudes (justo meio), \"o homem é um animal político\". Felicidade (eudaimonia) como fim."],"certa":1,"coment":""},{"enun":"Qual alternativa explica <b>Arenização</b>?","alts":["Formação de areais em solos arenosos (sudoeste do RS), agravada pelo pisoteio do gado.","Cidades que crescem e se juntam fisicamente.","União de metrópoles (eixo Rio-São Paulo).","Migração do campo para a cidade."],"certa":0,"coment":""}]}};
